#[derive(Debug)]
struct Config {
    pid: Dword,
    dll: PathBuf,
    early_launch: Option<EarlyLaunchCli>,
    /// Optional production-owned G2 request loaded and authenticated before
    /// the selected game process is created. The collector is the sole D3D
    /// hook owner and receives this only over the early H4CT channel.
    g2_capture_intent: Option<recorder_host::early_render_launch::G2CaptureIntent>,
    /// Explicit diagnostic-only staged hook subset. This can never produce a
    /// replay and is valid only with `diagnostic_no_commit`.
    diagnostic_staged_hook_mask: Option<u64>,
    diagnostic_no_commit: bool,
    out_dir: PathBuf,
    duration_ms: u32,
    sample_ms: u32,
    dwell_ms: u64,
    min_game_hours: i32,
    scheduled_domains: Vec<String>,
    production: bool,
    /// Ordinary resident product capture has separate static-publication
    /// authority, but its replay persistence is still production binary:
    /// canonical H4CR plus replay_decoder H4IX/H4CP, never hourly JSON.
    product_auto_attach_runtime: bool,
    /// Debug-only fast-turnaround persistence. Seal and hash the raw H4CR,
    /// retain capture integrity/error telemetry, and deliberately skip every
    /// derived replay artifact. replay_decoder inspects H4CR directly on demand.
    raw_debug_output: bool,
    lightweight_root_frame: bool,
    special_projects_scan: bool,
    compact_country_frame: bool,
    division_body_bridge: Option<String>,
    special_projects_bridge: Option<String>,
    idea_group_filter: Option<String>,
    advisor_token_filter: Option<String>,
    capture_id: Option<String>,
    session_id: String,
    stream_format: StreamFormat,
    /// The coherent capture profile this run resolved to, if `--profile` was
    /// passed. `None` = legacy behavior (no preset applied). Surfaced verbatim in
    /// `collector_control.json` so the DLL can re-apply preset fallbacks for any
    /// field a control file leaves unset (same override semantics as the host).
    profile: Option<compact_contract::CaptureProfile>,
    /// Phase-timing sidecar logs (`collector_attach.jsonl`,
    /// `collector_compact_phase_timing.jsonl`). Pure instrumentation; profile-
    /// driven (debug on, production off). Never gates data-loss detection.
    sidecar_log: bool,
    /// Evidence-only A40 owner transaction. This enables exact-a729
    /// selected-designer and peace lifecycle hooks plus a raw sidecar receipt;
    /// it never schedules a production domain or authorizes replay activation.
    a40_evidence_capture: bool,
    /// Evidence-only A39 character-presentation owner transaction. This
    /// performs the exact same-launch A25 textbox baseline, installs the
    /// feature-gated A39 observers only after d47/d46 catalog publication,
    /// and writes CPR1/RTI1 fixture candidates without scheduling d82.
    a39_evidence_capture: bool,
    /// Evidence-only A36 selected-context ability refresh/tooltip observer.
    /// Raw pointer-bearing transactions are written to a diagnostic sidecar;
    /// this never schedules d88 or emits an ABL1/ABA2 production payload.
    a36_evidence_capture: bool,
    /// Evidence-only A34 owner transaction. The strict pointer-free supplement
    /// is copied into the authenticated collector control block; the injected
    /// owner still derives family/order/geometry/text/alerts and country DB id
    /// solely from the one-shot exact-a729 hook receipt.
    a34_evidence_supplement: Option<serde_json::Value>,
    extraction_perf_gate: bool,
    d53_emit_mode: D53EmitMode,
    d51_emit_mode: D51EmitMode,
    d41_emit_mode: D41EmitMode,
    d44_emit_mode: D44EmitMode,
    d48_emit_mode: D48EmitMode,
    /// d53 relation-flag reader path (offsets|scan|shadow). Written verbatim into
    /// the DLL control file; `offsets` (the default) preserves current behavior.
    /// `shadow` is the live-validation gate path.
    d53_relation_read_mode: D53RelationReadMode,
    /// Per-session d53 prefetch-distance overrides (relation pair loop / flat
    /// candidate loops), written into the DLL control file as
    /// `prefetch_dist_relation` / `prefetch_dist_candidates`. `None` = field is
    /// `null` = the lane keeps its env/default distances (relation 8,
    /// candidates 32). Control-file delivery exists because the env-var channel
    /// cannot reach an already-running game — required for the live prefetch
    /// A/B. Perf-only hint; never changes rows/bytes/errors.
    prefetch_dist_relation: Option<u32>,
    prefetch_dist_candidates: Option<u32>,
    /// Plan-v2 P2b lever A: bound the collector's per-frame reader fan-out to at
    /// most this many concurrently-running domain workers (0 = unbounded = legacy).
    /// Passed through the JSON control block to the injected DLL as
    /// `reader_concurrency`, the same channel as `extraction_perf_gate`.
    reader_concurrency: u32,
    /// M2 modset binding: explicit Paradox user dir (the one carrying
    /// `dlc_load.json`). `None` = probe the standard and OneDrive-redirected
    /// Documents locations; ambiguity fails the modset resolution closed (the
    /// manifest records the probe evidence either way, never a guess).
    pdx_user_dir: Option<PathBuf>,
    /// File-boundary storage encoding for collector_stream.bin. The decoded bytes
    /// remain the exact collector-emitted H4CR stream.
    stream_compression: compact_stream::StreamCompression,
    compression_profile: CompressionProfile,
    /// Optional pre-built static artifacts to pack into the production container.
    /// Each entry names a well-known artifact and the on-disk path to its JSON
    /// payload. Absent = not requested; the container still packs and records the
    /// absence (fail-closed, never fabricated). A present-but-unreadable path is a
    /// HARD error (never a silent skip).
    static_artifacts: Vec<StaticArtifactRequest>,
    /// Complete A27 live heap catalog captured for this recording. This is a
    /// session-specific live artifact, deliberately separate from domain 59's
    /// authored static definitions.
    design_catalog_live: Option<DesignCatalogLiveRequest>,
    /// Debug/recovery option: skip the host-side post-capture fold entirely.
    /// The resulting compact-only container is intentionally incomplete for
    /// standalone playback and remains fail-closed. Production/profile capture
    /// rejects this option because a portable `.battleplan` must contain indexed
    /// folded snapshots. Default false.
    skip_host_fold: bool,
    /// lane/hour-latch: enable the zero-skip hour-boundary latch in the injected
    /// DLL. Default false (legacy synchronous sample loop). When true, a dedicated
    /// latch thread polls only the hour counter and the heavy sweep is
    /// latch-triggered so no game-hour is silently skipped. Read-only, no game
    /// patching.
    hour_latch_enabled: bool,
    /// Latch poll period in ms (clamped 1..=25 in the DLL). Default 2 — well under
    /// the measured 28.2 ms min inter-hour interval.
    hour_latch_poll_ms: u32,
    /// Pending-hour ring capacity (clamped 1..=65535 in the DLL). Bounds latch
    /// memory and capture lag. Default 64.
    hour_latch_queue_cap: u32,
    /// Canonical eight-artifact bundle admission inputs. Mandatory for production
    /// and both coherent profiles; optional only for explicit legacy probes.
    static_bundle: Option<StaticBundleCli>,
    speed_root_gate_path: Option<PathBuf>,
    domain57_game_speed_transcript_file_sha256: Option<String>,
    domain57_game_speed_gate: Option<Value>,
    /// Parse-time authorization for the collector's exact-a729 native X12
    /// speed/pause observer when no external transcript gate is supplied.
    /// Carry this decision into `run_capture` so the later admission check
    /// cannot accidentally reject a product runtime that parse_args admitted.
    domain57_without_external_gate_authorized: bool,
    /// Feature-local omission authority. Domain 57 is removed from the effective
    /// schedule when its exact transcript-bound v2 gate pair was not supplied;
    /// unrelated FRAMEs remain admissible and no speed/pause value is invented.
    domain57_omission_reason: Option<&'static str>,
    /// Explicit acceptance-only mode. Absent by default and from every normal
    /// production invocation. The nonce is bound into collector control using
    /// the recorder-generated pipe token before the DLL is loaded.
    acceptance_test: Option<AcceptanceTestCli>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AcceptanceTestMode {
    SyntheticFault,
    Paused,
    SinkOpenFault,
    SinkWriteFault,
}

impl AcceptanceTestMode {
    fn parse(value: &str) -> Option<Self> {
        match value {
            "synthetic-fault" => Some(Self::SyntheticFault),
            "paused" => Some(Self::Paused),
            "sink-open-fault" => Some(Self::SinkOpenFault),
            "sink-write-fault" => Some(Self::SinkWriteFault),
            _ => None,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::SyntheticFault => "synthetic-fault",
            Self::Paused => "paused",
            Self::SinkOpenFault => "sink-open-fault",
            Self::SinkWriteFault => "sink-write-fault",
        }
    }

    fn is_sink_fault(self) -> bool {
        matches!(self, Self::SinkOpenFault | Self::SinkWriteFault)
    }
}

