/// Runtime override for the d53 (diplomacy/intel/operatives) relation-flag reader
/// path, mirrored verbatim into `collector_control.json` as `d53_relation_read_mode`.
/// The DLL defaults to `offsets` when the field is absent, so the shadow gate MUST
/// write an explicit value. `shadow` runs BOTH the offsets and legacy-scan paths and
/// fail-closes any mismatching frame as partial (surfaced as
/// `domain53_relation_shadow_mismatches` in the manifest).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum D53RelationReadMode {
    Offsets,
    Scan,
    Shadow,
}

impl D53RelationReadMode {
    fn parse(value: &str) -> Option<Self> {
        match value {
            "offsets" => Some(Self::Offsets),
            "scan" => Some(Self::Scan),
            "shadow" => Some(Self::Shadow),
            _ => None,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Offsets => "offsets",
            Self::Scan => "scan",
            Self::Shadow => "shadow",
        }
    }
}

#[derive(Debug, Default)]
struct Summary {
    frame_count: usize,
    collector_started_count: usize,
    raw_event_count: usize,
    raw_delta_count: usize,
    domains_seen: BTreeSet<String>,
    raw_domains_seen: BTreeSet<String>,
    scheduled_domain_frames: BTreeMap<String, usize>,
    unique_hours: Vec<i32>,
    first_hour: Option<i32>,
    last_hour: Option<i32>,
    skipped_hours: i32,
    control_errors: BTreeSet<String>,
    parse_errors: Vec<String>,
}

/// One status-origin ledger row (C1 stage A): the aggregated value (summed
/// count, or last raw word for `_sample` units) plus the first/last game hour
/// the unit was seen — enough to attribute a chronic bit from one manifest.
/// Hours are None until a REAL-clock observation arrives: a NO_CLOCK frame's
/// attribution record carries the sentinel hour and is counted in `no_clock`
/// instead of fabricating a calendar-hour-zero span (stage-A gate finding 3).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
struct StatusOriginAgg {
    value: u64,
    first_hour: Option<i32>,
    last_hour: Option<i32>,
    no_clock_observations: u64,
}

#[derive(Debug, Default)]
struct CompactSummary {
    record_count: usize,
    domain_perf_record_count: usize,
    domain_data_record_count: usize,
    frame_end_record_count: usize,
    total_bytes: usize,
    total_payload_bytes: usize,
    max_payload_len: usize,
    max_record_len: usize,
    domains_seen: BTreeSet<u16>,
    unfolded_domain_data: BTreeSet<u16>,
    per_domain: BTreeMap<u16, CompactDomainSummary>,
    frame_end_hour_counts: BTreeMap<i32, usize>,
    per_hour_perf_domain_counts: BTreeMap<i32, BTreeMap<u16, usize>>,
    per_hour_data_domain_counts: BTreeMap<i32, BTreeMap<u16, usize>>,
    frame_times_us: Vec<u64>,
    status_flags_or: u32,
    frame_end_status_flags_or: u32,
    unique_hours: Vec<i32>,
    first_hour: Option<i32>,
    last_hour: Option<i32>,
    skipped_hours: i32,
    late_records_after_frame_end: u64,
    ordering_errors: Vec<String>,
    parse_errors: Vec<String>,
    // Plan-v2 P2 read A/B probe: per-primitive read-counter aggregates carried
    // by the reserved probe domain (RC_PROBE_DOMAIN_ID). Kept OUT of per_domain /
    // domains_seen / domain_perf_record_count so the exact perf-count
    // verification gate is unaffected; surfaced as compact_stream.read_ab_probe.
    read_ab_probe: BTreeMap<String, u64>,
    // R2 bound-trip attribution: `bt_*` units on the probe domain record every
    // plausibility-bound trip (a modded save legitimately exceeding a
    // vanilla-tuned ceiling would otherwise CLAMP-DROP the field silently).
    // `*_trips` counters sum across frames; `*_raw_sample` units keep the LAST
    // observed raw value (summing destroys raw words). Kept OUT of per_domain /
    // domains_seen so the coverage/perf-count gates are unaffected; surfaced as
    // compact_stream.bound_trips. Nonzero on vanilla = a bug; nonzero on a
    // modded capture = the named bound needs raising for that modset (R3).
    bound_trips: BTreeMap<String, u64>,
    // C1 stage A status-origin incidence ledger: `so_*` units on the probe
    // domain name the FIRST-INTRODUCTION site (and cause) of every status bit
    // (C0_DOSSIERS.md ranked telemetry). Counters sum; `_sample` units keep
    // the last raw word; both carry first/last incidence hour. Kept OUT of
    // per_domain / domains_seen; surfaced as compact_stream.status_origins.
    status_origins: BTreeMap<String, StatusOriginAgg>,
    // Typed collector-control rejection reasons (`ci_*`) emitted on the
    // reserved probe domain. Kept separate from status origins so manifests do
    // not have to infer which authority field failed from one CONTROL_INVALID
    // bit.
    control_invalid_reasons: BTreeMap<String, StatusOriginAgg>,
    domain57_frames: Vec<Domain57FrameEvidence>,
    // lane/hour-latch: zero-skip hour-boundary latch accounting, carried by
    // `hl_*` diagnostic units on the reserved probe domain (250). Counters are
    // cumulative/monotonic and aggregate by MAX. Terminal/transient state
    // markers (`last_observe_failed` and `capture_barrier_active`) aggregate by
    // last value. Surfaced as `compact_stream.hour_latch`. Kept OUT of
    // per_domain / domains_seen so the coverage/perf-count gates are unaffected.
    hour_latch: BTreeMap<String, u64>,
    // Lane-wall counter (deep-war lever #5): per-frame per-lane wall +
    // critical-path aggregates carried by `lw_*` diagnostic units on the same
    // reserved probe domain. Also kept OUT of per_domain / gates; surfaced as
    // compact_stream.lane_wall. `lw_crit_wall_us` and `lw_l{n}_wall_us` arrive
    // once per frame, so the Vecs hold per-frame values (avg/p95/max).
    lane_wall_frames: u64,
    lane_wall_worker_span_us_total: u64,
    // F5 acceptance telemetry: exact per-frame prewarm cost and absolute
    // frame-label/current-hour skew samples emitted by the collector. Missing
    // skew reads are counted separately and make acceptance incomplete.
    acceptance_prewarm_times_us: Vec<u64>,
    acceptance_hour_label_skew_abs: Vec<u64>,
    acceptance_hour_label_skew_missing: u64,
    lane_wall_crit_walls_us: Vec<u64>,
    lane_wall_crit_busy_us_total: u64,
    lane_wall_main_wall_us_total: u64,
    lane_wall_other_wall_us_total: u64,
    lane_wall_per_lane_walls_us: BTreeMap<u16, Vec<u64>>,
    lane_wall_per_lane_busy_us_total: BTreeMap<u16, u64>,
    lane_wall_domain_crit_us_total: BTreeMap<u16, u64>,
    // Applied prefetch-distance provenance from the stream (lw_prefetch_dist_*
    // units). None = stream predates the units. This is what the DLL actually
    // used, unlike the requested values echoed from host config. The `mixed`
    // flags trip when two frames carried DIFFERENT values — then the applied
    // value is withheld (a mixed session has no single arm label and must not
    // fabricate one by max/min).
    lane_wall_prefetch_dist_relation_applied: Option<u64>,
    lane_wall_prefetch_dist_relation_mixed: bool,
    lane_wall_prefetch_dist_candidates_applied: Option<u64>,
    lane_wall_prefetch_dist_candidates_mixed: bool,
    // W12C campaign identity: the identity-candidate observation accumulated from
    // the decoded d68 session_header_live records (last-value-wins witnesses;
    // game_unique_id/seed stay None until an offset-proven collector sources them
    // — see recorder_host::campaign_identity). Consumed at manifest-build time to
    // bind the fail-closed `campaign_identity` object. Default = no rows observed
    // (unbound). Kept OUT of per_domain / gates.
    session_header_identity: recorder_host::campaign_identity::SessionHeaderIdentityObservation,
    // W15 IdentityV1 authority retained only from the stateful stream validator.
    // This opaque token is the sole path allowed to mint manifest `Known`;
    // parallel d68 fields and asserted hashes remain non-authoritative.
    validated_cid1: Option<compact_contract::campaign_identity::ValidatedCid1>,
}

#[derive(Debug, Default)]
struct CompactDomainSummary {
    record_count: usize,
    data_record_count: usize,
    row_count_total: u64,
    changed_rows_total: u64,
    data_rows_total: u64,
    data_changed_rows_total: u64,
    data_units_total: BTreeMap<String, u64>,
    unit_count_total: u64,
    changed_unit_count_total: u64,
    read_times_us: Vec<u64>,
    max_read_time_us: u64,
    status_flags_or: u32,
    effective_failure_status_flags_or: u32,
    expected_partial_tolerance_hours: BTreeSet<i32>,
    problems: BTreeMap<String, u64>,
    /// Exact framed and payload bytes attributed to this domain across PERF +
    /// DATA records. Probe and FRAME_END bytes remain top-level overhead.
    record_bytes_total: u64,
    payload_bytes_total: u64,
    max_record_bytes: u64,
}

fn add_compact_global_status_flags(
    summary: &mut CompactSummary,
    domain_id: u16,
    status_flags: u32,
) {
    summary.status_flags_or |=
        compact_contract::compact_status_for_global_interpretation(domain_id, status_flags);
}

fn compact_domain_status_flags_scope(domain_id: u16) -> &'static str {
    if compact_contract::lane_local_status_mask(domain_id) == 0 {
        "global"
    } else {
        "raw_global_plus_lane_local"
    }
}

fn compact_status_has_expected_partial_tolerance(domain_id: u16, status_flags: u32) -> bool {
    compact_contract::expected_partial_tolerance_applies(domain_id, status_flags).is_some()
}

fn compact_domain_effective_failure_flags(domain_id: u16, status_flags: u32) -> u32 {
    compact_contract::compact_status_failure_flags_after_expected_partial_tolerance(
        domain_id,
        status_flags,
    )
}

fn merge_domain_data_authority(
    summary: &mut CompactSummary,
    domain_id: u16,
    game_hour_raw: i32,
    result: Result<DomainDataAuthority, DomainDataError>,
) {
    let authority = match result {
        Ok(authority) => authority,
        Err(error) => {
            summary.parse_errors.extend(error.errors);
            error.partial_authority
        }
    };
    let DomainDataAuthority {
        status_flags,
        emitted_rows,
        changed_rows,
        data_units,
        problems,
        auxiliary,
    } = authority;
    if let Some(status_flags) = status_flags {
        add_compact_global_status_flags(summary, domain_id, status_flags);
        if let Some(domain) = summary.per_domain.get_mut(&domain_id) {
            domain.status_flags_or |= status_flags;
            domain.effective_failure_status_flags_or |=
                compact_domain_effective_failure_flags(domain_id, status_flags);
            if compact_status_has_expected_partial_tolerance(domain_id, status_flags) {
                domain
                    .expected_partial_tolerance_hours
                    .insert(game_hour_raw);
            }
        }
    }
    if let Some(domain) = summary.per_domain.get_mut(&domain_id) {
        domain.data_rows_total = domain.data_rows_total.saturating_add(emitted_rows);
        domain.data_changed_rows_total =
            domain.data_changed_rows_total.saturating_add(changed_rows);
        for (name, count) in data_units {
            let entry = domain.data_units_total.entry(name).or_default();
            *entry = entry.saturating_add(count);
        }
        for (name, count) in problems {
            let entry = domain.problems.entry(name).or_default();
            *entry = entry.saturating_add(count);
        }
    }
    if let Some(frame) = auxiliary.domain57_frame {
        summary.domain57_frames.push(frame);
    }
}

fn main() {
    #[cfg(not(test))]
    {
        let raw_args = std::env::args_os().skip(1).collect::<Vec<_>>();
        if replay_prefold_worker::is_internal_invocation(&raw_args) {
            if let Err(error) = replay_prefold_worker::run(raw_args) {
                eprintln!("recorder internal prefold worker: {error}");
                std::process::exit(2);
            }
            return;
        }
    }
    let product_launch = std::env::args_os().nth(1).is_none();
    #[cfg(windows)]
    let cli_has_console = product_launch || attach_parent_console_for_cli();
    #[cfg(windows)]
    let supervised_worker = std::env::var_os(
        recorder_host::auto_attach::proof::WORKER_PROOF_PATH_ENV,
    )
    .is_some();
    if let Err(err) = run() {
        #[cfg(windows)]
        if product_launch || should_show_cli_error(cli_has_console, supervised_worker) {
            recorder_host::auto_attach::product_runtime::show_product_error(&err);
        } else {
            eprintln!("collector_record: {err}");
        }
        #[cfg(not(windows))]
        eprintln!("collector_record: {err}");
        std::process::exit(1);
    }
}

#[cfg(windows)]
fn attach_parent_console_for_cli() -> bool {
    #[link(name = "kernel32")]
    extern "system" {
        fn AttachConsole(process_id: u32) -> i32;
        fn GetConsoleWindow() -> *mut std::ffi::c_void;
    }
    const ATTACH_PARENT_PROCESS: u32 = u32::MAX;
    // A piped worker already has authoritative standard handles; attaching can
    // legitimately report ERROR_ACCESS_DENIED when a console is already bound.
    unsafe {
        AttachConsole(ATTACH_PARENT_PROCESS);
        !GetConsoleWindow().is_null()
    }
}

#[cfg(windows)]
fn should_show_cli_error(has_console: bool, supervised_worker: bool) -> bool {
    !has_console && !supervised_worker
}

/// Resident support/acceptance entry for the dual-order auto-attach supervisor
/// (roadmap task #36; design `extractor/documents/AUTO_ATTACH_DESIGN.md`). The
/// full supervisor/coordinator logic lives in the `recorder_host::auto_attach`
/// module (unit-tested with fakes); this is just the CLI seam that wires the
/// real Windows adapters and runs the loop. The installed product resolves its
/// collector payload beside this executable; `--dll` remains a support override.
/// Console/session close signals enter coordinator-owned stop handling. The
/// Product workers use the paired duplex backend, durable status stream,
/// cooperative stop, bounded H4CR drain, and verified finalization.
#[cfg(windows)]
fn run_auto_attach(args: &[String]) -> Result<(), String> {
    use recorder_host::auto_attach::{run_supervisor, SupervisorOptions};
    use std::path::PathBuf;

    let mut source_dll: Option<PathBuf> = None;
    let mut staging_root: Option<PathBuf> = None;
    let mut out_root: Option<PathBuf> = None;
    let mut journal_path: Option<PathBuf> = None;
    let mut worker_extra_args: Vec<String> = Vec::new();
    let mut poll_ms: u64 = 2_000;
    let mut require_visible_window = true;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--dll" => {
                i += 1;
                source_dll = Some(PathBuf::from(args.get(i).ok_or("--dll needs a value")?));
            }
            "--staging-root" => {
                i += 1;
                staging_root = Some(PathBuf::from(
                    args.get(i).ok_or("--staging-root needs a value")?,
                ));
            }
            "--out-root" => {
                i += 1;
                out_root = Some(PathBuf::from(
                    args.get(i).ok_or("--out-root needs a value")?,
                ));
            }
            "--journal" => {
                i += 1;
                journal_path = Some(PathBuf::from(args.get(i).ok_or("--journal needs a value")?));
            }
            "--poll-ms" => {
                i += 1;
                poll_ms = args
                    .get(i)
                    .ok_or("--poll-ms needs a value")?
                    .parse()
                    .map_err(|e| format!("--poll-ms: {e}"))?;
            }
            "--allow-headless-target" => require_visible_window = false,
            "--worker-arg" => {
                i += 1;
                worker_extra_args.push(args.get(i).ok_or("--worker-arg needs a value")?.clone());
            }
            other => return Err(format!("auto-attach: unknown arg {other:?}")),
        }
        i += 1;
    }

    let out_root = match out_root {
        Some(path) => path,
        None => recorder_host::auto_attach::product_runtime::default_product_data_root()?,
    };
    let staging_root = staging_root.unwrap_or_else(|| out_root.join("staging"));
    let journal_path = journal_path.unwrap_or_else(|| out_root.join("auto_attach_journal.jsonl"));
    let worker_exe = std::env::current_exe().map_err(|e| format!("current_exe: {e}"))?;
    let source_dll = recorder_host::auto_attach::product_runtime::resolve_packaged_collector_dll(
        source_dll,
        &worker_exe,
    )?;
    let graceful_stop =
        recorder_host::auto_attach::product_runtime::GracefulStopRegistration::install()?;

    let opts = SupervisorOptions {
        source_dll,
        staging_root,
        out_root,
        journal_path,
        worker_exe,
        worker_extra_args,
        require_visible_window,
        poll_ms,
    };
    run_supervisor(opts, || graceful_stop.is_requested())
}

/// Ordinary end-user entry. The packaged recorder executable owns both the
/// visible desktop window and the resident supervisor, so the distribution
/// needs no launcher, tray process, service, installer, or administrator access.
/// Closing the window transfers stop ownership to the coordinator and waits for
/// worker finalization before returning.
#[cfg(windows)]
fn product_auto_attach_runtime_domain_names() -> Vec<&'static str> {
    let mut domains = compact_contract::production_profile_scheduled_names();
    let speed_pause_domain =
        compact_contract::wire_name_for_id(session_multiplayer_metadata_live::DOMAIN_ID)
            .expect("assigned domain 57 must have a canonical wire name");
    if !domains.contains(&speed_pause_domain) {
        domains.push(speed_pause_domain);
    }
    domains
}

#[cfg(windows)]
fn product_auto_attach_worker_args(raw_debug_output: bool) -> Vec<String> {
    // The desktop product must never inherit the collector's empty-schedule
    // compatibility fallback (domains 10..=17).  That fallback is useful for
    // narrow probes, but it made an apparently verified auto-attach recording
    // exercise only eight domains.
    //
    // Do not pass `--profile production` here.  That profile additionally
    // requires a process-bound, pre-injection static bundle.  The ordinary
    // late-attach product cannot fabricate or rebind that evidence.  Instead,
    // select the exact shared production runtime roster and the lean runtime
    // settings explicitly.  Static-content publication remains a separate
    // fail-closed gate; runtime data capture no longer silently shrinks.
    let mut args = Vec::new();
    for domain in product_auto_attach_runtime_domain_names() {
        args.push("--scheduled-domain".to_string());
        args.push(domain.to_string());
    }
    args.extend(
        [
            "--product-auto-attach-runtime",
            "--hour-latch",
            "--compact-country-frame",
            "--extraction-perf-gate",
            "--sample-ms",
            "1",
            "--min-game-hours",
            "48",
            "--reader-concurrency",
            "12",
        ]
        .into_iter()
        .map(str::to_string),
    );
    if raw_debug_output {
        args.push("--raw-debug-output".to_string());
    }
    args
}

#[cfg(windows)]
fn run_product_auto_attach(raw_debug_output: bool) -> Result<(), String> {
    use recorder_host::auto_attach::{run_supervisor_with_events, SupervisorOptions};

    let worker_exe = std::env::current_exe().map_err(|e| format!("current_exe: {e}"))?;
    let source_dll = recorder_host::auto_attach::product_runtime::resolve_packaged_collector_dll(
        None,
        &worker_exe,
    )?;
    let out_root = recorder_host::auto_attach::product_runtime::default_product_data_root()?;
    let recordings_root = out_root.clone();
    let opts = SupervisorOptions {
        source_dll,
        staging_root: out_root.join("staging"),
        journal_path: out_root.join("auto_attach_journal.jsonl"),
        out_root,
        worker_exe,
        worker_extra_args: product_auto_attach_worker_args(raw_debug_output),
        // Headless capture cannot wait for a window: several production lanes
        // install one-shot setup observers that must be resident before the
        // first PID-owned window is created. Exact exe/SHA/session/SID identity
        // is re-probed immediately before the durable single-injection commit.
        require_visible_window: false,
        // The coordinator advances one fail-closed state transition per tick.
        // Keep the ordinary resident path responsive enough to attach while
        // launch-time setup is still in progress.
        poll_ms: 50,
    };
    recorder_host::auto_attach::product_runtime::run_product_window(
        recordings_root,
        move |stop, report_event| {
            run_supervisor_with_events(
                opts,
                || stop.load(std::sync::atomic::Ordering::Acquire),
                move |event| report_event(event),
            )
        },
    )
}

#[cfg(not(windows))]
fn run_auto_attach(_args: &[String]) -> Result<(), String> {
    Err("auto-attach is only supported on Windows".to_string())
}

fn absolute_g2_output_directory(cfg: &Config) -> Result<Option<PathBuf>, String> {
    cfg.g2_capture_intent
        .as_ref()
        .map(|_| absolute_run_g2_output_directory(&cfg.out_dir))
        .transpose()
}

fn absolute_run_g2_output_directory(out_dir: &Path) -> Result<PathBuf, String> {
    if out_dir.is_absolute() {
        Ok(out_dir.join("g2_engine"))
    } else {
        env::current_dir()
            .map(|current| current.join(out_dir).join("g2_engine"))
            .map_err(|error| format!("resolve absolute G2 output directory failed: {error}"))
    }
}

fn run() -> Result<(), String> {
    let args: Vec<String> = env::args().skip(1).collect();
    #[cfg(windows)]
    if args.is_empty() {
        return run_product_auto_attach(false);
    }
    #[cfg(windows)]
    if args.as_slice() == ["--raw-debug-auto-attach"] {
        return run_product_auto_attach(true);
    }
    if args.first().map(String::as_str) == Some("--fold-and-repack-existing-run-dir") {
        return fold_and_repack_existing_run_dir(parse_repack_args(&args)?);
    }
    if args.first().map(String::as_str) == Some("--auto-attach") {
        return run_auto_attach(&args[1..]);
    }
    let mut cfg = parse_args(args)?;
    if cfg.production && cfg.early_launch.is_none() && cfg.acceptance_test.is_none() {
        return Err(
            "production/profile capture requires authenticated --early-launch-exe so render creation cannot be missed"
                .into(),
        );
    }
    let g2_output_directory = absolute_g2_output_directory(&cfg)?;
    if let Some(intent) = cfg.g2_capture_intent.as_ref() {
        intent.validate_unchanged()?;
        if g2_output_directory
            .as_ref()
            .is_some_and(|output| output.exists())
        {
            return Err(
                "G2 output directory already exists before suspended launch; refusing overwrite"
                    .into(),
            );
        }
    }
    let mut early_pending = match cfg.early_launch.as_ref() {
        Some(early) => {
            let spec = recorder_host::early_render_launch::EarlyRenderProcessCreateSpec {
                executable_path: early.executable.clone(),
                user_dir: cfg
                    .pdx_user_dir
                    .clone()
                    .ok_or("early launch lost its exact Paradox user directory")?,
                semantic_arguments: early.semantic_arguments.clone(),
                diagnostic_staged_hook_mask: cfg.diagnostic_staged_hook_mask,
            };
            let pending = recorder_host::early_render_launch::create_suspended_game_process(&spec)?;
            cfg.pid = pending.process_id();
            Some(pending)
        }
        None => None,
    };
    fs::create_dir_all(&cfg.out_dir).map_err(|e| format!("create out dir failed: {e}"))?;
    let mut raw_path = cfg.out_dir.join(cfg.stream_format.stream_file_name());
    let manifest_path = cfg.out_dir.join("native_session_manifest.json");
    let normal_replay_path = replay_path_for_gate(&cfg.out_dir, true);
    let replay_game_id = replay_game_id(&cfg.session_id);
    // M2 modset binding: resolved BEFORE the capture so the evidence reflects
    // the game process as it was recorded (the exe could be replaced on disk
    // mid-run by an update). Best-effort by construction — failures are
    // recorded in the report and never abort a capture.
    let mut modset_report = match early_pending.as_ref() {
        Some(pending) => pending.resolve_modset(),
        None => recorder_host::modset::resolve_modset(cfg.pid, cfg.pdx_user_dir.as_deref()),
    };
    if let Some(authority_path) = std::env::var_os("BATTLE_PLAN_AUTO_ATTACH_MODSET_AUTHORITY").or_else(|| std::env::var_os("HOI4_AUTO_ATTACH_MODSET_AUTHORITY")) {
        let creation_filetime = std::env::var("BATTLE_PLAN_AUTO_ATTACH_EXPECTED_FILETIME").or_else(|_| std::env::var("HOI4_AUTO_ATTACH_EXPECTED_FILETIME"))
            .map_err(|_| "auto-attach modset authority lacks expected process FILETIME")?
            .parse::<u64>()
            .map_err(|error| format!("invalid auto-attach expected process FILETIME: {error}"))?;
        recorder_host::modset::apply_same_process_settings_authority(
            &mut modset_report,
            Path::new(&authority_path),
            cfg.pid,
            creation_filetime,
        )?;
    }
    eprintln!(
        "modset: resolved={} mods={} dlc_enabled={}/{}{}",
        modset_report.resolved,
        modset_report.enabled_mods.len(),
        modset_report.enabled_dlcs.len(),
        modset_report.installed_dlcs.len(),
        if modset_report.errors.is_empty() {
            String::new()
        } else {
            format!(" errors={:?}", modset_report.errors)
        }
    );
    if let Some(gate_path) = cfg.speed_root_gate_path.as_ref() {
        let exe = modset_report.exe_path.as_ref().ok_or_else(|| {
            "speed-root gate requires a resolved target executable path".to_string()
        })?;
        let transcript_file_sha256 = cfg
            .domain57_game_speed_transcript_file_sha256
            .as_deref()
            .ok_or_else(|| {
                "domain 57 gate requires a trusted raw transcript file SHA-256".to_string()
            })?;
        cfg.domain57_game_speed_gate = Some(load_domain57_speed_root_gate(
            gate_path,
            exe,
            &cfg.session_id,
            cfg.pid,
            transcript_file_sha256,
        )?);
    }
    if scheduled_roster_includes_domain57(&cfg.scheduled_domains)
        && cfg.domain57_game_speed_gate.is_none()
        && !cfg.domain57_without_external_gate_authorized
    {
        return Err("domain 57 is scheduled but its speed-root gate was not validated".to_string());
    }
    // Production static admission is completed before the pipe is exposed and
    // before any injection authority is exercised. The canonical Python gate is
    // the sole schema authority; Rust retains its exact verified evidence for a
    // second verification immediately before publication.
    let mut static_bundle_admission = match cfg.static_bundle.as_ref() {
        Some(bundle) => {
            let exe = modset_report.exe_path.clone().ok_or_else(|| {
                "static bundle admission requires a resolved target executable path".to_string()
            })?;
            let expected_process_creation_filetime_utc = match early_pending.as_ref() {
                Some(pending) => pending.process_start_nonce(),
                None => RetainedProcessAuthority::open(cfg.pid, None)?.expected_creation_filetime,
            };
            let request = StaticBundleRequest {
                python: bundle.python.clone(),
                verifier: bundle.verifier.clone(),
                manifest: bundle.manifest.clone(),
                exe,
                mod_state: bundle.mod_state.clone(),
                dlc_state: bundle.dlc_state.clone(),
                load_order: bundle.load_order.clone(),
                source_inventory: bundle.source_inventory.clone(),
                live_resolution_report: bundle.live_resolution_report.clone(),
                expected_process_id: cfg.pid,
                expected_process_creation_filetime_utc,
                allow_prepared_process_identity_rebind: early_pending.is_some(),
                timeout: bundle.timeout,
            };
            let verified =
                recorder_host::static_bundle_gate::verify(&request).map_err(|error| {
                    format!("pre-injection static bundle admission failed: {error}")
                })?;
            cfg.static_artifacts = static_artifact_requests_from_bundle(&verified)?;
            Some(StaticBundleAdmission {
                request,
                verified,
                finalized_request: None,
                finalized_verified: None,
            })
        }
        None => None,
    };
    // Construct the complete path-redacted launch identity in memory from the
    // suspended process binding and independently admitted effective VFS.
    let (
        early_launch_manifest,
        mut early_content_manifest,
        early_full_content_manifest,
        mut early_vfs_index,
        mut early_effective_vfs,
        mut early_runtime_dlc_launch,
        mut early_runtime_dlc_descriptors,
    ) = if let Some(early) = cfg.early_launch.as_ref() {
        let bundle = cfg
            .static_bundle
            .as_ref()
            .ok_or("early production launch has no admitted static bundle")?;
        let requested_profile_selection =
            recorder_host::runtime_dlc_roster::requested_profile_selection_from_modset(
                &modset_report,
            )?;
        let launch = recorder_host::portable_content_manifest::PortableLaunchBinding::from_effective_runtime_candidate(
            &modset_report,
        )?;
        let runtime_dlc_descriptors =
            recorder_host::runtime_dlc_roster::authenticated_dlc_descriptors_from_modset(
                &modset_report,
            )?;
        let content = recorder_host::portable_content_manifest::build_from_finalized_static_bundle(
            &bundle.source_inventory,
            &bundle
                .manifest
                .parent()
                .ok_or("static bundle manifest has no parent directory")?
                .join("proofs/catalog_source_join.json"),
            &bundle.live_resolution_report,
            &launch,
            &static_bundle_admission
                .as_ref()
                .ok_or("early production launch has no verified product-modset binding")?
                .verified
                .product_modset_sha256,
        )?;
        let directory_digests =
            recorder_host::portable_content_manifest::finalized_directory_layer_content_sha256(
                &bundle.source_inventory,
                &content,
            )?;
        let collector_first = fs::read(&cfg.dll)
            .map_err(|error| format!("read early collector DLL failed: {error}"))?;
        let collector_second = fs::read(&cfg.dll)
            .map_err(|error| format!("re-read early collector DLL failed: {error}"))?;
        if collector_first != collector_second {
            return Err("early collector DLL changed while being bound".into());
        }
        let manifest =
            recorder_host::early_render_launch::EarlyRenderLaunchManifest::from_bound_launch(
                &launch,
                &content.ordered_layers,
                &directory_digests,
                requested_profile_selection.into(),
                Sha256::hex(&collector_first),
                content.effective_vfs_manifest_sha256.clone(),
                early.semantic_arguments.clone(),
            )?;
        let winner_binding = recorder_host::production_vfs_winner_binding::build_effective_vfs_winner_binding_from_inventory(
            &bundle.source_inventory,
            &content.ordered_layers,
            early_pending
                .as_ref()
                .ok_or("early launch lost its suspended process")?
                .process_start_nonce(),
            &content.effective_vfs_manifest_sha256,
        )?;
        let prepared_index = recorder_host::early_render_host_channel::PreparedEarlyRenderVfsIndex::from_winner_binding(&winner_binding)?;
        let effective_vfs = recorder_host::production_content_vfs::effective_vfs_from_launch(
            &recorder_host::portable_content_manifest::RuntimeContentRoots {
                install_root: early
                    .executable
                    .parent()
                    .ok_or("early executable has no install root")?
                    .to_path_buf(),
                user_dir: cfg
                    .pdx_user_dir
                    .clone()
                    .ok_or("early launch lost its exact user directory")?,
            },
            &content.ordered_layers,
            &content.effective_vfs_manifest_sha256,
        )?;
        let content_envelope = recorder_host::early_render_host_channel::early_render_content_manifest_metadata_envelope(&content)?;
        (
            Some(manifest),
            Some(content_envelope),
            Some(content),
            Some(prepared_index),
            Some(effective_vfs),
            Some(launch),
            Some(runtime_dlc_descriptors),
        )
    } else {
        (None, None, None, None, None, None, None)
    };
    if let Some(intent) = cfg.g2_capture_intent.as_ref() {
        let content = early_full_content_manifest
            .as_ref()
            .ok_or("G2 capture lost its pre-resume content manifest")?;
        if content.localisation_language != intent.localisation_language {
            return Err(
                "G2 intent localisation language differs from launch-bound content authority"
                    .into(),
            );
        }
        if content
            .required_settings
            .get("settings_file_sha256")
            .map(String::as_str)
            != Some(intent.settings_file_sha256.as_str())
        {
            return Err(
                "G2 intent settings digest differs from launch-bound settings authority".into(),
            );
        }
        if content.manifest_digest_sha256.is_none() {
            return Err("G2 capture requires a sealed pre-resume content manifest".into());
        }
        intent.validate_context_authority(
            &early_launch_manifest
                .as_ref()
                .ok_or("G2 capture lost its launch manifest")?
                .executable_sha256,
            &intent.settings_file_sha256,
            &intent.localisation_language,
        )?;
    }
    // Bundle admission replaces the loose artifact list with the six canonical
    // verified artifacts, so the production summary must reflect the admitted
    // inputs rather than the pre-admission CLI state.
    let production_profile_summary = build_production_profile_summary(&cfg);
    if cfg.production
        && !production_profile_summary
            .mandatory_domains_not_production_complete
            .is_empty()
    {
        return Err(format!(
            "production profile contains mandatory domains which are not production-complete: {}",
            display_static_list(
                &production_profile_summary.mandatory_domains_not_production_complete
            )
        ));
    }
    let auto_attach_worker = AutoAttachWorkerContext::from_env(&cfg)?;
    let capture_identity_mode = if auto_attach_worker.is_some()
        && recorder_host::auto_attach::duplex_worker::auto_attach_identity_v1_enabled()
    {
        compact_contract::stream_validator::StreamIdentityMode::IdentityV1
    } else {
        compact_contract::stream_validator::StreamIdentityMode::Legacy
    };
    let pipe_token = match auto_attach_worker.as_ref() {
        Some(context) => context.pipe_token.clone(),
        None if cfg.early_launch.is_some() => {
            recorder_host::auto_attach::staging::generate_pipe_token()?.0
        }
        None => pipe_token(),
    };
    let ordinary_duplex_challenge = auto_attach_worker.as_ref().and_then(|context| {
        (capture_identity_mode
            == compact_contract::stream_validator::StreamIdentityMode::IdentityV1)
            .then_some(context.expectation.challenge)
    });
    let d49_base_only_authority = if cfg.early_launch.is_none()
        && compact_expected_domain_ids(&cfg.scheduled_domains).contains(&49)
        && modset_report.resolved
        && modset_report.enabled_mods.is_empty()
    {
        Some(
            recorder_host::production_content_vfs::
                d49_base_only_authority_from_resolved_zero_mod_launch(&modset_report)?,
        )
    } else {
        None
    };
    write_sink_failure_acceptance_plan(&cfg, &pipe_token)?;
    write_control_file_with_d49_authority(
        &cfg,
        &pipe_token,
        ordinary_duplex_challenge,
        d49_base_only_authority.as_ref(),
    )?;

    let hook_hold_ms = u64::from(cfg.duration_ms)
        .saturating_add(cfg.dwell_ms)
        .saturating_add(native_division_root_prewarm_budget_ms(&cfg))
        .saturating_add(native_special_projects_prewarm_budget_ms(&cfg))
        .saturating_add(1_000);
    let pipe_timeout_ms = hook_hold_ms.saturating_add(3_000);
    let pipe_name = capture_pipe_name(cfg.pid, &pipe_token)?;
    let mut early_h4ct = match early_launch_manifest.as_ref() {
        Some(manifest) => Some(
            recorder_host::early_render_host_channel::PreparedEarlyRenderHostChannel::prepare(
                cfg.pid,
                early_pending
                    .as_ref()
                    .ok_or("early launch lost its suspended process")?
                    .process_start_nonce(),
                &pipe_token,
                manifest.clone(),
                early_content_manifest
                    .take()
                    .ok_or("early launch lost its finalized content manifest")?,
                early_vfs_index
                    .take()
                    .ok_or("early launch lost its effective-VFS winner index")?,
                early_effective_vfs
                    .take()
                    .ok_or("early launch lost its mounted effective VFS")?,
                early_runtime_dlc_launch
                    .take()
                    .ok_or("early launch lost its authenticated runtime DLC launch binding")?,
                early_runtime_dlc_descriptors
                    .take()
                    .ok_or("early launch lost its authenticated runtime DLC descriptors")?,
                cfg.g2_capture_intent.is_some(),
                cfg.early_launch
                    .as_ref()
                    .ok_or("early launch lost its CLI authority")?
                    .timeout_ms,
            )?,
        ),
        None => None,
    };
    // The pipe stream is written STRAIGHT to disk during capture (bounded memory);
    // `capture` carries only the byte count + rolling sha256, never the bytes.
    let (
        mut capture,
        rollover_set,
        first_recording_logical_stream_id,
        scientist_capture_authority,
        early_render_process,
        design_catalog_timeline_capture,
    ) = {
        let pipe_name = pipe_name.clone();
        let raw_path = raw_path.clone();
        let pipe_session_token = pipe_token.clone();
        let stream_compression = cfg.stream_compression;
        let proof_expected_domain_ids = compact_expected_domain_ids_for_config(&cfg);
        let auto_attach_creation_filetime = auto_attach_worker
            .as_ref()
            .map(|context| context.expected_creation_filetime);
        let domain57_creation_filetime = cfg
            .domain57_game_speed_gate
            .as_ref()
            .and_then(|gate| gate.get("process_creation_filetime_utc"))
            .and_then(Value::as_u64);
        let expected_creation_filetime = match (
            auto_attach_creation_filetime,
            domain57_creation_filetime,
        ) {
            (Some(auto_attach), Some(domain57)) if auto_attach != domain57 => {
                return Err(format!(
                    "auto-attach process creation authority {auto_attach} differs from domain 57 authority {domain57}"
                ));
            }
            (Some(value), _) | (_, Some(value)) => Some(value),
            (None, None) => None,
        };
        let activated_duplex = capture_identity_mode
            == compact_contract::stream_validator::StreamIdentityMode::IdentityV1;
        let (retained_dll, proof_emitter, activated_spec, activated_stop_signal) = match auto_attach_worker {
            Some(context) if activated_duplex => {
                let (dll, emitter, spec, stop_signal) = context.into_activated_parts(&cfg)?;
                (Some(dll), Some(emitter), Some(spec), Some(stop_signal))
            }
            Some(context) => {
                let (dll, emitter) = context.into_parts(&cfg)?;
                (Some(dll), Some(emitter), None, None)
            }
            None => (None, None, None, None),
        };
        // Acquire every authority before exposing the pipe. In particular, a
        // restart with a coherently rolled-back journal must observe an already
        // resident collector and fail before it can perform another hook action.
        let dll_authority = match retained_dll {
            Some(authority) => authority,
            None => RetainedDllAuthority::open(&cfg.dll, None)?,
        };
        let process_authority = std::sync::Arc::new(match expected_creation_filetime {
            Some(expected) => validate_process_creation_filetime(cfg.pid, expected)?,
            None => RetainedProcessAuthority::open(cfg.pid, None)?,
        });
        process_authority.revalidate_live()?;
        let mut design_catalog_timeline_capture = if cfg.production {
            let python = cfg
                .static_bundle
                .as_ref()
                .map(|bundle| bundle.python.as_os_str())
                .unwrap_or_else(|| OsStr::new("python"));
            let mut capture = start_owned_design_catalog_timeline(
                cfg.pid,
                &cfg.out_dir,
                python,
            )?;
            // An attached process is already running, so do not expose the
            // compact pipe or install the collector until A27 has sealed its
            // first coherent full census. Early-launch targets are still
            // suspended here and cross the equivalent barrier after resume,
            // before collector COMMIT.
            if early_pending.is_none() {
                wait_owned_design_catalog_timeline_ready(&mut capture)?;
            }
            Some(capture)
        } else {
            None
        };
        let scientist_requested = cfg.special_projects_scan
            && proof_expected_domain_ids.contains(&scientists_live_lane::PROJECTS_LIVE_DOMAIN_ID);
        if scientist_requested && cfg.special_projects_bridge.is_some() {
            return Err(
                "production scientist DLL-scan source evidence forbids bridge rows".to_string(),
            );
        }
        let mut game_module_authority = if scientist_requested && early_pending.is_none() {
            let exe = modset_report.exe_path.as_ref().ok_or_else(|| {
                "scientist source evidence requires a resolved game executable".to_string()
            })?;
            Some(retain_game_module_authority(
                process_authority.as_ref(),
                exe,
            )?)
        } else {
            None
        };
        let deferred_early_game_module = std::sync::Arc::new(std::sync::OnceLock::new());
        let deferred_early_image = match early_pending.as_ref() {
            Some(pending) => {
                let manifest = early_launch_manifest
                    .as_ref()
                    .ok_or("early launch lost its in-memory manifest")?;
                pending.validate_suspended_image_authority(&manifest.executable_sha256)?;
                Some((
                    cfg.early_launch
                        .as_ref()
                        .ok_or("early launch lost its CLI authority")?
                        .executable
                        .clone(),
                    manifest.executable_sha256.clone(),
                ))
            }
            None => {
                ensure_target_module_absent(
                    process_authority.as_ref(),
                    dll_authority.module_name()?,
                )?;
                None
            }
        };
        // EVERY injection entry, including an ordinary --pid/--dll CLI
        // invocation with no auto-attach proof channel, must commit this exact
        // target identity before pipe exposure or hook action. The named job
        // association is the cross-entry single-injection lease and the
        // kernel-retained history poison after either worker exits.
        let _target_lease = match early_pending.as_ref() {
            Some(pending) => {
                let recorder_owned_job = pending.recorder_owned_creation_job()?;
                RetainedTargetLease::establish(
                    process_authority.as_ref(),
                    Some(&recorder_owned_job),
                    false,
                )?
            }
            None => RetainedTargetLease::establish(
                process_authority.as_ref(),
                None,
                activated_spec
                    .as_ref()
                    .is_some_and(|spec| spec.payload.rearmed_after_proven_unload)
                    && std::env::var("BATTLE_PLAN_AUTO_ATTACH_REARMED_TARGET_LEASE").or_else(|_| std::env::var("HOI4_AUTO_ATTACH_REARMED_TARGET_LEASE")).as_deref()
                        == Ok("1"),
            )?,
        };
        let target_dll_proof = if proof_emitter.is_some() || scientist_requested {
            Some(dll_authority.target_proof(process_authority.clone())?)
        } else {
            None
        };
        if activated_duplex {
            if early_pending.is_some() || cfg.diagnostic_no_commit {
                return Err("activated auto-attach duplex worker cannot enter early-launch/diagnostic flow".into());
            }
            let spec = activated_spec
                .as_ref()
                .ok_or("activated duplex worker lost its immutable WorkerSpec")?;
            let target_proof = target_dll_proof
                .as_ref()
                .ok_or("activated duplex worker lost target DLL proof")?;
            let (data, control, hook_lease) = prepare_activated_duplex_workers(
                spec,
                &process_authority,
                &dll_authority,
                target_proof,
                Duration::from_millis(recorder_host::auto_attach::policy::HANDSHAKE_DEADLINE_MS),
            )?;
            let loaded_dll_sha256 = verify_target_loaded_dll(target_proof)?;
            let stitch_process_start_identity = format!(
                "pid:{}:creation-filetime:{}",
                process_authority.pid, process_authority.expected_creation_filetime
            );
            let outcome = capture_combined_pipe_to_file(
                data,
                control,
                &raw_path,
                stream_compression,
                proof_expected_domain_ids,
                proof_emitter.ok_or("activated duplex worker lost supervisor proof emitter")?,
                loaded_dll_sha256,
                activated_stop_signal.ok_or("activated duplex worker lost stop signal")?,
                &cfg.out_dir,
                &cfg.session_id,
                &stitch_process_start_identity,
            )?;
            hook_lease.release()?;
            let scientist_authority = if scientist_requested {
                let game = game_module_authority
                    .take()
                    .ok_or("activated scientist capture lost game-module authority")?;
                Some(ScientistCaptureAuthority {
                    collector_source_dll_sha256: dll_authority.sha256,
                    collector_staged_dll_sha256: dll_authority.sha256,
                    collector_loaded_dll_sha256: loaded_dll_sha256,
                    collector_image_size: dll_authority.image_size,
                    process_id: process_authority.pid,
                    process_creation_filetime_utc: process_authority.expected_creation_filetime,
                    game,
                })
            } else {
                None
            };
            (
                outcome.capture,
                outcome.rollover_set,
                outcome.first_recording_logical_stream_id,
                scientist_authority,
                None,
                design_catalog_timeline_capture,
            )
        } else {
        let hook_target_dll_proof = target_dll_proof.clone();
        let pipe_target_process = process_authority.clone();
        let (ready_tx, ready_rx) = std::sync::mpsc::sync_channel(1);
        let pipe_thread = thread::spawn(move || {
            capture_pipe_to_file(
                &pipe_name,
                &pipe_session_token,
                pipe_timeout_ms,
                &raw_path,
                stream_compression,
                proof_expected_domain_ids,
                proof_emitter,
                target_dll_proof,
                pipe_target_process,
                ready_tx,
            )
        });
        ready_rx
            .recv()
            .map_err(|_| "capture pipe exited before listening barrier".to_string())??;
        let early_a27_capture = design_catalog_timeline_capture.as_mut();
        let mut early_render_process = match early_pending.take() {
            Some(pending) => {
                let early = cfg
                    .early_launch
                    .as_ref()
                    .ok_or("early launch lost its CLI authority")?;
                let manifest = early_launch_manifest
                    .as_ref()
                    .ok_or("early launch lost its in-memory manifest")?;
                let spec = recorder_host::early_render_launch::EarlyRenderLaunchSpec {
                    executable_path: early.executable.clone(),
                    user_dir: cfg
                        .pdx_user_dir
                        .clone()
                        .ok_or("early launch lost its exact user directory")?,
                    collector_path: cfg.dll.clone(),
                    manifest: manifest.clone(),
                    hook_ready_timeout_ms: early.timeout_ms,
                    minimize_after_first_d3d: early.minimize_after_first_d3d,
                    diagnostic_staged_hook_mask: cfg.diagnostic_staged_hook_mask,
                    g2_capture_intent: cfg.g2_capture_intent.clone(),
                    g2_output_directory: g2_output_directory.clone(),
                    g2_content_manifest_digest_sha256: cfg
                        .g2_capture_intent
                        .as_ref()
                        .map(|_| {
                            early_full_content_manifest
                                .as_ref()
                                .and_then(|content| content.manifest_digest_sha256.clone())
                                .ok_or("G2 capture lost its sealed content digest")
                        })
                        .transpose()?,
                };
                let validation_process = process_authority.clone();
                let validation_result = deferred_early_game_module.clone();
                let a27_ready_timeout = Duration::from_millis(u64::from(early.timeout_ms));
                Some(
                    pending.activate_with_post_resume_validation(
                        &spec,
                        early_h4ct
                            .as_mut()
                            .ok_or("early launch lost its prepared H4CT listener")?,
                        move || {
                            let (executable, expected_sha256) = deferred_early_image
                                .as_ref()
                                .ok_or("early launch lost deferred executable authority")?;
                            let authority = retain_game_module_authority(
                                validation_process.as_ref(),
                                executable,
                            )?;
                            if to_hex(&authority.sha256) != *expected_sha256 {
                                return Err(
                                    "post-resume game module SHA differs from suspended image authority"
                                        .into(),
                                );
                            }
                            validation_result
                                .set(authority)
                                .map_err(|_| "post-resume game module authority was already set")?;
                            if let Some(capture) = early_a27_capture {
                                wait_owned_design_catalog_timeline_ready_with_timeout(
                                    capture,
                                    a27_ready_timeout,
                                    "post-resume baseline",
                                )?;
                            }
                            Ok(())
                        },
                    )?,
                )
            }
            None => {
                attach_hook(
                    &process_authority,
                    &dll_authority,
                    hook_target_dll_proof.as_ref(),
                    hook_hold_ms,
                )?;
                None
            }
        };
        if cfg.diagnostic_no_commit {
            const DIAGNOSTIC_MIN_HOLD_MS: u64 = 210_000;
            let process = early_render_process
                .as_mut()
                .ok_or("diagnostic no-COMMIT probe did not retain its launched process")?;
            let mask = cfg
                .diagnostic_staged_hook_mask
                .ok_or("diagnostic no-COMMIT probe lost its staged-hook mask")?;
            write_diagnostic_probe_receipt(
                &cfg,
                process,
                mask,
                "first_and_runtime_roster_validated_holding_without_commit",
                DIAGNOSTIC_MIN_HOLD_MS,
                0,
                true,
                false,
                None,
                false,
                "DIAGNOSTIC_NO_COMMIT_VALIDATED.json",
            )?;
            let hold_started = Instant::now();
            while hold_started.elapsed().as_millis() < u128::from(DIAGNOSTIC_MIN_HOLD_MS) {
                if process.wait(1_000)? {
                    let held_ms = hold_started.elapsed().as_millis() as u64;
                    write_diagnostic_probe_receipt(
                        &cfg,
                        process,
                        mask,
                        "target_exited_before_diagnostic_hold_completed",
                        DIAGNOSTIC_MIN_HOLD_MS,
                        held_ms,
                        false,
                        false,
                        None,
                        false,
                        "DIAGNOSTIC_NO_COMMIT_EARLY_EXIT.json",
                    )?;
                    return Err(format!(
                        "diagnostic no-COMMIT target exited after {held_ms} ms, before the required {DIAGNOSTIC_MIN_HOLD_MS} ms hold"
                    ));
                }
            }
            let held_before_liveness_ms = hold_started.elapsed().as_millis() as u64;
            if held_before_liveness_ms < DIAGNOSTIC_MIN_HOLD_MS {
                return Err("diagnostic host hold ended before the contract minimum".into());
            }
            let channel = early_h4ct
                .as_mut()
                .ok_or("diagnostic no-COMMIT probe lost its authenticated H4CT channel")?;
            let liveness =
                channel.request_diagnostic_liveness(&process.receipt, DIAGNOSTIC_MIN_HOLD_MS)?;
            channel.send_diagnostic_end(&process.receipt, &liveness)?;
            process.terminate_diagnostic()?;
            if !process.wait(0)? {
                return Err(
                    "diagnostic target remained alive after deterministic termination".into(),
                );
            }
            let held_ms = hold_started.elapsed().as_millis() as u64;
            if let Some(channel) = early_h4ct.as_ref() {
                channel.cancellation_handle().cancel();
            }
            drop(early_h4ct.take());
            write_diagnostic_probe_receipt(
                &cfg,
                process,
                mask,
                "completed_target_terminated_no_commit_no_replay",
                DIAGNOSTIC_MIN_HOLD_MS,
                held_ms,
                false,
                true,
                Some(&liveness),
                true,
                "DIAGNOSTIC_NO_COMMIT_COMPLETED.json",
            )?;
            eprintln!(
                "diagnostic no-COMMIT probe completed: pid={} mask=0x{mask:02x} held_ms={held_ms}",
                process.process_id
            );
            return Ok(());
        }
        let outcome = if early_render_process.is_some() {
            let channel = early_h4ct
                .take()
                .ok_or("early launch lost its authenticated H4CT channel after COMMIT")?;
            let cancellation = channel.cancellation_handle();
            let pipe_joiner = thread::spawn(move || {
                let result = pipe_thread
                    .join()
                    .map_err(|_| "pipe thread panicked".to_string());
                cancellation.cancel();
                result
            });
            let service_result = channel.serve_vfs_payload_requests(pipe_timeout_ms);
            let pipe_result = pipe_joiner
                .join()
                .map_err(|_| "pipe joiner thread panicked".to_string())?;
            match service_result? {
                recorder_host::early_render_host_channel::EarlyRenderServiceOutcome::CaptureTeardown => {
                    pipe_result??
                }
                recorder_host::early_render_host_channel::EarlyRenderServiceOutcome::SinkFailure(report) => {
                    let pipe_status = match pipe_result {
                        Ok(Ok(_)) => "data pipe closed cleanly after terminal sink report".to_string(),
                        Ok(Err(error)) | Err(error) => error,
                    };
                    let receipt_path =
                        write_authenticated_sink_failure_receipt(&cfg, &pipe_token, &report)?;
                    return Err(format!(
                        "collector reported authenticated terminal sink failure; receipt={}; data_pipe={pipe_status}",
                        receipt_path.display()
                    ));
                }
            }
        } else {
            pipe_thread
                .join()
                .map_err(|_| "pipe thread panicked".to_string())??
        };
        if scientist_requested && game_module_authority.is_none() {
            game_module_authority = deferred_early_game_module.get().cloned();
        }
        let scientist_authority = match game_module_authority {
            Some(game) => {
                let loaded_dll_sha256 = outcome.loaded_dll_sha256.ok_or_else(|| {
                    "scientist source capture lacks loaded collector DLL proof".to_string()
                })?;
                Some(ScientistCaptureAuthority {
                    collector_source_dll_sha256: dll_authority.sha256,
                    collector_staged_dll_sha256: dll_authority.sha256,
                    collector_loaded_dll_sha256: loaded_dll_sha256,
                    collector_image_size: dll_authority.image_size,
                    process_id: process_authority.pid,
                    process_creation_filetime_utc: process_authority.expected_creation_filetime,
                    game,
                })
            }
            None => None,
        };
        (
            outcome.capture,
            outcome.rollover_set,
            outcome.first_recording_logical_stream_id,
            scientist_authority,
            early_render_process,
            design_catalog_timeline_capture,
        )
        }
    };
    if let Some(timeline_capture) = design_catalog_timeline_capture {
        cfg.design_catalog_live = Some(finish_owned_design_catalog_timeline(timeline_capture)?);
    }
    if let Some(descriptor) = rollover_set.as_ref() {
        if cfg.stream_format != StreamFormat::Compact
            || cfg.stream_compression != compact_stream::StreamCompression::None
        {
            return Err(
                "ordered CID1 logical-stream publication requires raw compact storage"
                    .to_string(),
            );
        }
        let first = descriptor
            .ordered_streams
            .first()
            .ok_or("ordered CID1 logical-stream descriptor is empty")?;
        if first.logical_stream_id != 0 {
            return Err("ordered CID1 logical-stream descriptor does not start at zero".into());
        }
        let first_recording_id = first_recording_logical_stream_id.ok_or(
            "rollover capture completed without the logical stream id that admitted FirstWorld",
        )?;
        if first_recording_id >= descriptor.ordered_streams.len() as u64 {
            return Err(format!(
                "FirstWorld logical stream {first_recording_id} is outside the {}-member rollover set",
                descriptor.ordered_streams.len()
            ));
        }
        let recording_stream = descriptor
            .ordered_streams
            .get(
                usize::try_from(first_recording_id)
                    .map_err(|_| "FirstWorld logical stream id exceeds usize".to_string())?,
            )
            .ok_or("FirstWorld logical stream disappeared from the rollover descriptor")?;
        if recording_stream.logical_stream_id != first_recording_id {
            return Err("FirstWorld logical stream id is not descriptor-index canonical".into());
        }
        // Continue can replace the launch-time CGameState before any world
        // frame is admitted. In that case logical stream zero is a durable
        // CID1-only pre-world transient and stream one is the first recordable
        // campaign. Root finalization must select the stream that actually
        // admitted FirstWorld, not mechanically select stream zero.
        raw_path = cfg
            .out_dir
            .join("logical-streams")
            .join(&recording_stream.relative_path);
        capture.byte_count = recording_stream.file_bytes;
        capture.stored_byte_count = recording_stream.file_bytes;
        capture.sha256 = recording_stream.file_sha256_hex.clone();
    }
    let g2_capture_artifact_seal = if let Some(intent) = cfg.g2_capture_intent.as_ref() {
        let content_digest = early_full_content_manifest
            .as_ref()
            .and_then(|content| content.manifest_digest_sha256.as_deref())
            .ok_or("G2 finalizer lost its sealed pre-resume content digest")?;
        Some(recorder_host::early_render_launch::seal_g2_capture_artifacts(
            intent,
            g2_output_directory
                .as_deref()
                .ok_or("G2 finalizer lost its absolute output directory")?,
            early_launch_manifest
                .as_ref()
                .ok_or("G2 finalizer lost its early launch manifest")?,
            &early_render_process
                .as_ref()
                .ok_or("G2 finalizer lost its authenticated capture receipt")?
                .receipt,
            content_digest,
        )?)
    } else {
        None
    };
    // Post-capture finalization (summarize + streaming fold + streaming pack +
    // streaming verify) must complete in seconds, not the minutes the old whole-
    // stream-in-RAM path took; this clock is reported into the manifest (G5).
    let finalize_started = Instant::now();

    // Production (compact) never re-reads the whole stream into RAM: it is summarized
    // over a read-only memory map and folded in a bounded streaming pass. The JSON
    // debug stream is dev-only and small, so it is read back into RAM unchanged.
    let json_bytes: Option<Vec<u8>> = match cfg.stream_format {
        StreamFormat::Json => {
            Some(fs::read(&raw_path).map_err(|e| format!("read raw stream failed: {e}"))?)
        }
        StreamFormat::Compact => None,
    };
    let (mut manifest, hourly_met) = match cfg.stream_format {
        StreamFormat::Json => {
            let json_bytes = json_bytes.as_deref().unwrap_or(&[]);
            let summary = summarize_frames(json_bytes);
            let hourly_problems = json_hourly_problems(&summary, cfg.min_game_hours);
            let hourly_met = hourly_problems.is_empty();
            (
                json!({
                    "schema": "native_collector_session_v1",
                    "pid": cfg.pid,
                    "dll": cfg.dll.display().to_string(),
                    "raw_stream": raw_path.file_name().and_then(|v| v.to_str()).unwrap_or("collector_frames.jsonl"),
                    "session_id": cfg.session_id,
                    "duration_ms": cfg.duration_ms,
                    "sample_ms": cfg.sample_ms,
                    "dwell_ms": cfg.dwell_ms,
                    "scheduled_domains": cfg.scheduled_domains,
                    "lightweight_root_frame": cfg.lightweight_root_frame,
                    "special_projects_scan": cfg.special_projects_scan,
                    "compact_country_frame": cfg.compact_country_frame,
                    "division_body_bridge_rows": encoded_row_count(cfg.division_body_bridge.as_deref()),
                    "special_projects_bridge_rows": encoded_row_count(cfg.special_projects_bridge.as_deref()),
                    "division_root_source": "not_applicable_json_debug_stream",
                    "division_root_discovery_debt": cfg.division_body_bridge.as_ref().map(|_| "temporary bounded preflight/cache input; JSON is not the production compact proof path").unwrap_or("not_applicable_json_debug_stream"),
                    "division_body_bridge_preflight_debt": cfg.division_body_bridge.as_ref().map(|_| "temporary bounded preflight/cache input; JSON is not the production compact proof path").unwrap_or("not_applicable_json_debug_stream"),
                    "ship_root_source": "not_applicable_json_debug_stream",
                    "ship_root_discovery_debt": "not_applicable_json_debug_stream",
                    "projects_root_source": "not_applicable_json_debug_stream",
                    "projects_root_discovery_debt": "not_applicable_json_debug_stream",
                    "stream_format": cfg.stream_format.as_str(),
                    "a39_evidence_capture": cfg.a39_evidence_capture,
                    "extraction_perf_gate": cfg.extraction_perf_gate,
                    "d53_emit_mode": cfg.d53_emit_mode.as_str(),
                    "d51_emit_mode": cfg.d51_emit_mode.as_str(),
                    "d41_emit_mode": cfg.d41_emit_mode.as_str(),
                    "d44_emit_mode": cfg.d44_emit_mode.as_str(),
                    "d48_emit_mode": cfg.d48_emit_mode.as_str(),
                    "d53_relation_read_mode": cfg.d53_relation_read_mode.as_str(),
                    "prefetch_dist_relation": cfg.prefetch_dist_relation,
                    "prefetch_dist_candidates": cfg.prefetch_dist_candidates,
                    "reader_concurrency": cfg.reader_concurrency,
                    "idea_group_filter_rows": encoded_row_count(cfg.idea_group_filter.as_deref()),
                    "advisor_token_filter_rows": encoded_row_count(cfg.advisor_token_filter.as_deref()),
                    "frame_count": summary.frame_count,
                    "collector_started_count": summary.collector_started_count,
                    "raw_event_count": summary.raw_event_count,
                    "raw_delta_count": summary.raw_delta_count,
                    "domains_seen": summary.domains_seen.iter().collect::<Vec<_>>(),
                    "raw_domains_seen": summary.raw_domains_seen.iter().collect::<Vec<_>>(),
                    "scheduled_domain_frames": summary.scheduled_domain_frames,
                    "first_game_hour_raw": summary.first_hour,
                    "last_game_hour_raw": summary.last_hour,
                    "unique_game_hour_count": summary.unique_hours.len(),
                    "game_hours_advanced": summary.first_hour.zip(summary.last_hour).map(|(first, last)| last.saturating_sub(first)),
                    "skipped_game_hours": summary.skipped_hours,
                    "hourly_requirement": {
                        "required": true,
                        "requested_game_hours": cfg.min_game_hours,
                        "met": hourly_met,
                        "problems": hourly_problems,
                    },
                    "expected_partial_tolerances_applied": [],
                    "collector_control_errors": summary.control_errors.iter().collect::<Vec<_>>(),
                    "parse_errors": summary.parse_errors,
                    "production_path_note": "JSON is debug/proof visibility only; production feasibility must use the compact stream gate",
                }),
                hourly_met,
            )
        }
        StreamFormat::Compact => {
            // Decode raw or zstd storage record-by-record. Peak memory is bounded
            // by the largest H4CR record rather than the full capture.
            let summary = summarize_compact_stream_file_with_identity_mode(
                &raw_path,
                capture_identity_mode,
            )?;
            let scheduled_expected_domain_ids = compact_expected_domain_ids_for_config(&cfg);
            let coverage_errors =
                compact_domain_coverage_errors(&summary, &scheduled_expected_domain_ids);
            let mut expected_domain_ids = scheduled_expected_domain_ids;
            // Suspended-launch production appends one authenticated, pointer-free
            // ProductionRenderFrame (d77) immediately before each FRAME_END.
            // d77 remains non-schedulable: it is expected only when the H4CT
            // early-render transaction actually completed for this capture.
            if early_render_process.is_some() && !expected_domain_ids.contains(&77) {
                expected_domain_ids.push(77);
                expected_domain_ids.sort_unstable();
            }
            let gate_status = compact_gate_status(&summary);
            let control_invalid_seen =
                (gate_status.failure_status_flags_or & COMPACT_STATUS_CONTROL_INVALID) != 0;
            let collector_control_errors = if control_invalid_seen {
                if summary.control_invalid_reasons.is_empty() {
                    vec![
                        "control_invalid:compact_status_control_invalid_without_reason".to_string(),
                    ]
                } else {
                    summary
                        .control_invalid_reasons
                        .keys()
                        .map(|reason| format!("control_invalid:{reason}"))
                        .collect()
                }
            } else {
                Vec::new()
            };
            let division_root_source = compact_division_root_source(&cfg, &summary);
            let division_root_discovery_debt =
                compact_division_root_discovery_debt(division_root_source);
            let ship_root_source = compact_ship_root_source(&cfg, &summary);
            let ship_root_discovery_debt = compact_ship_root_discovery_debt(ship_root_source);
            let projects_root_source = compact_projects_root_source(&cfg, &summary);
            let projects_root_discovery_debt =
                compact_projects_root_discovery_debt(projects_root_source);
            let mut hourly_problems =
                compact_hourly_problems(&summary, cfg.min_game_hours, &coverage_errors);
            hourly_problems.extend(domain57_gate_problems(
                &summary,
                expected_domain_ids.contains(&COMPACT_DOMAIN_SESSION_MULTIPLAYER_METADATA_LIVE),
            ));
            hourly_problems.extend(hour_latch_gate_problems(&summary, cfg.hour_latch_enabled));
            if cfg.production {
                hourly_problems.extend(acceptance_telemetry_problems(
                    &summary,
                    &expected_domain_ids,
                    Some(&capture),
                ));
            }
            let hourly_met = hourly_problems.is_empty();
            let compact_stream_manifest = compact_stream_manifest_json(
                &summary,
                &expected_domain_ids,
                &coverage_errors,
                &cfg.scheduled_domains,
                Some(&capture),
            );
            let acceptance_test_observation = acceptance_test_observation_json(&cfg, &summary);
            // W15: `Known` can be minted only by the opaque CID1 token retained
            // by the stateful stream validator. Legacy d68 observations remain
            // witnesses and can resolve only to unbound/unavailable.
            let campaign_identity_binding = recorder_host::campaign_identity::to_manifest_json(
                &compact_summary_campaign_identity(&summary),
            );
            let expected_partial_tolerances_applied =
                compact_expected_partial_tolerances_applied_json(&summary);
            (
                json!({
                    "schema": "native_collector_session_v1",
                    "pid": cfg.pid,
                    "dll": cfg.dll.display().to_string(),
                    "raw_stream": rollover_set
                        .as_ref()
                        .and_then(|set| {
                            first_recording_logical_stream_id
                                .and_then(|id| usize::try_from(id).ok())
                                .and_then(|index| set.ordered_streams.get(index))
                        })
                        .map(|stream| format!("logical-streams/{}", stream.relative_path))
                        .unwrap_or_else(|| raw_path.file_name().and_then(|v| v.to_str()).unwrap_or("collector_stream.bin").to_string()),
                    "session_id": cfg.session_id,
                    "duration_ms": cfg.duration_ms,
                    "sample_ms": cfg.sample_ms,
                    "dwell_ms": cfg.dwell_ms,
                    "scheduled_domains": cfg.scheduled_domains,
                    "lightweight_root_frame": cfg.lightweight_root_frame,
                    "special_projects_scan": cfg.special_projects_scan,
                    "compact_country_frame": cfg.compact_country_frame,
                    "division_body_bridge_rows": encoded_row_count(cfg.division_body_bridge.as_deref()),
                    "special_projects_bridge_rows": encoded_row_count(cfg.special_projects_bridge.as_deref()),
                    "division_root_source": division_root_source,
                    "division_root_discovery_debt": division_root_discovery_debt,
                    "division_body_bridge_preflight_debt": division_root_discovery_debt,
                    "ship_root_source": ship_root_source,
                    "ship_root_discovery_debt": ship_root_discovery_debt,
                    "projects_root_source": projects_root_source,
                    "projects_root_discovery_debt": projects_root_discovery_debt,
                    "stream_format": cfg.stream_format.as_str(),
                    "a39_evidence_capture": cfg.a39_evidence_capture,
                    "compact_stream_identity_mode": match capture_identity_mode {
                        compact_contract::stream_validator::StreamIdentityMode::IdentityV1 => "identity_v1",
                        compact_contract::stream_validator::StreamIdentityMode::Legacy => "legacy",
                    },
                    "extraction_perf_gate": cfg.extraction_perf_gate,
                    "d53_emit_mode": cfg.d53_emit_mode.as_str(),
                    "d51_emit_mode": cfg.d51_emit_mode.as_str(),
                    "d41_emit_mode": cfg.d41_emit_mode.as_str(),
                    "d44_emit_mode": cfg.d44_emit_mode.as_str(),
                    "d48_emit_mode": cfg.d48_emit_mode.as_str(),
                    "d53_relation_read_mode": cfg.d53_relation_read_mode.as_str(),
                    "prefetch_dist_relation": cfg.prefetch_dist_relation,
                    "prefetch_dist_candidates": cfg.prefetch_dist_candidates,
                    "reader_concurrency": cfg.reader_concurrency,
                    "idea_group_filter_rows": encoded_row_count(cfg.idea_group_filter.as_deref()),
                    "advisor_token_filter_rows": encoded_row_count(cfg.advisor_token_filter.as_deref()),
                    "compact_stream": compact_stream_manifest,
                    "acceptance_test_observation": acceptance_test_observation,
                    "campaign_identity": campaign_identity_binding,
                    "first_game_hour_raw": summary.first_hour,
                    "last_game_hour_raw": summary.last_hour,
                    "unique_game_hour_count": summary.unique_hours.len(),
                    "game_hours_advanced": summary.first_hour.zip(summary.last_hour).map(|(first, last)| last.saturating_sub(first)),
                    "skipped_game_hours": summary.skipped_hours,
                    "hourly_requirement": {
                        "required": true,
                        "requested_game_hours": cfg.min_game_hours,
                        "met": hourly_met,
                        "problems": hourly_problems,
                    },
                    "expected_partial_tolerances_applied": expected_partial_tolerances_applied,
                    "collector_control_errors": collector_control_errors,
                    "parse_errors": summary.parse_errors,
                    "ordering_errors": summary.ordering_errors,
                    "production_path_note": "compact DLL stream gate: no full JSON root frames in the live extraction path; the Rust recorder packs the raw compact stream into .battleplan for durability",
                }),
                hourly_met,
            )
        }
    };
    let scientist_source_report = match scientist_capture_authority.as_ref() {
        Some(authority) => {
            let closed_frames = manifest
                .get("compact_stream")
                .and_then(|stream| stream.get("frame_end_record_count"))
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok())
                .ok_or_else(|| {
                    "scientist source report requires compact_stream.frame_end_record_count"
                        .to_string()
                })?;
            let first_game_hour_raw = manifest
                .get("first_game_hour_raw")
                .and_then(Value::as_i64)
                .and_then(|value| i32::try_from(value).ok())
                .ok_or_else(|| {
                    "scientist source report requires first_game_hour_raw".to_string()
                })?;
            let last_game_hour_raw = manifest
                .get("last_game_hour_raw")
                .and_then(Value::as_i64)
                .and_then(|value| i32::try_from(value).ok())
                .ok_or_else(|| "scientist source report requires last_game_hour_raw".to_string())?;
            let requested_game_hour_advancements =
                u32::try_from(cfg.min_game_hours).map_err(|_| {
                    "scientist source requested game hours must be nonnegative".to_string()
                })?;
            let stored_stream_sha256 = to_hex(&hash_file_sha256_bytes(&raw_path)?);
            let collector_source_dll_sha256 = to_hex(&authority.collector_source_dll_sha256);
            let collector_staged_dll_sha256 = to_hex(&authority.collector_staged_dll_sha256);
            let collector_loaded_dll_sha256 = to_hex(&authority.collector_loaded_dll_sha256);
            let game_exe_sha256 = to_hex(&authority.game.sha256);
            let report = recorder_host::scientist_source_report::build_and_write(
                recorder_host::scientist_source_report::ScientistSourceReportRequest {
                    output_path: &cfg.out_dir.join("scientists_live_dll_scan_source.json"),
                    session_id: &cfg.session_id,
                    stored_stream_sha256: &stored_stream_sha256,
                    decoded_stream_sha256: &capture.sha256,
                    requested_game_hour_advancements,
                    closed_frames,
                    first_game_hour_raw,
                    last_game_hour_raw,
                    collector_source_dll_sha256: &collector_source_dll_sha256,
                    collector_staged_dll_sha256: &collector_staged_dll_sha256,
                    collector_loaded_dll_sha256: &collector_loaded_dll_sha256,
                    collector_pe_image_size: authority.collector_image_size,
                    game_exe_sha256: &game_exe_sha256,
                    process_id: authority.process_id,
                    process_creation_filetime_utc: authority.process_creation_filetime_utc,
                    game_module_base: authority.game.base_address as u64,
                    game_module_size: authority.game.image_size as u64,
                    game_module_backing_file_sha256: &game_exe_sha256,
                    bridge_rows_supplied: 0,
                },
            )?;
            let report_bytes = fs::read(&report.path)
                .map_err(|error| format!("read scientist source report failed: {error}"))?;
            let collector_dll_bytes = fs::read(&cfg.dll).map_err(|error| {
                format!("read collector DLL for scientist proof failed: {error}")
            })?;
            let game_exe_path = modset_report.exe_path.as_ref().ok_or_else(|| {
                "scientist source verification requires resolved game executable".to_string()
            })?;
            let game_exe_bytes = fs::read(game_exe_path).map_err(|error| {
                format!("read game executable for scientist proof failed: {error}")
            })?;
            let verified = scientists_live_lane::source_evidence::verify_required_dll_scan_source_evidence_hashes(
                Some(&report_bytes),
                Some(&collector_dll_bytes),
                Some(&game_exe_bytes),
                scientists_live_lane::source_evidence::ExpectedStreamHashes {
                    stored_sha256: &stored_stream_sha256,
                    decoded_sha256: &capture.sha256,
                    requested_game_hour_advancements,
                    closed_frames,
                    first_game_hour_raw,
                    last_game_hour_raw,
                },
            )
            .map_err(|error| format!("scientist source report verification failed: {error}"))?;
            Some((report, verified))
        }
        None => None,
    };
    if cfg.production {
        let request = cfg
            .design_catalog_live
            .as_ref()
            .ok_or("production capture did not retain an A27 timeline")?;
        let first_game_hour_raw = manifest
            .get("first_game_hour_raw")
            .and_then(Value::as_i64)
            .ok_or("A27 timeline coverage requires first_game_hour_raw")?;
        let last_game_hour_raw = manifest
            .get("last_game_hour_raw")
            .and_then(Value::as_i64)
            .ok_or("A27 timeline coverage requires last_game_hour_raw")?;
        validate_design_catalog_timeline_coverage(
            request,
            first_game_hour_raw,
            last_game_hour_raw,
        )?;
    }
    let emitted_token_inventory = if cfg.raw_debug_output {
        // Raw debug deliberately stops at the capture boundary. The admitted
        // pre-resume content/VFS facts remain available below, but token
        // inventory construction and static-bundle finalization are
        // post-capture certification work and therefore stay disabled.
        None
    } else {
        match static_bundle_admission.as_mut() {
            Some(admission) => {
                if cfg.stream_format != StreamFormat::Compact {
                    return Err(
                        "static bundle finalization requires a compact H4CR stream".to_string()
                    );
                }
                let capture_id = cfg
                    .capture_id
                    .as_deref()
                    .ok_or_else(|| "static bundle finalization requires --capture-id".to_string())?;
                let inventory = recorder_host::emitted_token_inventory::build_and_write(
                    &raw_path,
                    &cfg.out_dir.join("emitted_token_inventory.json"),
                    capture_id,
                    &cfg.session_id,
                    &capture.sha256,
                    capture_identity_mode,
                )?;
                let (finalized_request, finalized_verified) =
                    recorder_host::static_bundle_gate::finalize(
                        &admission.request,
                        &cfg.out_dir.join("static_bundle_finalized"),
                        &inventory.path,
                        capture_id,
                        &cfg.session_id,
                        &capture.sha256,
                    )
                    .map_err(|error| {
                        format!("post-capture static bundle finalization failed: {error}")
                    })?;
                cfg.static_artifacts = static_artifact_requests_from_bundle(&finalized_verified)?;
                admission.finalized_request = Some(finalized_request);
                admission.finalized_verified = Some(finalized_verified);
                Some(inventory)
            }
            None => None,
        }
    };
    let portable_content_manifest = if cfg.production && cfg.raw_debug_output {
        // Preserve the exact content manifest that was authenticated over
        // H4CT before ResumeThread. Do not reinterpret it as a post-capture
        // finalized publication manifest.
        early_full_content_manifest.clone()
    } else if cfg.production {
        let admission = static_bundle_admission
            .as_ref()
            .ok_or("production content manifest has no finalized static bundle admission")?;
        let finalized = admission
            .finalized_request
            .as_ref()
            .ok_or("production content manifest has no finalized static bundle request")?;
        let bundle_root = finalized
            .manifest
            .parent()
            .ok_or("finalized static bundle manifest has no parent directory")?;
        let launch = recorder_host::portable_content_manifest::PortableLaunchBinding::from_modset(
            &modset_report,
        )?;
        let runtime_roots =
            recorder_host::portable_content_manifest::RuntimeContentRoots::from_modset(
                &modset_report,
            )?;
        let finalized_content = recorder_host::portable_content_manifest::build_from_finalized_static_bundle_with_early_render_receipt(
                &finalized.source_inventory,
                &bundle_root.join("proofs/catalog_source_join.json"),
                &finalized.live_resolution_report,
                &launch,
                &admission
                    .finalized_verified
                    .as_ref()
                    .ok_or("production content manifest has no finalized product-modset binding")?
                    .product_modset_sha256,
                &runtime_roots,
                &raw_path,
                capture_identity_mode,
                early_launch_manifest
                    .as_ref()
                    .ok_or("production finalizer lost its in-memory early launch manifest")?,
                &early_render_process
                    .as_ref()
                    .ok_or("production finalizer lost its authenticated early process receipt")?
                    .receipt,
            )?;
        let early_envelope = recorder_host::early_render_host_channel::early_render_content_manifest_metadata_envelope(
            early_full_content_manifest
                .as_ref()
                .ok_or("production finalizer lost its pre-resume full content manifest")?,
        )?;
        let finalized_envelope = recorder_host::early_render_host_channel::early_render_content_manifest_metadata_envelope(
            &finalized_content,
        )?;
        if finalized_envelope != early_envelope {
            return Err(
                "final content manifest metadata differs from the pre-resume authority".into(),
            );
        }
        Some(finalized_content)
    } else {
        match cfg
            .static_bundle
            .as_ref()
            .and_then(|bundle| bundle.portable_content_use_trace.as_ref())
        {
            Some(path) => {
                let launch =
                    recorder_host::portable_content_manifest::PortableLaunchBinding::from_modset(
                        &modset_report,
                    )?;
                let live_report = &cfg
                    .static_bundle
                    .as_ref()
                    .expect("portable trace belongs to a static bundle")
                    .live_resolution_report;
                let (content_manifest, _) =
                    recorder_host::portable_content_manifest::load_and_build_bound(
                        path,
                        live_report,
                        &launch,
                        &static_bundle_admission
                            .as_ref()
                            .and_then(|admission| admission.finalized_verified.as_ref())
                            .ok_or("portable trace publication has no finalized product-modset binding")?
                            .product_modset_sha256,
                    )?;
                Some(content_manifest)
            }
            None => None,
        }
    };
    let replay_content_manifest_digest = portable_content_manifest
        .as_ref()
        .and_then(|content| content.manifest_digest_sha256.as_deref());
    let replay_packaging = replay_packaging_manifest_json(
        &cfg,
        g2_capture_artifact_seal.as_ref(),
        replay_content_manifest_digest,
    )?;
    if let Some(obj) = manifest.as_object_mut() {
        obj.insert("replay_packaging".to_string(), replay_packaging);
        obj.insert(
            "portable_content_manifest".to_string(),
            portable_content_manifest
                .as_ref()
                .map(|content| serde_json::to_value(content).expect("content manifest serializes"))
                .unwrap_or(Value::Null),
        );
        if let (Some(launch), Some(process)) = (
            early_launch_manifest.as_ref(),
            early_render_process.as_ref(),
        ) {
            obj.insert(
                "early_render_launch_manifest".to_string(),
                serde_json::to_value(launch)
                    .map_err(|error| format!("serialize early launch manifest: {error}"))?,
            );
            obj.insert(
                "early_render_capture_receipt".to_string(),
                serde_json::to_value(&process.receipt)
                    .map_err(|error| format!("serialize early capture receipt: {error}"))?,
            );
            obj.insert(
                "early_render_capture_receipt_sha256".to_string(),
                json!(process.receipt.sha256()?),
            );
        }
    }
    // All finalization decisions must consume the same strict JSON value that
    // can be read back from disk. In particular, live timing telemetry carries
    // f64 values whose serde_json Number representation can normalize across a
    // serialize/strict-parse boundary.
    manifest = normalize_session_manifest_value(&manifest)?;
    let gate_problems = manifest_hourly_problems(&manifest);
    let replay_path = replay_path_for_gate(&cfg.out_dir, hourly_met);
    let normal_quarantine = (!hourly_met && !cfg.raw_debug_output)
        .then(|| quarantine_normal_replay(&normal_replay_path));
    let replay_file_name = replay_path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("native_session.battleplan")
        .to_string();
    let normal_replay_file_name = normal_replay_path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("native_session.battleplan")
        .to_string();
    // The production validator's F5 contract is rooted at
    // `acceptance_telemetry`. Keep the compact-stream copy for local diagnostic
    // cohesion, but promote the exact same value rather than recomputing or
    // allowing the two views to drift.
    let root_acceptance_telemetry = manifest
        .get("compact_stream")
        .and_then(|stream| stream.get("acceptance_telemetry"))
        .cloned()
        .unwrap_or(Value::Null);
    if let Some(obj) = manifest.as_object_mut() {
        obj.insert("replay_file".to_string(), json!(replay_file_name.clone()));
        obj.insert("replay_game_id".to_string(), json!(replay_game_id));
        obj.insert(
            "replay_artifact".to_string(),
            json!({
                "normal_file": normal_replay_file_name,
                "written_file": replay_file_name,
                "recovery": !hourly_met,
                "reason": if hourly_met { "gate_passed" } else { "gate_failed" },
                "gate_problems": gate_problems.clone(),
                "normal_file_quarantine": normal_quarantine
                    .as_ref()
                    .map(ReplayQuarantineReport::as_json)
                    .unwrap_or(Value::Null),
            }),
        );
        obj.insert(
            "replay_entries".to_string(),
            json!({
                "index": "index.json",
                "timeline": "timeline.json",
                "stream": format!("collector_raw/{}", cfg.stream_format.stream_file_name()),
                "stream_role": "collector_compact_stream",
                "session_manifest": "recorder/native_session_manifest.json",
                "session_manifest_role": "recorder_manifest",
            }),
        );
        let mut production_profile = production_profile_summary.as_json();
        bind_domain57_authority_to_manifest_profile(&mut production_profile, &cfg);
        obj.insert("production_profile".to_string(), production_profile);
        obj.insert(
            "stream_storage".to_string(),
            json!({
                "compression": cfg.stream_compression.as_str(),
                "decoded_bytes": capture.byte_count,
                "stored_bytes": capture.stored_byte_count,
                "decoded_sha256": capture.sha256,
            }),
        );
        obj.insert(
            "acceptance_telemetry".to_string(),
            root_acceptance_telemetry,
        );
        // M2: the recording's modset + game-build binding. `resolved:false`
        // means UNKNOWN modset (errors carried alongside) — downstream joins
        // must not assume vanilla.
        obj.insert("modset".to_string(), modset_report.as_json());
        obj.insert("capture_id".to_string(), json!(cfg.capture_id));
        if let Some(descriptor) = rollover_set.as_ref() {
            let descriptor_path = cfg
                .out_dir
                .join("logical-streams")
                .join(recorder_host::duplex_session::rollover_fs::SET_DESCRIPTOR_FILE);
            obj.insert(
                "logical_stream_id".to_string(),
                json!(first_recording_logical_stream_id),
            );
            obj.insert(
                "acceptance_telemetry_scope".to_string(),
                json!("logical_stream"),
            );
            obj.insert(
                "logical_stream_set".to_string(),
                json!({
                    "schema": descriptor.schema,
                    "descriptor": format!(
                        "logical-streams/{}",
                        recorder_host::duplex_session::rollover_fs::SET_DESCRIPTOR_FILE
                    ),
                    "descriptor_sha256": to_hex(&hash_file_sha256_bytes(&descriptor_path)?),
                    "member_count": descriptor.ordered_streams.len(),
                    "first_recording_logical_stream_id": first_recording_logical_stream_id,
                }),
            );
            obj.insert(
                "logical_stream_package_set".to_string(),
                json!({
                    "schema": "cid1-rollover-package-set-v1",
                    "descriptor": recorder_host::duplex_session::rollover_fs::PACKAGE_SET_DESCRIPTOR_FILE,
                    "selection": "ordered_logical_stream_segments",
                }),
            );
        }
        obj.insert(
            "emitted_token_inventory".to_string(),
            emitted_token_inventory
                .as_ref()
                .map(|inventory| {
                    json!({
                        "path": inventory.path.file_name().and_then(|name| name.to_str()),
                        "sha256": inventory.sha256,
                        "token_count": inventory.token_count,
                        "decoded_stream_bytes": inventory.decoded_stream_bytes,
                    })
                })
                .unwrap_or(Value::Null),
        );
        obj.insert(
            "scientists_live_dll_scan_source".to_string(),
            scientist_source_report
                .as_ref()
                .map(|(report, verified)| {
                    json!({
                        "path": report.path.file_name().and_then(|name| name.to_str()),
                        "sha256": report.sha256,
                        "evidence_nonce_hex": report.evidence_nonce_hex,
                        "verified": true,
                        "build_id": scientists_live_lane::source_evidence::SOURCE_EVIDENCE_BUILD_ID,
                        "collector_dll_sha256": verified.collector_dll_sha256,
                        "game_exe_sha256": verified.game_exe_sha256,
                        "process_id": verified.process_id,
                        "process_creation_filetime_utc": verified.process_creation_filetime_utc,
                        "module_base": format!("0x{:x}", verified.module_base),
                        "module_size": verified.module_size,
                    })
                })
                .unwrap_or(Value::Null),
        );
        obj.insert(
            "static_bundle".to_string(),
            if cfg.raw_debug_output {
                Value::Null
            } else {
                static_bundle_admission
                    .as_ref()
                    .and_then(StaticBundleAdmission::publication_verified)
                    .map(VerifiedStaticBundle::as_json)
                    .unwrap_or(Value::Null)
            },
        );
        if cfg.raw_debug_output {
            obj.insert(
                "raw_debug_pre_resume_static_bundle".to_string(),
                static_bundle_admission
                    .as_ref()
                    .map(|admission| admission.verified.as_json())
                    .unwrap_or(Value::Null),
            );
        }
    }
    if cfg.raw_debug_output && cfg.production {
        verify_raw_debug_pre_resume_content_join(&manifest, static_bundle_admission.as_ref())?;
    } else if !cfg.raw_debug_output {
        verify_product_modset_publication_join(
            &manifest,
            static_bundle_admission.as_ref(),
            cfg.production,
        )?;
    }
    normalize_and_write_session_manifest(&manifest_path, &mut manifest)?;
    for line in production_profile_summary_lines(&production_profile_summary) {
        eprintln!("{line}");
    }
    if let Some(tolerated_domains) = manifest
        .get("expected_partial_tolerances_applied")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| item.get("domain").and_then(Value::as_str))
                .collect::<Vec<_>>()
        })
        .filter(|items| !items.is_empty())
    {
        eprintln!(
            "recorder summary: tolerated_expected_partial={}",
            tolerated_domains.join(",")
        );
    }
    if let Some(errors) = manifest
        .get("collector_control_errors")
        .and_then(Value::as_array)
    {
        let errors = errors.iter().filter_map(Value::as_str).collect::<Vec<_>>();
        if !errors.is_empty() {
            eprintln!(
                "recorder error: collector control invalid; errors={}",
                errors.join(",")
            );
        }
    }
    let acceptance_test_met = cfg.acceptance_test.is_some()
        && manifest
            .get("acceptance_test_observation")
            .and_then(|value| value.get("ok"))
            .and_then(Value::as_bool)
            == Some(true);
    if !hourly_met {
        if cfg.raw_debug_output {
            eprintln!(
                "recorder warning: capture gates failed; retaining sealed raw H4CR with error telemetry; problems={}",
                if gate_problems.is_empty() {
                    "unspecified".to_string()
                } else {
                    gate_problems.join(",")
                }
            );
        } else {
            eprintln!(
                "recorder warning: gates failed; writing recovery replay {} instead of normal replay {}; problems={}",
                replay_path.display(),
                normal_replay_path.display(),
                if gate_problems.is_empty() {
                    "unspecified".to_string()
                } else {
                    gate_problems.join(",")
                }
            );
        }
        if let Some(report) = &normal_quarantine {
            if report.attempted && report.ok {
                eprintln!(
                    "recorder warning: quarantined stale normal replay {} -> {}; reason={}",
                    report.old_file,
                    report.new_file.as_deref().unwrap_or("unknown"),
                    report.reason
                );
            } else if report.attempted {
                eprintln!(
                    "recorder error: could not quarantine normal replay {}; it may be stale; error={}",
                    report.old_file,
                    report.error.as_deref().unwrap_or("unknown")
                );
            }
        }
    }
    if acceptance_test_met {
        eprintln!(
            "acceptance test observation passed; replay remains recovery-only and is not production-admissible"
        );
    }
    // Fold the decoded compact records into per-game-hour world-state snapshots.
    // Only the compact stream carries H4CR records; the JSON debug stream has no
    // fold and packs an empty snapshots array.
    let mut fold_stats_telemetry: Option<recorder_host::stream_fold::FoldStreamStats> = None;
    let mut replay_artifacts_telemetry: Option<replay_decoder::CertifiedReplayArtifacts> = None;
    let mut verify_report_telemetry: Option<snapshot::StreamVerifyReport> = None;
    match cfg.stream_format {
        StreamFormat::Compact if cfg.raw_debug_output => {
            // Raw debug stops at the durable capture boundary. The pipe writer
            // is closed, rollover publication (when active) has already sealed
            // and hashed the selected FirstWorld H4CR, and this receipt
            // independently rebinds the on-disk bytes to that capture hash.
            //
            // Do not fold, build H4IX/H4CP, reconstruct hours, or create a
            // compressed container here. replay_decoder consumes H4CR directly
            // if and when a later debugging action explicitly requests it.
            let receipt_path = publish_raw_debug_output_receipt(
                &cfg,
                &raw_path,
                &capture,
                hourly_met,
                &gate_problems,
                &manifest_path,
                &mut manifest,
            )?;
            eprintln!(
                "recorder raw debug H4CR sealed without fold, index, checkpoints, parity, or compression: {}",
                receipt_path.display()
            );
        }
        StreamFormat::Compact if uses_binary_replay_persistence(&cfg) => {
            // Production persistence is H4CR-first: no per-hour JSON spill is
            // created. replay_decoder folds the certified stream once into a
            // binary hourly offset index plus sparse checkpoints/bounded
            // deltas, then reconstructs every hour to prove exact byte parity
            // before packaging. The artifact spill is retained; finalization
            // never deletes its active evidence directory.
            let artifact_spill_dir = create_unique_replay_artifact_spill_dir(&cfg.out_dir)?;
            let artifacts = replay_decoder::build_certified_replay_artifacts(
                &raw_path,
                &artifact_spill_dir,
                &replay_game_id,
                capture_identity_mode,
                capture.byte_count,
                &capture.sha256,
                snapshot::DEFAULT_CHECKPOINT_INTERVAL_HOURS,
            )
            .map_err(|error| {
                let error = format!("build certified replay_decoder artifacts: {error}");
                mark_manifest_replay_not_produced(&manifest_path, &mut manifest, &error);
                error
            })?;
            verify_static_bundle_before_publication(
                static_bundle_admission.as_ref(),
                cfg.production,
            )?;
            let verify = write_native_replay_container_streaming(
                &cfg,
                &raw_path,
                &capture,
                &[],
                Some(&artifacts),
                None,
                capture_identity_mode,
                &manifest,
                &manifest_path,
                &replay_path,
            )
            .map_err(|error| {
                mark_manifest_replay_not_produced(&manifest_path, &mut manifest, &error);
                error
            })?;
            verify_report_telemetry = Some(verify);
            eprintln!(
                "recorder production replay_decoder artifacts retained at {} (hours={}, checkpoints={}, max_seek_deltas={}, legacy_json_bytes_avoided={})",
                artifact_spill_dir.display(),
                artifacts.hour_count,
                artifacts.checkpoint_count,
                artifacts.max_seek_deltas,
                artifacts.legacy_json_bytes_avoided,
            );
            replay_artifacts_telemetry = Some(artifacts);
        }
        StreamFormat::Compact if cfg.skip_host_fold => {
            // Production skip: the raw compact stream is the canonical artifact
            // (replay_decoder D1 folds per-hour on demand); pack the container
            // with an empty snapshots array and mark the skip EXPLICITLY in the
            // container index and the session manifest (host_fold_skipped).
            //
            // SEAL-TIME BOUNDARY GATE (container re-gate round 2, finding 3):
            // without a host fold nothing else would notice a torn/open-hour
            // tail before sealing, and the sealed-source read strictness would
            // then make the published container unreadable. A crash tail must
            // stay a raw recovery artifact.
            if let Err(e) = recorder_host::stream_fold::verify_stream_logical_boundary_with_identity_mode(
                &raw_path,
                capture_identity_mode,
            ) {
                let error = format!(
                    "refusing to seal (skip-fold): {e}; the raw stream stays the \
                     recovery artifact"
                );
                mark_manifest_replay_not_produced(&manifest_path, &mut manifest, &error);
                return Err(error);
            }
            verify_static_bundle_before_publication(
                static_bundle_admission.as_ref(),
                cfg.production,
            )?;
            match write_native_replay_container_streaming(
                &cfg,
                &raw_path,
                &capture,
                &[],
                None,
                None,
                capture_identity_mode,
                &manifest,
                &manifest_path,
                &replay_path,
            ) {
                Ok(verify) => {
                    verify_report_telemetry = Some(verify);
                }
                Err(error) => {
                    mark_manifest_replay_not_produced(&manifest_path, &mut manifest, &error);
                    return Err(error);
                }
            }
        }
        StreamFormat::Compact => {
            let snapshot_spill_dir = create_unique_snapshot_spill_dir(&cfg.out_dir)?;
            let replay_result = (|| -> Result<
                (
                    recorder_host::stream_fold::FoldStreamStats,
                    snapshot::StreamVerifyReport,
                ),
                String,
            > {
                // Bounded streaming fold over the on-disk stream: each hour's snapshot
                // is spilled to disk and released, so peak memory is O(world state)
                // per worker. This is POST-capture offline batch work, so the
                // parallel fold is used (the weaker-PC "don't lean on cores" law
                // binds capture-time per-frame work, not finalization).
                let (world_snapshot_files, fold_outcome) =
                    recorder_host::stream_fold::fold_compact_stream_file_parallel_with_identity_mode(
                        &raw_path,
                        &replay_game_id,
                        &snapshot_spill_dir,
                        recorder_host::stream_fold::default_fold_workers(),
                        capture_identity_mode,
                    )
                    .map_err(|e| format!("streaming fold failed: {e}"))?;
                validate_fold_campaign_identity_join(
                    &fold_outcome,
                    &manifest,
                    capture_identity_mode,
                )?;
                let fold_stats = fold_outcome.stats;
                // Same seal-time boundary law as the repack path: never seal
                // a source that does not end at a closed game hour.
                if fold_stats.truncated_tail_bytes > 0
                    || fold_stats.stop_reason.is_some()
                    || !fold_stats.ends_at_frame_end
                {
                    return Err(format!(
                        "refusing to seal: source does not end at a closed game hour \
                         (truncated_tail_bytes={}, stop_reason={:?}, ends_at_frame_end={})",
                        fold_stats.truncated_tail_bytes,
                        fold_stats.stop_reason,
                        fold_stats.ends_at_frame_end,
                    ));
                }
                verify_static_bundle_before_publication(
                    static_bundle_admission.as_ref(),
                    cfg.production,
                )?;
                let verify = write_native_replay_container_streaming(
                    &cfg,
                    &raw_path,
                    &capture,
                    &world_snapshot_files,
                    None,
                    Some(&fold_stats),
                    capture_identity_mode,
                    &manifest,
                    &manifest_path,
                    &replay_path,
                )?;
                Ok((fold_stats, verify))
            })();
            cleanup_snapshot_spill_dir(&snapshot_spill_dir);
            let (fold_stats, verify) = match replay_result {
                Ok(value) => value,
                Err(error) => {
                    mark_manifest_replay_not_produced(&manifest_path, &mut manifest, &error);
                    return Err(error);
                }
            };
            fold_stats_telemetry = Some(fold_stats);
            verify_report_telemetry = Some(verify);
        }
        StreamFormat::Json => {
            let world_snapshots = Vec::new();
            verify_static_bundle_before_publication(
                static_bundle_admission.as_ref(),
                cfg.production,
            )?;
            if let Err(error) = write_native_replay_container(
                &cfg,
                json_bytes.as_deref().unwrap_or(&[]),
                &world_snapshots,
                &manifest,
                &manifest_path,
                &replay_path,
            ) {
                mark_manifest_replay_not_produced(&manifest_path, &mut manifest, &error);
                return Err(error);
            }
        }
    }

    // G5 telemetry: record the host's peak private/working-set bytes plus the
    // streaming finalize accounting into native_session_manifest.json so bounded
    // memory is measurable from the manifest of every future run. Best-effort:
    // a telemetry write failure never fails an otherwise-good capture.
    write_host_finalize_telemetry(
        &manifest_path,
        &capture,
        finalize_started.elapsed(),
        fold_stats_telemetry.as_ref(),
        cfg.skip_host_fold && cfg.stream_format == StreamFormat::Compact,
        replay_artifacts_telemetry.as_ref(),
        verify_report_telemetry.as_ref(),
    );

    if let Some(descriptor) = rollover_set.as_ref() {
        if cfg.raw_debug_output {
            eprintln!(
                "recorder raw debug output: retaining {} sealed logical streams without compressed package-set publication",
                descriptor.ordered_streams.len()
            );
        } else {
            publish_rollover_package_set(
                &cfg,
                descriptor,
                &manifest_path,
                &manifest,
                &capture,
                capture_identity_mode,
                static_bundle_admission.as_ref(),
                first_recording_logical_stream_id.ok_or(
                    "rollover finalizer lost the logical stream id that admitted FirstWorld",
                )?,
            )?;
        }
        if cfg.production && !cfg.raw_debug_output {
            let product_root = cfg
                .out_dir
                .parent()
                .ok_or("production rollover run has no product-data parent")?;
            let stitch_reports =
                recorder_host::stitching::callsite::publish_registered_rollover_stitches(
                    product_root,
                    &cfg.out_dir,
                    descriptor,
                )?;
            for report in stitch_reports.published {
                eprintln!(
                    "recorder stitch: published={} segments={} visible_hours={} sha256={}",
                    report.published_path.display(),
                    report.segments,
                    report.visible_snapshot_hours,
                    report.container_sha256
                );
            }
            for reason in stitch_reports.kept_separate {
                eprintln!("recorder stitch: kept separate: {reason}");
            }
        }
    }

    if cfg.production && !cfg.raw_debug_output {
        if let Some(request) = cfg.design_catalog_live.as_ref() {
            if let Err(error) = fs::remove_file(&request.path) {
                eprintln!(
                    "recorder warning: packed A27 source cleanup failed for {}: {error}",
                    request.path.display()
                );
            }
        }
        let owned_dir = cfg.out_dir.join("recorder_owned");
        let _ = fs::remove_dir(&owned_dir);
    }

    // The ordinary root finalizer necessarily owns logical stream zero. During
    // Continue that segment can be a loading-world transient which never
    // admitted FirstWorld; the rollover package-set finalizer above is the
    // recording authority and has already failed if any admitted member failed.
    if !hourly_met
        && !acceptance_test_met
        && (cfg.raw_debug_output || rollover_set.is_none())
    {
        let quarantine_detail = normal_quarantine
            .as_ref()
            .filter(|report| report.attempted && !report.ok)
            .map(|report| {
                format!(
                    "; normal replay quarantine failed for {}: {}; stale normal may remain",
                    report.old_file,
                    report.error.as_deref().unwrap_or("unknown")
                )
            })
            .unwrap_or_default();
        let artifact_detail = if cfg.raw_debug_output {
            format!("raw debug stream retained at {}", raw_path.display())
        } else {
            format!(
                "recovery replay written to {}; normal replay not updated at {}",
                replay_path.display(),
                normal_replay_path.display()
            )
        };
        return Err(format!(
            "hourly requirement not met; {artifact_detail}; manifest written to {}; problems={}{}",
            manifest_path.display(),
            if gate_problems.is_empty() {
                "unspecified".to_string()
            } else {
                gate_problems.join(",")
            },
            quarantine_detail
        ));
    }
    if rollover_set.is_some() && !cfg.raw_debug_output {
        println!(
            "{}",
            cfg.out_dir
                .join(recorder_host::duplex_session::rollover_fs::PACKAGE_SET_DESCRIPTOR_FILE)
                .display()
        );
    } else {
        println!("{}", manifest_path.display());
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn write_diagnostic_probe_receipt(
    cfg: &Config,
    process: &recorder_host::early_render_launch::EarlyRenderProcess,
    staged_hook_group_mask: u64,
    phase: &str,
    required_hold_ms: u64,
    observed_hold_ms: u64,
    target_alive: bool,
    terminated_by_host: bool,
    end_liveness_proof: Option<&recorder_host::early_render_launch::EarlyDiagnosticLivenessProof>,
    diagnostic_end_sent: bool,
    file_name: &str,
) -> Result<(), String> {
    if diagnostic_end_sent != end_liveness_proof.is_some() {
        return Err("diagnostic receipt END state differs from its liveness proof presence".into());
    }
    if let Some(proof) = end_liveness_proof {
        proof.validate_for(&process.receipt, required_hold_ms)?;
    }
    let receipt_sha256 = process.receipt.sha256()?;
    let document = json!({
        "schema": "extractor.diagnostic-no-commit-probe.v1",
        "admissible_for_production": false,
        "phase": phase,
        "session_id": cfg.session_id,
        "capture_id": cfg.capture_id,
        "process_id": process.process_id,
        "process_start_nonce": process.receipt.process_start_nonce,
        "owned_process_handle_identity_bound": true,
        "kill_on_close_job_armed": true,
        "diagnostic_stage_probe": true,
        "staged_hook_group_mask": staged_hook_group_mask,
        "staged_hook_group_mask_hex": format!("0x{staged_hook_group_mask:02x}"),
        "staged_hook_count": process.receipt.staged_hook_count,
        "staged_hook_set_sha256": process.receipt.staged_hook_set_sha256,
        "first_game_d3d_validated": true,
        "runtime_dlc_roster_double_stable_validated": process.receipt.effective_runtime_dlc.double_stable,
        "commit_sent": false,
        "diagnostic_liveness_request_sent": end_liveness_proof.is_some(),
        "diagnostic_liveness_response_validated": end_liveness_proof.is_some(),
        "diagnostic_end_sent": diagnostic_end_sent,
        "end_liveness_proof": end_liveness_proof,
        "capture_stream_admitted": false,
        "replay_created": false,
        "required_hold_ms": required_hold_ms,
        "observed_hold_ms": observed_hold_ms,
        "target_alive_at_receipt": target_alive,
        "target_terminated_by_host": terminated_by_host,
        "early_capture_receipt_sha256": receipt_sha256,
        "early_capture_receipt": &process.receipt,
    });
    let bytes = serde_json::to_vec_pretty(&document)
        .map_err(|error| format!("serialize diagnostic no-COMMIT receipt failed: {error}"))?;
    let path = cfg.out_dir.join(file_name);
    let temp = cfg
        .out_dir
        .join(format!(".{file_name}.{}.tmp", std::process::id()));
    let mut file = fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&temp)
        .map_err(|error| format!("create diagnostic receipt temp failed: {error}"))?;
    file.write_all(&bytes)
        .and_then(|_| file.write_all(b"\n"))
        .and_then(|_| file.sync_all())
        .map_err(|error| format!("durably write diagnostic receipt failed: {error}"))?;
    drop(file);
    fs::rename(&temp, &path).map_err(|error| {
        format!(
            "publish diagnostic receipt {} failed: {error}",
            path.display()
        )
    })?;
    Ok(())
}

fn write_sink_failure_acceptance_plan(cfg: &Config, pipe_token: &str) -> Result<(), String> {
    let Some(acceptance) = cfg
        .acceptance_test
        .as_ref()
        .filter(|acceptance| acceptance.mode.is_sink_fault())
    else {
        return Ok(());
    };
    let early_launch = cfg
        .early_launch
        .as_ref()
        .ok_or_else(|| "sink-failure plan requires an early-launch process".to_string())?;
    let mode = acceptance.mode.as_str();
    let authorization = acceptance_test_authorization(
        pipe_token,
        &cfg.session_id,
        mode,
        &acceptance.nonce,
    );
    let collector_dll_sha256 = to_hex(&hash_file_sha256_bytes(&cfg.dll)?);
    let game_executable_sha256 =
        to_hex(&hash_file_sha256_bytes(&early_launch.executable)?);
    let recorder_executable = env::current_exe()
        .map_err(|error| format!("sink-failure recorder current_exe failed: {error}"))?;
    let recorder_executable_sha256 =
        to_hex(&hash_file_sha256_bytes(&recorder_executable)?);
    let collector_dll_file = cfg
        .dll
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| "sink-failure collector DLL has no portable leaf name".to_string())?;
    let game_executable_file = early_launch
        .executable
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| "sink-failure game executable has no portable leaf name".to_string())?;
    let recorder_executable_file = recorder_executable
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| "sink-failure recorder executable has no portable leaf name".to_string())?;
    let document = json!({
        "schema": "extractor.sink-failure-acceptance-plan.v1",
        "admissible_for_production": false,
        "mode": mode,
        "nonce": acceptance.nonce,
        "control_authorization_v1": authorization,
        "session_id": cfg.session_id,
        "capture_id": cfg.capture_id,
        "process_id": cfg.pid,
        "game_executable_file": game_executable_file,
        "game_executable_sha256": game_executable_sha256,
        "recorder_executable_file": recorder_executable_file,
        "recorder_executable_sha256": recorder_executable_sha256,
        "collector_dll_file": collector_dll_file,
        "collector_dll_sha256": collector_dll_sha256,
        "expected_receipt_schema": "extractor.authenticated-sink-failure.v2",
        "expected_topology": "sole_pipe",
        "expected_terminality": "attempt_terminal",
    });
    let bytes = serde_json::to_vec_pretty(&document)
        .map_err(|error| format!("serialize sink-failure acceptance plan: {error}"))?;
    let path = cfg.out_dir.join("sink_failure_acceptance_plan.json");
    let mut file = fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&path)
        .map_err(|error| format!("create sink-failure acceptance plan: {error}"))?;
    if let Err(error) = file
        .write_all(&bytes)
        .and_then(|_| file.write_all(b"\n"))
        .and_then(|_| file.sync_all())
    {
        drop(file);
        let _ = fs::remove_file(&path);
        return Err(format!("durably write sink-failure acceptance plan: {error}"));
    }
    Ok(())
}

fn write_authenticated_sink_failure_receipt(
    cfg: &Config,
    pipe_token: &str,
    report: &recorder_host::transport_status::SinkFailureReport,
) -> Result<PathBuf, String> {
    let acceptance_plan_sha256 = match cfg.acceptance_test.as_ref() {
        Some(acceptance) if acceptance.mode.is_sink_fault() => Some(to_hex(
            &hash_file_sha256_bytes(&cfg.out_dir.join("sink_failure_acceptance_plan.json"))?,
        )),
        _ => None,
    };
    let acceptance_test = cfg.acceptance_test.as_ref().map(|acceptance| {
        let mode = acceptance.mode.as_str();
        let authorization = acceptance_test_authorization(
            pipe_token,
            &cfg.session_id,
            mode,
            &acceptance.nonce,
        );
        json!({
            "mode": mode,
            "nonce": acceptance.nonce,
            "control_authorization_v1": authorization,
            "acceptance_plan_sha256": acceptance_plan_sha256.clone(),
            "report_matches_armed_fault": sink_failure_matches_acceptance_mode(
                acceptance.mode,
                report,
            ),
        })
    });
    let document = json!({
        "schema": "extractor.authenticated-sink-failure.v2",
        "admissible_for_production": false,
        "attempt_terminal": true,
        "authenticated_h4ct_session": true,
        "session_id": cfg.session_id,
        "capture_id": cfg.capture_id,
        "process_id": cfg.pid,
        "kind": format!("{:?}", report.kind),
        "requested_bits": report.requested.bits(),
        "opened_bits": report.opened.bits(),
        "failed_bits": report.failed.bits(),
        "error_class": format!("{:?}", report.error_class),
        "win32_error": report.win32_error,
        "last_complete_sequence": report.last_complete_sequence,
        "failed_sequence": report.failed_sequence,
        "file_bytes_committed": report.file_bytes_committed,
        "pipe_bytes_committed": report.pipe_bytes_committed,
        "replay_created": false,
        "acceptance_test": acceptance_test,
    });
    let bytes = serde_json::to_vec_pretty(&document)
        .map_err(|error| format!("serialize authenticated sink-failure receipt: {error}"))?;
    let path = cfg.out_dir.join("collector_sink_failure.json");
    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let temp = cfg.out_dir.join(format!(
        ".collector_sink_failure.{}.{}.tmp",
        std::process::id(),
        nonce
    ));
    let mut file = fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&temp)
        .map_err(|error| format!("create sink-failure receipt temp: {error}"))?;
    if let Err(error) = file
        .write_all(&bytes)
        .and_then(|_| file.write_all(b"\n"))
        .and_then(|_| file.sync_all())
    {
        drop(file);
        let _ = fs::remove_file(&temp);
        return Err(format!("durably write sink-failure receipt: {error}"));
    }
    drop(file);
    if let Err(error) = fs::rename(&temp, &path) {
        let _ = fs::remove_file(&temp);
        return Err(format!(
            "publish sink-failure receipt {}: {error}",
            path.display()
        ));
    }
    Ok(path)
}

fn sink_failure_matches_acceptance_mode(
    mode: AcceptanceTestMode,
    report: &recorder_host::transport_status::SinkFailureReport,
) -> bool {
    use recorder_host::transport_status::{SinkErrorClass, SinkFailureKind, SinkTopology};
    let sole_pipe = report.requested.bits() == SinkTopology::PIPE
        && report.failed.bits() == SinkTopology::PIPE
        && report.file_bytes_committed == 0;
    match mode {
        AcceptanceTestMode::SinkOpenFault => {
            sole_pipe
                && report.kind == SinkFailureKind::Setup
                && report.opened.bits() == 0
                && report.error_class == SinkErrorClass::OtherIo
                && report.win32_error.is_none()
                && report.last_complete_sequence.is_none()
                && report.failed_sequence.is_none()
                && report.pipe_bytes_committed == 0
        }
        AcceptanceTestMode::SinkWriteFault => {
            sole_pipe
                && report.kind == SinkFailureKind::Terminal
                && report.opened.bits() == SinkTopology::PIPE
                && report.error_class == SinkErrorClass::OtherIo
                && report.win32_error.is_none()
                && report.pipe_bytes_committed > 0
                && report
                    .last_complete_sequence
                    .zip(report.failed_sequence)
                    .is_some_and(|(last, failed)| last.checked_add(1) == Some(failed))
        }
        AcceptanceTestMode::SyntheticFault | AcceptanceTestMode::Paused => false,
    }
}

fn parse_repack_args(args: &[String]) -> Result<RepackConfig, String> {
    if args.len() < 2 || args[0] != "--fold-and-repack-existing-run-dir" {
        return Err(
            "usage: collector_record --fold-and-repack-existing-run-dir RUN_DIR [--workers N] [static artifact flags] [--design-catalog-live path]"
                .to_string(),
        );
    }

    let run_dir = PathBuf::from(&args[1]);
    let mut workers = recorder_host::stream_fold::default_fold_workers();
    let mut static_templates_equipment_catalog: Option<PathBuf> = None;
    let mut static_localisation_join: Option<PathBuf> = None;
    let mut static_decisions_definitions: Option<PathBuf> = None;
    let mut static_idea_tech_loc_xref: Option<PathBuf> = None;
    let mut static_ship_definitions: Option<PathBuf> = None;
    let mut static_gfx_icon_manifest: Option<PathBuf> = None;
    let mut design_catalog_live: Option<PathBuf> = None;
    let mut static_bundle_manifest: Option<PathBuf> = None;
    let mut static_bundle_mod_state: Option<PathBuf> = None;
    let mut static_bundle_dlc_state: Option<PathBuf> = None;
    let mut static_bundle_load_order: Option<PathBuf> = None;
    let mut static_bundle_source_inventory: Option<PathBuf> = None;
    let mut static_bundle_live_resolution_report: Option<PathBuf> = None;
    let mut portable_content_use_trace: Option<PathBuf> = None;
    let mut static_bundle_verifier: Option<PathBuf> = None;
    let mut static_bundle_python: Option<OsString> = None;
    let mut static_bundle_timeout_ms: u64 = 30_000;
    let mut i = 2usize;
    while i < args.len() {
        match args[i].as_str() {
            "--workers" => {
                i += 1;
                workers = required(args.get(i), "--workers")?
                    .parse::<usize>()
                    .map_err(|e| format!("--workers expects a positive integer: {e}"))?;
                if workers == 0 {
                    return Err("--workers must be >= 1".to_string());
                }
            }
            "--static-templates-equipment-catalog" => {
                if static_templates_equipment_catalog.is_some() {
                    return Err(
                        "duplicate --static-templates-equipment-catalog is not allowed".to_string(),
                    );
                }
                i += 1;
                static_templates_equipment_catalog =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-localisation-join" => {
                if static_localisation_join.is_some() {
                    return Err("duplicate --static-localisation-join is not allowed".to_string());
                }
                i += 1;
                static_localisation_join =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-decisions-definitions" => {
                if static_decisions_definitions.is_some() {
                    return Err(
                        "duplicate --static-decisions-definitions is not allowed".to_string()
                    );
                }
                i += 1;
                static_decisions_definitions =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-idea-tech-loc-xref" => {
                if static_idea_tech_loc_xref.is_some() {
                    return Err("duplicate --static-idea-tech-loc-xref is not allowed".to_string());
                }
                i += 1;
                static_idea_tech_loc_xref =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-ship-definitions" => {
                if static_ship_definitions.is_some() {
                    return Err("duplicate --static-ship-definitions is not allowed".to_string());
                }
                i += 1;
                static_ship_definitions = Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-gfx-icon-manifest" => {
                if static_gfx_icon_manifest.is_some() {
                    return Err("duplicate --static-gfx-icon-manifest is not allowed".to_string());
                }
                i += 1;
                static_gfx_icon_manifest =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--design-catalog-live" => {
                if design_catalog_live.is_some() {
                    return Err("duplicate --design-catalog-live is not allowed".to_string());
                }
                i += 1;
                design_catalog_live = Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-manifest" => {
                i += 1;
                static_bundle_manifest = Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-mod-state" => {
                i += 1;
                static_bundle_mod_state = Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-dlc-state" => {
                i += 1;
                static_bundle_dlc_state = Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-load-order" => {
                i += 1;
                static_bundle_load_order =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-source-inventory" => {
                i += 1;
                static_bundle_source_inventory =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-live-resolution-report" => {
                i += 1;
                static_bundle_live_resolution_report =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--portable-content-use-trace" => {
                i += 1;
                portable_content_use_trace =
                    Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-verifier" => {
                i += 1;
                static_bundle_verifier = Some(PathBuf::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-python" => {
                i += 1;
                static_bundle_python = Some(OsString::from(required(args.get(i), &args[i - 1])?));
            }
            "--static-bundle-timeout-ms" => {
                i += 1;
                static_bundle_timeout_ms =
                    parse_static_bundle_timeout_ms(args.get(i), &args[i - 1])?;
            }
            other => return Err(format!("unknown fold-and-repack flag {other}")),
        }
        i += 1;
    }

    let mut static_artifacts = Vec::new();
    if let Some(path) = static_templates_equipment_catalog {
        static_artifacts.push(StaticArtifactRequest {
            name: STATIC_ARTIFACT_TEMPLATES_EQUIPMENT_CATALOG,
            path,
            expected_sha256: None,
        });
    }
    if let Some(path) = static_localisation_join {
        static_artifacts.push(StaticArtifactRequest {
            name: STATIC_ARTIFACT_LOCALISATION_JOIN,
            path,
            expected_sha256: None,
        });
    }
    if let Some(path) = static_decisions_definitions {
        static_artifacts.push(StaticArtifactRequest {
            name: STATIC_ARTIFACT_DECISIONS_STATIC_DEFINITIONS,
            path,
            expected_sha256: None,
        });
    }
    if let Some(path) = static_idea_tech_loc_xref {
        static_artifacts.push(StaticArtifactRequest {
            name: STATIC_ARTIFACT_IDEA_TECH_LOC_XREF_STATIC,
            path,
            expected_sha256: None,
        });
    }
    if let Some(path) = static_ship_definitions {
        static_artifacts.push(StaticArtifactRequest {
            name: STATIC_ARTIFACT_SHIP_DEFINITIONS_STATIC,
            path,
            expected_sha256: None,
        });
    }
    if let Some(path) = static_gfx_icon_manifest {
        static_artifacts.push(StaticArtifactRequest {
            name: STATIC_ARTIFACT_GFX_ICON_MANIFEST,
            path,
            expected_sha256: None,
        });
    }

    let static_bundle = assemble_static_bundle_cli(
        static_bundle_manifest,
        static_bundle_mod_state,
        static_bundle_dlc_state,
        static_bundle_load_order,
        static_bundle_source_inventory,
        static_bundle_live_resolution_report,
        portable_content_use_trace,
        static_bundle_verifier,
        static_bundle_python,
        Duration::from_millis(static_bundle_timeout_ms),
    )?;
    if static_bundle.is_some() && !static_artifacts.is_empty() {
        return Err(
            "fold-and-repack static bundle cannot be combined with loose static artifacts"
                .to_string(),
        );
    }
    Ok(RepackConfig {
        run_dir,
        workers,
        static_artifacts,
        design_catalog_live: design_catalog_live.map(|path| DesignCatalogLiveRequest {
            path,
            expected_sha256: None,
        }),
        static_bundle,
    })
}

fn replay_packaging_manifest_json(
    cfg: &Config,
    g2: Option<&recorder_host::early_render_launch::G2CaptureArtifactSeal>,
    replay_content_manifest_digest_sha256: Option<&str>,
) -> Result<Value, String> {
    let game_id = replay_game_id(&cfg.session_id);
    let mut static_artifacts = Vec::with_capacity(cfg.static_artifacts.len());
    for request in &cfg.static_artifacts {
        let resolved = resolve_static_artifact(&game_id, request)?;
        static_artifacts.push(json!({
            "name": request.name,
            "path": resolved.payload_path,
            "sha256": to_hex(&Sha256::digest(&resolved.bytes)),
            "bytes": resolved.bytes.len() as u64,
            "content_manifest_digest_sha256": replay_content_manifest_digest_sha256,
        }));
    }
    let design_catalog_live = cfg
        .design_catalog_live
        .as_ref()
        .map(resolve_design_catalog_live)
        .transpose()?
        .map(|resolved| {
            let source_schema = resolved.index_descriptor["source_schema"].clone();
            let first_capture_hour_index =
                resolved.index_descriptor["first_capture_hour_index"].clone();
            let last_capture_hour_index =
                resolved.index_descriptor["last_capture_hour_index"].clone();
            let capture_count = resolved.index_descriptor["capture_count"].clone();
            json!({
                "schema": snapshot::design_catalog::PORTABLE_DESIGN_CATALOG_SCHEMA,
                "source_schema": source_schema,
                "path": snapshot::design_catalog::PORTABLE_ARTIFACT_PATH,
                "sha256": resolved.sha256,
                "source_sha256": resolved.source_sha256,
                "bytes": resolved.bytes.len() as u64,
                "content_manifest_digest_sha256": replay_content_manifest_digest_sha256,
                "first_capture_hour_index": first_capture_hour_index,
                "last_capture_hour_index": last_capture_hour_index,
                "capture_count": capture_count,
            })
        });
    let g2_engine_capture = g2
        .map(|seal| {
            let replay_content_digest = replay_content_manifest_digest_sha256
                .filter(|value| is_lower_sha256(value))
                .ok_or("G2 packaging has no finalized replay content manifest digest")?;
            Ok::<Value, String>(json!({
            "schema": G2_PACKAGED_CAPTURE_SCHEMA,
            "witness_path": G2_PACKAGED_WITNESS_PATH,
            "witness_sha256": seal.witness_sha256.as_str(),
            "witness_bytes": seal.witness_bytes,
            "bmp_path": G2_PACKAGED_BMP_PATH,
            "bmp_sha256": seal.bmp_sha256.as_str(),
            "bmp_bytes": seal.bmp_bytes,
            "capture_content_manifest_digest_sha256": seal.capture_content_manifest_digest_sha256.as_str(),
            "replay_content_manifest_digest_sha256": replay_content_digest,
        }))
        })
        .transpose()?;
    Ok(json!({
        "created_utc": created_utc_label(),
        "mode": if cfg.raw_debug_output {
            "raw_debug_uncompressed"
        } else {
            "portable_zstd_container"
        },
        "container_emitted": !cfg.raw_debug_output,
        "compression_applied": !cfg.raw_debug_output,
        "compression": {
            "zstd_level": cfg.compression_profile.zstd_level,
            "zstd_window_log": cfg.compression_profile.zstd_window_log,
            "purpose": if cfg.raw_debug_output {
                "deferred_repack_profile_only"
            } else {
                "applied_to_portable_container"
            },
        },
        "static_artifacts": static_artifacts,
        "design_catalog_live": design_catalog_live,
        "g2_engine_capture": g2_engine_capture,
    }))
}

fn recorded_design_catalog_live_sha256(
    manifest: &Value,
) -> Result<Option<(String, String)>, String> {
    let Some(value) = manifest
        .get("replay_packaging")
        .and_then(|value| value.get("design_catalog_live"))
    else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    if value.get("schema").and_then(Value::as_str)
        != Some(snapshot::design_catalog::PORTABLE_DESIGN_CATALOG_SCHEMA)
        || !matches!(
            value.get("source_schema").and_then(Value::as_str),
            Some(snapshot::design_catalog::A27_LIVE_CATALOG_SCHEMA)
                | Some(snapshot::design_catalog::A27_LIVE_CATALOG_TIMELINE_SCHEMA)
        )
        || value.get("path").and_then(Value::as_str)
            != Some(snapshot::design_catalog::PORTABLE_ARTIFACT_PATH)
    {
        return Err("manifest replay_packaging.design_catalog_live identity is invalid".into());
    }
    let sha256 = value
        .get("sha256")
        .and_then(Value::as_str)
        .filter(|sha| is_lower_sha256(sha))
        .ok_or_else(|| {
            "manifest replay_packaging.design_catalog_live sha256 is invalid".to_string()
        })?;
    let source_sha256 = value
        .get("source_sha256")
        .and_then(Value::as_str)
        .filter(|sha| is_lower_sha256(sha))
        .ok_or_else(|| {
            "manifest replay_packaging.design_catalog_live source_sha256 is invalid".to_string()
        })?;
    Ok(Some((sha256.to_string(), source_sha256.to_string())))
}

fn resolve_recorded_design_catalog_live(
    cfg: &Config,
    manifest: &Value,
) -> Result<Option<ResolvedDesignCatalogLive>, String> {
    let recorded = recorded_design_catalog_live_sha256(manifest)?;
    match (cfg.design_catalog_live.as_ref(), recorded.as_ref()) {
        (None, None) => Ok(None),
        (Some(_), None) => Err(
            "A27 live design catalog was supplied at pack time but is absent from the capture-time replay seal"
                .into(),
        ),
        (None, Some(_)) => Err(
            "capture-time replay seal requires an A27 live design catalog, but no file was supplied"
                .into(),
        ),
        (Some(request), Some((expected, expected_source))) => {
            let resolved = resolve_design_catalog_live(request)?;
            if resolved.sha256 != *expected || resolved.source_sha256 != *expected_source {
                return Err(format!(
                    "A27 live design catalog changed since capture seal: recorded payload/source {expected}/{expected_source} current payload/source {}/{}",
                    resolved.sha256, resolved.source_sha256
                ));
            }
            Ok(Some(resolved))
        }
    }
}

fn replay_packaging_created_utc(manifest: &Value) -> Option<String> {
    manifest
        .get("replay_packaging")
        .and_then(|value| value.get("created_utc"))
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string)
}

fn recorded_portable_content_manifest(
    manifest: &Value,
) -> Result<Option<portable_content_manifest::ContentManifest>, String> {
    match manifest.get("portable_content_manifest") {
        None | Some(Value::Null) => Ok(None),
        Some(value) => {
            let content: portable_content_manifest::ContentManifest =
                serde_json::from_value(value.clone()).map_err(|error| {
                    format!("session portable_content_manifest is malformed: {error}")
                })?;
            content.validate().map_err(|error| {
                format!("session portable_content_manifest failed validation: {error}")
            })?;
            if content.manifest_digest_sha256.is_none() {
                return Err(
                    "session portable_content_manifest is not finalized with a digest".into(),
                );
            }
            Ok(Some(content))
        }
    }
}

fn recorded_replay_compression_profile(manifest: &Value) -> Result<CompressionProfile, String> {
    let compression = manifest
        .get("replay_packaging")
        .and_then(|value| value.get("compression"))
        .ok_or_else(|| "manifest replay_packaging.compression is missing".to_string())?;
    let zstd_level = compression
        .get("zstd_level")
        .and_then(Value::as_i64)
        .and_then(|value| i32::try_from(value).ok())
        .ok_or_else(|| "manifest replay_packaging.compression.zstd_level is invalid".to_string())?;
    let zstd_window_log = compression
        .get("zstd_window_log")
        .and_then(Value::as_u64)
        .and_then(|value| u32::try_from(value).ok())
        .ok_or_else(|| {
            "manifest replay_packaging.compression.zstd_window_log is invalid".to_string()
        })?;
    let profile = CompressionProfile {
        zstd_level,
        zstd_window_log,
    };
    profile
        .validate()
        .map_err(|e| format!("manifest replay compression profile is invalid: {e}"))?;
    Ok(profile)
}

fn read_stable_g2_packaging_file(path: &Path, label: &str) -> Result<Vec<u8>, String> {
    let metadata = fs::symlink_metadata(path)
        .map_err(|error| format!("read packaged G2 {label} metadata failed: {error}"))?;
    if !metadata.file_type().is_file() || metadata.file_type().is_symlink() {
        return Err(format!("packaged G2 {label} is not a regular non-symlink file"));
    }
    let first = fs::read(path)
        .map_err(|error| format!("read packaged G2 {label} failed: {error}"))?;
    let second = fs::read(path)
        .map_err(|error| format!("re-read packaged G2 {label} failed: {error}"))?;
    if first != second {
        return Err(format!("packaged G2 {label} changed while being read"));
    }
    Ok(first)
}

fn resolve_recorded_g2_engine_capture(
    cfg: &Config,
    manifest: &Value,
) -> Result<Option<ResolvedG2EngineCapture>, String> {
    let recorded = manifest
        .get("replay_packaging")
        .and_then(|value| value.get("g2_engine_capture"));
    let Some(recorded) = recorded.filter(|value| !value.is_null()) else {
        if cfg.g2_capture_intent.is_some() {
            return Err("requested G2 capture is absent from the capture-time replay seal".into());
        }
        return Ok(None);
    };
    let object = recorded
        .as_object()
        .ok_or("manifest replay_packaging.g2_engine_capture is not an object")?;
    let expected_fields = BTreeSet::from([
        "schema",
        "witness_path",
        "witness_sha256",
        "witness_bytes",
        "bmp_path",
        "bmp_sha256",
        "bmp_bytes",
        "capture_content_manifest_digest_sha256",
        "replay_content_manifest_digest_sha256",
    ]);
    let observed_fields = object.keys().map(String::as_str).collect::<BTreeSet<_>>();
    if observed_fields != expected_fields
        || object.get("schema").and_then(Value::as_str) != Some(G2_PACKAGED_CAPTURE_SCHEMA)
        || object.get("witness_path").and_then(Value::as_str)
            != Some(G2_PACKAGED_WITNESS_PATH)
        || object.get("bmp_path").and_then(Value::as_str) != Some(G2_PACKAGED_BMP_PATH)
    {
        return Err("manifest packaged G2 identity fields drifted".into());
    }
    let expected_witness_sha256 = object
        .get("witness_sha256")
        .and_then(Value::as_str)
        .filter(|value| is_lower_sha256(value))
        .ok_or("manifest packaged G2 witness SHA-256 is invalid")?;
    let expected_bmp_sha256 = object
        .get("bmp_sha256")
        .and_then(Value::as_str)
        .filter(|value| is_lower_sha256(value))
        .ok_or("manifest packaged G2 BMP SHA-256 is invalid")?;
    let expected_witness_bytes = object
        .get("witness_bytes")
        .and_then(Value::as_u64)
        .ok_or("manifest packaged G2 witness byte count is invalid")?;
    let expected_bmp_bytes = object
        .get("bmp_bytes")
        .and_then(Value::as_u64)
        .ok_or("manifest packaged G2 BMP byte count is invalid")?;
    let capture_content_digest = object
        .get("capture_content_manifest_digest_sha256")
        .and_then(Value::as_str)
        .filter(|value| is_lower_sha256(value))
        .ok_or("manifest packaged G2 capture content digest is invalid")?;
    let replay_content_digest = object
        .get("replay_content_manifest_digest_sha256")
        .and_then(Value::as_str)
        .filter(|value| is_lower_sha256(value))
        .ok_or("manifest packaged G2 replay content digest is invalid")?;
    if manifest
        .get("portable_content_manifest")
        .and_then(|value| value.get("manifest_digest_sha256"))
        .and_then(Value::as_str)
        != Some(replay_content_digest)
    {
        return Err("packaged G2 replay content digest differs from recorder manifest".into());
    }
    let source = absolute_run_g2_output_directory(&cfg.out_dir)?;
    let witness_bytes = read_stable_g2_packaging_file(
        &source.join(recorder_host::early_render_launch::G2_ENGINE_WITNESS_FILE),
        "witness",
    )?;
    let bmp_bytes = read_stable_g2_packaging_file(
        &source.join(recorder_host::early_render_launch::G2_ENGINE_BMP_FILE),
        "BMP",
    )?;
    if witness_bytes.len() as u64 != expected_witness_bytes
        || bmp_bytes.len() as u64 != expected_bmp_bytes
        || to_hex(&Sha256::digest(&witness_bytes)) != expected_witness_sha256
        || to_hex(&Sha256::digest(&bmp_bytes)) != expected_bmp_sha256
    {
        return Err("packaged G2 source bytes differ from the capture-time replay seal".into());
    }
    let witness = snapshot::parse_json_strict(&witness_bytes)
        .map_err(|error| format!("strict parse packaged G2 witness failed: {error}"))?;
    if witness
        .get("content_manifest_digest_sha256")
        .and_then(Value::as_str)
        != Some(capture_content_digest)
    {
        return Err("packaged G2 capture digest differs from the raw witness".into());
    }
    Ok(Some(ResolvedG2EngineCapture {
        witness_bytes,
        bmp_bytes,
        index_descriptor: recorded.clone(),
    }))
}

fn recorded_static_artifacts(manifest: &Value) -> Result<Vec<(String, String)>, String> {
    manifest
        .get("replay_packaging")
        .and_then(|value| value.get("static_artifacts"))
        .and_then(Value::as_array)
        .ok_or_else(|| "manifest replay_packaging.static_artifacts is missing".to_string())?
        .iter()
        .map(|value| {
            let name = value
                .get("name")
                .and_then(Value::as_str)
                .filter(|name| !name.is_empty())
                .ok_or_else(|| {
                    "manifest replay_packaging.static_artifacts contains an invalid name"
                        .to_string()
                })?;
            let sha256 = value
                .get("sha256")
                .and_then(Value::as_str)
                .filter(|sha| sha.len() == 64 && sha.bytes().all(|byte| byte.is_ascii_hexdigit()))
                .ok_or_else(|| {
                    format!(
                        "manifest replay_packaging static artifact {name:?} has an invalid sha256"
                    )
                })?;
            Ok((name.to_string(), sha256.to_ascii_lowercase()))
        })
        .collect()
}

