#[derive(Debug, Clone, PartialEq, Eq)]
struct CompactExpectedPartialToleranceApplied {
    domain_id: u16,
    domain: &'static str,
    tolerated_flags: u32,
    reason: &'static str,
    frames_affected: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CompactGateStatus {
    failure_status_flags_or: u32,
    expected_partial_tolerances_applied: Vec<CompactExpectedPartialToleranceApplied>,
}

fn compact_gate_status(summary: &CompactSummary) -> CompactGateStatus {
    let mut failure_status_flags_or =
        summary.frame_end_status_flags_or & COMPACT_STATUS_FAILURE_MASK;
    let mut expected_partial_tolerances_applied = Vec::new();

    for (domain_id, domain) in &summary.per_domain {
        if !domain.expected_partial_tolerance_hours.is_empty() {
            let tolerance = compact_contract::expected_partial_tolerance(*domain_id)
                .expect("applied tolerance hours require a tolerance");
            expected_partial_tolerances_applied.push(CompactExpectedPartialToleranceApplied {
                domain_id: *domain_id,
                domain: compact_domain_name(*domain_id),
                tolerated_flags: tolerance.tolerated_flags,
                reason: tolerance.reason,
                frames_affected: domain.expected_partial_tolerance_hours.len(),
            });
        }
        if compact_contract::expected_partial_tolerance(*domain_id).is_some() {
            failure_status_flags_or |= domain.effective_failure_status_flags_or;
        } else {
            failure_status_flags_or |= compact_contract::compact_status_for_global_interpretation(
                *domain_id,
                domain.status_flags_or,
            ) & COMPACT_STATUS_FAILURE_MASK;
        }
    }

    CompactGateStatus {
        failure_status_flags_or,
        expected_partial_tolerances_applied,
    }
}

fn compact_expected_partial_tolerances_applied_json(summary: &CompactSummary) -> Value {
    let gate_status = compact_gate_status(summary);
    Value::Array(
        gate_status
            .expected_partial_tolerances_applied
            .iter()
            .map(|applied| {
                json!({
                    "domain": applied.domain,
                    "domain_id": applied.domain_id,
                    "tolerated_flags": applied.tolerated_flags,
                    "reason": applied.reason,
                    "frames_affected": applied.frames_affected,
                })
            })
            .collect(),
    )
}

#[cfg(test)]
fn compact_expected_partial_tolerance_domain_names(summary: &CompactSummary) -> Vec<&'static str> {
    compact_gate_status(summary)
        .expected_partial_tolerances_applied
        .iter()
        .map(|applied| applied.domain)
        .collect()
}

fn compact_profile_unfolded_domains(summary: &CompactSummary) -> BTreeSet<u16> {
    let profile_ids: BTreeSet<u16> = compact_contract::production_profile_domains()
        .into_iter()
        .map(|descriptor| descriptor.id)
        .collect();
    summary
        .unfolded_domain_data
        .intersection(&profile_ids)
        .copied()
        .collect()
}

fn domain57_frame_evidence_json(summary: &CompactSummary) -> Value {
    const REQUIRED_ROOT_MASK: u32 = 0x7;
    let mut speed_values = BTreeMap::<String, u64>::new();
    let mut pause_values = BTreeMap::<String, u64>::new();
    let mut root_masks = BTreeMap::<String, u64>::new();
    let mut speed_rows_per_record = BTreeMap::<String, u64>::new();
    let mut pause_rows_per_record = BTreeMap::<String, u64>::new();
    let mut records_per_closed_frame = BTreeMap::<String, u64>::new();
    let mut records_by_hour = BTreeMap::<i32, usize>::new();
    for record in &summary.domain57_frames {
        *records_by_hour.entry(record.header_hour_raw).or_default() += 1;
        *root_masks
            .entry(format!("0x{:08x}", record.root_evidence_mask))
            .or_default() += 1;
        *speed_rows_per_record
            .entry(record.speed_rows.len().to_string())
            .or_default() += 1;
        *pause_rows_per_record
            .entry(record.pause_rows.len().to_string())
            .or_default() += 1;
        for row in &record.speed_rows {
            *speed_values.entry(row.value_i32.to_string()).or_default() += 1;
        }
        for row in &record.pause_rows {
            *pause_values.entry(row.value_i32.to_string()).or_default() += 1;
        }
    }
    for hour in summary.frame_end_hour_counts.keys() {
        *records_per_closed_frame
            .entry(records_by_hour.get(hour).copied().unwrap_or(0).to_string())
            .or_default() += 1;
    }
    let record_count = summary.domain57_frames.len();
    let closed_frame_count = summary.frame_end_record_count;
    let exact_one_record_per_closed_frame = summary.frame_end_hour_counts.len()
        == closed_frame_count
        && summary
            .frame_end_hour_counts
            .values()
            .all(|count| *count == 1)
        && records_by_hour.len() == summary.frame_end_hour_counts.len()
        && summary
            .frame_end_hour_counts
            .keys()
            .all(|hour| records_by_hour.get(hour) == Some(&1));
    json!({
        "schema": "battle-plan.domain57_frame_evidence.v1",
        "required_root_mask": REQUIRED_ROOT_MASK,
        "record_count": record_count,
        "closed_frame_count": closed_frame_count,
        "records_per_closed_frame_histogram": records_per_closed_frame,
        "root_presence_counts": {
            "player_country": summary.domain57_frames.iter().filter(|record| record.root_evidence_mask & 0x1 != 0).count(),
            "pause_clock": summary.domain57_frames.iter().filter(|record| record.root_evidence_mask & 0x2 != 0).count(),
            "game_speed": summary.domain57_frames.iter().filter(|record| record.root_evidence_mask & 0x4 != 0).count(),
        },
        "root_mask_histogram": root_masks,
        "speed": {
            "row_count": summary.domain57_frames.iter().map(|record| record.speed_rows.len()).sum::<usize>(),
            "rows_per_record_histogram": speed_rows_per_record,
            "value_histogram": speed_values,
        },
        "pause": {
            "row_count": summary.domain57_frames.iter().map(|record| record.pause_rows.len()).sum::<usize>(),
            "rows_per_record_histogram": pause_rows_per_record,
            "value_histogram": pause_values,
        },
        "payload_header_hour_mismatch_count": summary.domain57_frames.iter().filter(|record| record.payload_hour_raw != record.header_hour_raw).count(),
        "event_header_hour_mismatch_count": summary.domain57_frames.iter().map(|record| record.speed_rows.iter().chain(record.pause_rows.iter()).filter(|row| row.event_hour_raw != record.header_hour_raw).count()).sum::<usize>(),
        "exact_one_record_per_closed_frame": exact_one_record_per_closed_frame,
        "all_required_roots_per_record": summary.domain57_frames.iter().all(|record| {
            has_all_required_root_evidence(record.root_evidence_mask, REQUIRED_ROOT_MASK)
        }),
        "exact_one_speed_row_per_record": summary.domain57_frames.iter().all(|record| record.speed_rows.len() == 1),
        "exact_one_pause_row_per_record": summary.domain57_frames.iter().all(|record| record.pause_rows.len() == 1),
        "records": summary.domain57_frames.iter().map(|record| json!({
            "sequence": record.sequence,
            "header_hour_raw": record.header_hour_raw,
            "payload_hour_raw": record.payload_hour_raw,
            "root_evidence_mask": record.root_evidence_mask,
            "speed": record.speed_rows.iter().map(|row| json!({"event_hour_raw": row.event_hour_raw, "value_i32": row.value_i32})).collect::<Vec<_>>(),
            "pause": record.pause_rows.iter().map(|row| json!({"event_hour_raw": row.event_hour_raw, "value_i32": row.value_i32})).collect::<Vec<_>>(),
        })).collect::<Vec<_>>(),
    })
}

fn compact_stream_manifest_json(
    summary: &CompactSummary,
    expected_domain_ids: &[u16],
    coverage_errors: &[String],
    scheduled_domains: &[String],
    capture: Option<&PipeCapture>,
) -> Value {
    let gate_status = compact_gate_status(summary);
    let failure_status_flags_or = gate_status.failure_status_flags_or;
    let failure_status_seen = failure_status_flags_or != 0;
    let worker_panic_seen = (failure_status_flags_or & COMPACT_STATUS_WORKER_PANIC) != 0;
    let bridge_unavailable_seen =
        (failure_status_flags_or & COMPACT_STATUS_BRIDGE_UNAVAILABLE) != 0;
    let source_unavailable_seen =
        (failure_status_flags_or & COMPACT_STATUS_SOURCE_UNAVAILABLE) != 0;
    let partial_data_seen = (failure_status_flags_or & COMPACT_STATUS_PARTIAL_DATA) != 0;
    let transition_baseline_reset_seen =
        (summary.status_flags_or & COMPACT_STATUS_TRANSITION_BASELINE_RESET) != 0;
    let control_invalid_seen = (failure_status_flags_or & COMPACT_STATUS_CONTROL_INVALID) != 0;
    let profile_unfolded = compact_profile_unfolded_domains(summary);
    json!({
        "record_magic": "H4CR",
        "record_header_len": COMPACT_RECORD_HEADER_LEN,
        "record_version": COMPACT_RECORD_VERSION,
        "record_count": summary.record_count,
        "domain_perf_record_count": summary.domain_perf_record_count,
        "domain_data_record_count": summary.domain_data_record_count,
        "frame_end_record_count": summary.frame_end_record_count,
        "total_bytes": summary.total_bytes,
        "total_payload_bytes": summary.total_payload_bytes,
        "max_payload_len": summary.max_payload_len,
        "max_record_len": summary.max_record_len,
        "decodable": summary.parse_errors.is_empty(),
        "ordered": summary.ordering_errors.is_empty(),
        "status_flags_or": summary.status_flags_or,
        "failure_status_flags_or": failure_status_flags_or,
        "failure_status_seen": failure_status_seen,
        "worker_panic_seen": worker_panic_seen,
        "bridge_unavailable_seen": bridge_unavailable_seen,
        "source_unavailable_seen": source_unavailable_seen,
        "partial_data_seen": partial_data_seen,
        "transition_baseline_reset_seen": transition_baseline_reset_seen,
        "control_invalid_seen": control_invalid_seen,
        "domains_seen": compact_domain_names(&summary.domains_seen),
        "expected_domains": compact_domain_names_from_ids(expected_domain_ids),
        "forced_domain_dependencies": compact_forced_domain_dependencies_json(scheduled_domains),
        "domain_coverage": {
            "ok": coverage_errors.is_empty(),
            "expected_domain_count": expected_domain_ids.len(),
            "errors": coverage_errors,
        },
        "world_fold": {
            "folded_domains": compact_domain_names_from_ids(FOLDED_DOMAIN_IDS),
            "unfolded_domains": compact_domain_descriptor_list_json(&summary.unfolded_domain_data),
            "production_profile_unfolded_domains": compact_domain_descriptor_list_json(&profile_unfolded),
            "delta_before_baseline": compact_domain_problem_domains_json(summary, "delta_before_baseline"),
            "late_records_after_frame_end": summary.late_records_after_frame_end,
            "late_record_domains": compact_domain_problem_domains_json(summary, "late_record_after_frame_end"),
        },
        "per_domain": compact_domain_summaries_json(summary),
        "frame_time_us": timing_summary_json(&summary.frame_times_us),
        "read_ab_probe": serde_json::to_value(&summary.read_ab_probe).unwrap_or(Value::Null),
        // R2 bound-trip attribution: nonzero = a vanilla-tuned plausibility
        // bound dropped real content this session (bound named by the unit,
        // last raw value in the paired `_raw_sample`). Empty on vanilla.
        "bound_trips": serde_json::to_value(&summary.bound_trips).unwrap_or(Value::Null),
        // C1 stage A status-origin incidence ledger: which site/cause first
        // introduced each status bit, how often, over which hour span.
        "status_origins": Value::Object(
            summary
                .status_origins
                .iter()
                .map(|(name, agg)| {
                    (
                        name.clone(),
                        json!({
                            "value": agg.value,
                            "first_hour": agg.first_hour,
                            "last_hour": agg.last_hour,
                            "no_clock_observations": agg.no_clock_observations,
                        }),
                    )
                })
                .collect(),
        ),
        "control_invalid_reasons": Value::Object(
            summary
                .control_invalid_reasons
                .iter()
                .map(|(name, agg)| {
                    (
                        name.clone(),
                        json!({
                            "value": agg.value,
                            "first_hour": agg.first_hour,
                            "last_hour": agg.last_hour,
                            "no_clock_observations": agg.no_clock_observations,
                        }),
                    )
                })
                .collect(),
        ),
        "domain57_frame_evidence": domain57_frame_evidence_json(summary),
        "lane_wall": lane_wall_summary_json(summary),
        "hour_latch": hour_latch_summary_json(summary),
        "acceptance_telemetry": acceptance_telemetry_json(summary, expected_domain_ids, capture),
    })
}

fn acceptance_test_observation_json(cfg: &Config, summary: &CompactSummary) -> Value {
    let Some(test) = cfg.acceptance_test.as_ref() else {
        return Value::Null;
    };
    let framing_intact = summary.frame_end_record_count > 0
        && summary.parse_errors.is_empty()
        && summary.ordering_errors.is_empty()
        && summary.late_records_after_frame_end == 0;
    let weather = summary.per_domain.get(&24);
    let weather_flags = weather
        .map(|domain| domain.effective_failure_status_flags_or)
        .unwrap_or(0);
    let non_d57_failure_domains = summary
        .per_domain
        .iter()
        .filter_map(|(domain_id, domain)| {
            (*domain_id != COMPACT_DOMAIN_SESSION_MULTIPLAYER_METADATA_LIVE
                && domain.effective_failure_status_flags_or != 0)
                .then_some(*domain_id)
        })
        .collect::<Vec<_>>();
    let non_d57_source_unavailable_domains = summary
        .per_domain
        .iter()
        .filter_map(|(domain_id, domain)| {
            (*domain_id != COMPACT_DOMAIN_SESSION_MULTIPLAYER_METADATA_LIVE
                && domain.effective_failure_status_flags_or & COMPACT_STATUS_SOURCE_UNAVAILABLE
                    != 0)
                .then_some(*domain_id)
        })
        .collect::<Vec<_>>();
    let paused_observed = summary.domain57_frames.iter().any(|frame| {
        frame
            .pause_rows
            .iter()
            .any(|row| row.value_i32 == 1 && row.event_hour_raw == frame.header_hour_raw)
    });
    let mode_observed = match test.mode {
        AcceptanceTestMode::SyntheticFault => {
            weather_flags & COMPACT_STATUS_WORKER_PANIC != 0
                && weather_flags & COMPACT_STATUS_SOURCE_UNAVAILABLE != 0
        }
        AcceptanceTestMode::Paused => {
            paused_observed && !non_d57_source_unavailable_domains.is_empty()
        }
        AcceptanceTestMode::SinkOpenFault | AcceptanceTestMode::SinkWriteFault => false,
    };
    json!({
        "schema": "battle-plan.acceptance_test_observation.v1",
        "admissible_for_production": false,
        "mode": test.mode.as_str(),
        "acceptance_test_nonce": test.nonce,
        "framing_intact": framing_intact,
        "mode_observed": mode_observed,
        "ok": framing_intact && mode_observed,
        "weather_effective_failure_status_flags_or": weather_flags,
        "paused_observed": paused_observed,
        "non_d57_failure_domains": non_d57_failure_domains,
        "non_d57_source_unavailable_domains": non_d57_source_unavailable_domains,
    })
}

/// lane/hour-latch: surface the zero-SILENT-GAP latch accounting (NOT a
/// zero-data-loss claim — a coalesced hour is explicit, reason-tagged loss of
/// that hour's per-hour world state). Returns Null when the latch was disabled
/// (no `hl_*` units in the stream). The coverage invariant
/// `observed == attempts + coalesced` (after the final flush) is reconciled and
/// reported so a violation is loud, never silent. New `emitted_to_sink` probes
/// mean a status-complete frame was completely written to every configured sink;
/// pre-fix `confirmed` probes are surfaced separately as `legacy_semantics`
/// because they also counted non-tolerated PARTIAL frames. The stricter proof
/// below additionally requires sticky transport health and a terminal sole-pipe
/// marker before the recorder claims successful delivery.
/// `capture_failed = attempts - emitted_to_sink` is a distinct, explicitly-counted
/// loss class only when the status-complete counter exists. Per-hour DATA
/// completeness is enforced SEPARATELY by the per-domain coverage gate, which
/// this lane does not touch.
/// Return every reason the terminal latch/transport evidence cannot prove that
/// one complete status-clean H4CR frame reached the recorder pipe for every
/// observed game hour.
///
/// An in-band terminal record can prove its own delivery only when the recorder
/// pipe is the sole configured sink: receipt of the complete framed record is
/// the acknowledgement. With a file/mirror sink, the pipe may receive the
/// record while the other sink fails on that same write, so mixed-sink captures
/// remain unverified until duplex/out-of-band acknowledgement exists.
fn hour_latch_delivery_problems(summary: &CompactSummary) -> Vec<String> {
    if summary.hour_latch.is_empty() {
        return vec!["hour_latch_proof_missing".to_string()];
    }

    let get = |name: &str| summary.hour_latch.get(name).copied();
    let required = [
        "observed",
        "attempts",
        "emitted_to_sink",
        "coalesced",
        "coalesced_superseded",
        "coalesced_overflow",
        "coalesced_flush",
        "coalesced_backward",
        "coalesced_anomalous",
        "in_flight",
        "last_observe_failed",
        "latch_requested_but_inactive",
        "capture_barrier_acquisitions",
        "capture_barrier_failures",
        "capture_barrier_releases",
        "capture_barrier_restore_failures",
        "capture_barrier_supported",
        "capture_barrier_active",
        "sink_write_failures",
        "sink_open_attempts",
        "sink_open_finishes",
        "sink_requested_count",
        "sink_opened_count",
        "sink_open_failures",
        "sink_write_attempts",
        "sink_write_finishes",
        "sink_write_commits",
        "sink_write_in_flight",
        "sink_time_sample_count",
        "sink_time_total_us",
        "sink_time_p50_us",
        "sink_time_p99_us",
        "sink_time_max_us",
        "transport_failed",
        "configured_sink_count",
        "pipe_sink_enabled",
        "file_sink_enabled",
        "pipe_sink_requested",
        "pipe_sink_opened",
        "file_sink_requested",
        "file_sink_opened",
        "finalized",
    ];
    let missing = required
        .iter()
        .copied()
        .filter(|name| get(name).is_none())
        .collect::<Vec<_>>();
    let mut problems = Vec::new();
    if !missing.is_empty() {
        problems.push(format!(
            "hour_latch_required_counters_missing:{}",
            missing.join(",")
        ));
    }

    let observed = get("observed").unwrap_or(0);
    let attempts = get("attempts").unwrap_or(0);
    let coalesced = get("coalesced").unwrap_or(0);
    let reason_sum = get("coalesced_superseded")
        .unwrap_or(0)
        .saturating_add(get("coalesced_overflow").unwrap_or(0))
        .saturating_add(get("coalesced_flush").unwrap_or(0))
        .saturating_add(get("coalesced_backward").unwrap_or(0))
        .saturating_add(get("coalesced_anomalous").unwrap_or(0));

    if get("finalized") != Some(1) {
        problems.push("hour_latch_terminal_proof_missing".to_string());
    }
    if get("latch_requested_but_inactive").unwrap_or(1) != 0 {
        problems.push("hour_latch_inactive".to_string());
    }
    if get("capture_barrier_supported") != Some(1) {
        problems.push("hour_latch_capture_barrier_unavailable".to_string());
    }
    if get("capture_barrier_failures").unwrap_or(1) != 0
        || get("capture_barrier_restore_failures").unwrap_or(1) != 0
    {
        problems.push("hour_latch_capture_barrier_failed".to_string());
    }
    if get("capture_barrier_active").unwrap_or(1) != 0 {
        problems.push("hour_latch_capture_barrier_not_released".to_string());
    }
    if get("capture_barrier_acquisitions") != Some(attempts)
        || get("capture_barrier_releases") != Some(attempts)
    {
        problems.push("hour_latch_capture_barrier_accounting_invalid".to_string());
    }
    if get("last_observe_failed").unwrap_or(1) != 0 {
        problems.push("hour_latch_terminal_observe_failed".to_string());
    }
    if observed != attempts.saturating_add(coalesced) || reason_sum != coalesced {
        problems.push("hour_latch_accounting_invalid".to_string());
    }
    if get("in_flight").unwrap_or(1) != 0 {
        problems.push("hour_latch_in_flight_not_flushed".to_string());
    }
    if coalesced != 0 || observed != attempts {
        problems.push("hour_latch_coalesced_hours".to_string());
    }
    if get("sink_write_failures").unwrap_or(1) != 0 || get("transport_failed").unwrap_or(1) != 0 {
        problems.push("hour_latch_transport_failure".to_string());
    }
    let sink_requested = get("sink_requested_count").unwrap_or(0);
    let sink_opened = get("sink_opened_count").unwrap_or(0);
    let sink_open_failures = get("sink_open_failures").unwrap_or(u64::MAX);
    let sink_open_attempts = get("sink_open_attempts").unwrap_or(0);
    let sink_open_finishes = get("sink_open_finishes").unwrap_or(0);
    if sink_open_attempts != sink_requested
        || sink_open_finishes != sink_open_attempts
        || sink_opened.saturating_add(sink_open_failures) != sink_requested
        || sink_open_failures != 0
        || sink_opened != sink_requested
    {
        problems.push("hour_latch_sink_open_accounting_invalid".to_string());
    }
    let sink_write_attempts = get("sink_write_attempts").unwrap_or(0);
    let sink_write_finishes = get("sink_write_finishes").unwrap_or(0);
    let sink_write_commits = get("sink_write_commits").unwrap_or(0);
    let sink_write_failures = get("sink_write_failures").unwrap_or(u64::MAX);
    // `emitted_to_sink` is the semantic status-complete count, not the
    // transport commit count: failed/partial frames are still durably emitted
    // and must remain reconstructable evidence. Transport delivery is exact
    // when every attempted hourly frame has one committed sink write.
    if sink_write_commits != attempts {
        problems.push("hour_latch_sink_delivery_mismatch".to_string());
    }
    if sink_write_attempts != sink_write_finishes
        || sink_write_finishes != sink_write_commits.saturating_add(sink_write_failures)
        || get("sink_write_in_flight").unwrap_or(1) != 0
    {
        problems.push("hour_latch_sink_write_accounting_invalid".to_string());
    }
    if get("sink_time_sample_count") != Some(sink_write_finishes) {
        problems.push("hour_latch_sink_time_accounting_invalid".to_string());
    }
    if get("configured_sink_count") != Some(1)
        || get("pipe_sink_enabled") != Some(1)
        || get("file_sink_enabled") != Some(0)
        || get("pipe_sink_requested") != Some(1)
        || get("pipe_sink_opened") != Some(1)
        || get("file_sink_requested") != Some(0)
        || get("file_sink_opened") != Some(0)
    {
        problems.push("hour_latch_authoritative_pipe_not_sole_sink".to_string());
    }
    if u64::try_from(summary.frame_end_record_count).ok() != Some(attempts) {
        problems.push("hour_latch_frame_count_mismatch".to_string());
    }
    problems
}

/// True exactly when the recorder's resolved compact roster contains domain 57.
/// The empty legacy schedule resolves to domains 10..=17, so it does not borrow
/// the collector's profile-default expansion and does not require a speed gate.
fn scheduled_roster_includes_domain57(scheduled_domains: &[String]) -> bool {
    scheduled_domains.iter().any(|domain| {
        compact_domain_id(domain) == Some(COMPACT_DOMAIN_SESSION_MULTIPLAYER_METADATA_LIVE)
    })
}

/// X12's suspended early-launch proof must install its mutation hooks before
/// the first game-state initialization writes. A same-process A3 transcript
/// gate therefore cannot exist yet. Permit this one debug/evidence topology.
/// Non-production captures still require the transcript-bound v2 gate unless
/// they use this exact evidence topology. Production may instead use the
/// independently authorized passive X12 observer below.
fn allow_x12_debug_d57_without_speed_gate(
    production: bool,
    profile: Option<compact_contract::CaptureProfile>,
    early_launch: bool,
    activation: Option<&str>,
) -> bool {
    !production
        && profile == Some(compact_contract::CaptureProfile::Debug)
        && early_launch
        && activation == Some("1")
}

/// Native production admission is available only while the exact-build passive
/// X12 observer's lane-local activation latch remains enabled. Each capture
/// still fails closed on hook installation, identity, sequencing, or queue
/// integrity failure.
fn allow_native_production_d57_without_speed_gate(
    production: bool,
    profile: Option<compact_contract::CaptureProfile>,
) -> bool {
    production
        && profile == Some(compact_contract::CaptureProfile::Production)
        && session_multiplayer_metadata_live::x12_a729_hook::PRODUCTION_ACTIVATION
}

fn hour_latch_gate_problems(summary: &CompactSummary, required: bool) -> Vec<String> {
    if !required && summary.hour_latch.is_empty() {
        Vec::new()
    } else {
        hour_latch_delivery_problems(summary)
    }
}

fn hour_latch_summary_json(summary: &CompactSummary) -> Value {
    if summary.hour_latch.is_empty() {
        return Value::Null;
    }
    let get = |k: &str| summary.hour_latch.get(k).copied().unwrap_or(0);
    let observed = get("observed");
    let attempts = get("attempts");
    // Accept pre-fix probe streams for diagnostics, but never reinterpret their
    // `hl_confirmed` value as the post-fix status-complete emitted-to-sink claim:
    // the legacy counter also included non-tolerated PARTIAL frames.
    let emitted_to_sink = summary.hour_latch.get("emitted_to_sink").copied();
    let legacy_confirmed = summary.hour_latch.get("confirmed").copied();
    let legacy_semantics = emitted_to_sink.is_none() && legacy_confirmed.is_some();
    let emission_semantics = if emitted_to_sink.is_some() {
        "status_complete"
    } else if legacy_semantics {
        "legacy_semantics"
    } else {
        "unavailable"
    };
    let coalesced = get("coalesced");
    let in_flight = get("in_flight");
    // The live invariant includes queued work. A valid terminal marker has
    // in_flight==0 after flush; a last periodic marker retained after a hard
    // kill can still reconcile truthfully without relabeling queued hours as
    // captured or coalesced.
    let accounted = attempts.saturating_add(coalesced).saturating_add(in_flight);
    let reason_sum = get("coalesced_superseded")
        .saturating_add(get("coalesced_overflow"))
        .saturating_add(get("coalesced_flush"))
        .saturating_add(get("coalesced_backward"))
        .saturating_add(get("coalesced_anomalous"));
    let emitted_count_valid = emitted_to_sink
        .map(|emitted| emitted <= attempts)
        .unwrap_or(true);
    let legacy_count_valid = legacy_confirmed
        .map(|confirmed| confirmed <= attempts)
        .unwrap_or(true);
    let invariant_ok = observed == accounted
        && reason_sum == coalesced
        && emitted_count_valid
        && legacy_count_valid;
    let latch_requested_but_inactive = get("latch_requested_but_inactive") != 0;
    let last_observe_failed = get("last_observe_failed") != 0;
    let accounting_claim = if latch_requested_but_inactive {
        "INACTIVE"
    } else if !invariant_ok {
        "INVALID"
    } else if last_observe_failed {
        "TRUNCATED-AT-LAST-GOOD-OBSERVE"
    } else {
        "COMPLETE"
    };
    let capture_failed = emitted_to_sink.map(|emitted| attempts.saturating_sub(emitted));
    let delivery_problems = hour_latch_delivery_problems(summary);
    let sink_write_success_verified = delivery_problems.is_empty();
    let capture_barrier_supported = get("capture_barrier_supported") == 1;
    let sink_write_gap = if sink_write_success_verified {
        Value::Null
    } else {
        json!(delivery_problems)
    };
    serde_json::json!({
        "requested": true,
        "enabled": !latch_requested_but_inactive,
        "latch_requested_but_inactive": latch_requested_but_inactive,
        "accounting_claim": accounting_claim,
        "last_observe_failed": last_observe_failed,
        "note": if capture_barrier_supported {
            "exact-build capture barrier freezes each observed hour while its full world frame is assembled"
        } else {
            "legacy zero-silent-gap accounting only; coalesced hours are explicit reason-tagged loss"
        },
        "hours_observed": observed,
        "capture_attempts": attempts,
        "in_flight": summary.hour_latch.get("in_flight").copied(),
        "emission_semantics": emission_semantics,
        "legacy_semantics": legacy_semantics,
        "legacy_confirmed": if legacy_semantics { legacy_confirmed } else { None },
        "frames_emitted_to_sink": emitted_to_sink,
        "capture_failed": capture_failed,
        "recorded_failed": capture_failed,
        "terminal_proof_seen": summary.hour_latch.get("finalized").copied() == Some(1),
        "configured_sink_count": summary.hour_latch.get("configured_sink_count").copied(),
        "pipe_sink_enabled": summary.hour_latch.get("pipe_sink_enabled").copied(),
        "file_sink_enabled": summary.hour_latch.get("file_sink_enabled").copied(),
        "sink_write_failure_count": summary.hour_latch.get("sink_write_failures").copied(),
        "sink_lifecycle": {
            "open_attempts": summary.hour_latch.get("sink_open_attempts").copied(),
            "open_finishes": summary.hour_latch.get("sink_open_finishes").copied(),
            "requested": summary.hour_latch.get("sink_requested_count").copied(),
            "opened": summary.hour_latch.get("sink_opened_count").copied(),
            "open_failures": summary.hour_latch.get("sink_open_failures").copied(),
            "write_attempts": summary.hour_latch.get("sink_write_attempts").copied(),
            "write_finishes": summary.hour_latch.get("sink_write_finishes").copied(),
            "write_commits": summary.hour_latch.get("sink_write_commits").copied(),
            "write_failures": summary.hour_latch.get("sink_write_failures").copied(),
            "write_in_flight": summary.hour_latch.get("sink_write_in_flight").copied(),
            "file_bytes_committed": summary.hour_latch.get("sink_file_bytes_committed").copied(),
            "pipe_bytes_committed": summary.hour_latch.get("sink_pipe_bytes_committed").copied(),
        },
        "sink_write_us": {
            "scope": "finished synchronous sink writes preceding the in-band terminal marker",
            "count": summary.hour_latch.get("sink_time_sample_count").copied(),
            "total": summary.hour_latch.get("sink_time_total_us").copied(),
            "p50": summary.hour_latch.get("sink_time_p50_us").copied(),
            "p99": summary.hour_latch.get("sink_time_p99_us").copied(),
            "max": summary.hour_latch.get("sink_time_max_us").copied(),
        },
        "transport_failed": summary.hour_latch.get("transport_failed").copied().map(|value| value != 0),
        "per_hour_delivery_proof_complete": sink_write_success_verified,
        "sink_write_success_verified": sink_write_success_verified,
        "sink_write_gap": sink_write_gap,
        "hours_coalesced": coalesced,
        "coalesced_superseded": get("coalesced_superseded"),
        "coalesced_overflow": get("coalesced_overflow"),
        "coalesced_flush": get("coalesced_flush"),
        "coalesced_backward": get("coalesced_backward"),
        "coalesced_anomalous": get("coalesced_anomalous"),
        "max_queue_depth": get("max_queue_depth"),
        "queue_cap": get("queue_cap"),
        "backward_jumps": get("backward_jumps"),
        "anomalous_jumps": get("anomalous_jumps"),
        "latch_polls": get("polls"),
        "latch_read_failures": get("read_failures"),
        "capture_barrier": {
            "supported": capture_barrier_supported,
            "acquisitions": summary.hour_latch.get("capture_barrier_acquisitions").copied(),
            "failures": summary.hour_latch.get("capture_barrier_failures").copied(),
            "releases": summary.hour_latch.get("capture_barrier_releases").copied(),
            "restore_failures": summary.hour_latch.get("capture_barrier_restore_failures").copied(),
            "active_at_terminal": summary.hour_latch.get("capture_barrier_active").copied().map(|value| value != 0),
            "player_pause_sample_preserved": capture_barrier_supported,
        },
        // Coverage reconciliation — the load-bearing zero-silent-gap invariant.
        "hours_accounted": accounted,
        "coverage_invariant_ok": invariant_ok && !latch_requested_but_inactive,
        "hours_unaccounted": observed.saturating_sub(accounted),
    })
}

/// F5 production-facing acceptance telemetry. This object combines facts
/// decoded from the collector stream with measurements taken at the recorder's
/// real pipe-to-storage boundary; neither side is a host configuration echo.
/// Its `complete` bit is false whenever any required sample/counter is absent or
/// internally inconsistent, so old streams remain readable but can never gain
/// a false production green.
fn acceptance_telemetry_json(
    summary: &CompactSummary,
    expected_domain_ids: &[u16],
    capture: Option<&PipeCapture>,
) -> Value {
    let problems = acceptance_telemetry_problems(summary, expected_domain_ids, capture);
    let expected: BTreeSet<u16> = expected_domain_ids.iter().copied().collect();
    let actual: BTreeSet<u16> = summary.per_domain.keys().copied().collect();
    let speed_required = expected.contains(&COMPACT_DOMAIN_SESSION_MULTIPLAYER_METADATA_LIVE);
    let speed_problems = domain57_gate_problems(summary, speed_required);
    let mut per_domain_bytes = serde_json::Map::new();
    for domain_id in expected_domain_ids {
        let domain = summary.per_domain.get(domain_id);
        per_domain_bytes.insert(
            compact_domain_name(*domain_id).to_string(),
            json!({
                "domain_id": domain_id,
                "record_bytes": domain.map(|row| row.record_bytes_total),
                "payload_bytes": domain.map(|row| row.payload_bytes_total),
                "max_record_bytes": domain.map(|row| row.max_record_bytes),
            }),
        );
    }
    json!({
        "schema": "battle-plan.acceptance_telemetry.v1",
        "complete": problems.is_empty(),
        "problems": problems,
        "verified_game_speed": {
            "required": speed_required,
            "verified": speed_required && speed_problems.is_empty(),
            "problems": speed_problems,
            "frame_evidence": domain57_frame_evidence_json(summary),
        },
        "frame_time_us": timing_summary_json(&summary.frame_times_us),
        "collector_sink_write_us": collector_sink_write_summary_json(summary),
        "sink_write_us": capture
            .map(|capture| write_latency_summary_json(&capture.write_latency))
            .unwrap_or_else(|| write_latency_summary_json(&WriteLatencyHistogram::default())),
        "sink_write_scope": "recorder StreamWriter::write_all calls over the complete physical H4CR capture; capture-set scoped during rollover; buffered/compressed host-path diagnostic, not logical-stream collector sink latency",
        "clock_skew": capture
            .map(|capture| capture.clock_skew.as_json())
            .unwrap_or(Value::Null),
        "clock_skew_scope": "complete physical H4CR capture; capture-set scoped during rollover",
        "hour_label_skew": {
            "definition": "absolute game-hour distance between the latch-owned frame label and an independent stable hour read at heavy-sweep start",
            "unit": "game_hours",
            "absolute": timing_summary_json(&summary.acceptance_hour_label_skew_abs),
            "missing": summary.acceptance_hour_label_skew_missing,
        },
        "prewarm_time_us": timing_summary_json(&summary.acceptance_prewarm_times_us),
        "capture_accounting": {
            "observed": summary.hour_latch.get("observed").copied(),
            "attempts": summary.hour_latch.get("attempts").copied(),
            "coalesced": summary.hour_latch.get("coalesced").copied(),
            "in_flight": summary.hour_latch.get("in_flight").copied(),
            "emitted_to_sink": summary.hour_latch.get("emitted_to_sink").copied(),
        },
        "sink_lifecycle": {
            "open_attempts": summary.hour_latch.get("sink_open_attempts").copied(),
            "open_finishes": summary.hour_latch.get("sink_open_finishes").copied(),
            "requested": summary.hour_latch.get("sink_requested_count").copied(),
            "opened": summary.hour_latch.get("sink_opened_count").copied(),
            "open_failures": summary.hour_latch.get("sink_open_failures").copied(),
            "write_attempts": summary.hour_latch.get("sink_write_attempts").copied(),
            "write_finishes": summary.hour_latch.get("sink_write_finishes").copied(),
            "write_commits": summary.hour_latch.get("sink_write_commits").copied(),
            "write_failures": summary.hour_latch.get("sink_write_failures").copied(),
            "write_in_flight": summary.hour_latch.get("sink_write_in_flight").copied(),
            "file_bytes_committed": summary.hour_latch.get("sink_file_bytes_committed").copied(),
            "pipe_bytes_committed": summary.hour_latch.get("sink_pipe_bytes_committed").copied(),
        },
        "per_domain_bytes": Value::Object(per_domain_bytes),
        "exact_roster": {
            "expected": compact_domain_names_from_ids(expected_domain_ids),
            "observed": compact_domain_names(&actual),
            "exact": actual == expected,
        },
    })
}

fn acceptance_telemetry_problems(
    summary: &CompactSummary,
    expected_domain_ids: &[u16],
    capture: Option<&PipeCapture>,
) -> Vec<String> {
    let mut problems = Vec::new();
    let expected: BTreeSet<u16> = expected_domain_ids.iter().copied().collect();
    let actual: BTreeSet<u16> = summary.per_domain.keys().copied().collect();
    if actual != expected {
        problems.push("acceptance_exact_roster_mismatch".to_string());
    }
    if summary.frame_end_record_count == 0
        || summary.frame_times_us.len() != summary.frame_end_record_count
    {
        problems.push("acceptance_frame_time_samples_incomplete".to_string());
    }
    if summary.acceptance_prewarm_times_us.len() != summary.frame_end_record_count {
        problems.push("acceptance_prewarm_samples_incomplete".to_string());
    }
    if summary.acceptance_hour_label_skew_missing != 0
        || summary.acceptance_hour_label_skew_abs.len() != summary.frame_end_record_count
    {
        problems.push("acceptance_hour_label_skew_samples_incomplete".to_string());
    }
    if !expected.contains(&COMPACT_DOMAIN_SESSION_MULTIPLAYER_METADATA_LIVE) {
        problems.push("acceptance_verified_game_speed_not_scheduled".to_string());
    } else {
        problems.extend(
            domain57_gate_problems(summary, true)
                .into_iter()
                .map(|problem| format!("acceptance_{problem}")),
        );
    }
    for domain_id in expected_domain_ids {
        let complete = summary
            .per_domain
            .get(domain_id)
            .map(|domain| domain.record_bytes_total != 0 && domain.payload_bytes_total != 0)
            .unwrap_or(false);
        if !complete {
            problems.push(format!(
                "acceptance_domain_bytes_missing:{}",
                compact_domain_name(*domain_id)
            ));
        }
    }
    problems.extend(
        hour_latch_delivery_problems(summary)
            .into_iter()
            .map(|problem| format!("acceptance_{problem}")),
    );
    let sink_count = summary.hour_latch.get("sink_time_sample_count").copied();
    let sink_total = summary.hour_latch.get("sink_time_total_us").copied();
    let sink_p50 = summary.hour_latch.get("sink_time_p50_us").copied();
    let sink_p99 = summary.hour_latch.get("sink_time_p99_us").copied();
    let sink_max = summary.hour_latch.get("sink_time_max_us").copied();
    if sink_count == Some(0) {
        problems.push("acceptance_collector_sink_time_samples_empty".to_string());
    }
    if matches!(
        (sink_total, sink_p50, sink_p99, sink_max),
        (Some(total), Some(p50), Some(p99), Some(max))
            if p50 > p99 || p99 > max || max > total
    ) {
        problems.push("acceptance_collector_sink_time_distribution_invalid".to_string());
    }
    match capture {
        Some(capture) => {
            if capture.write_latency.count == 0 {
                problems.push("acceptance_host_sink_write_samples_empty".to_string());
            }
            if !capture.clock_skew.measured {
                problems.push("acceptance_clock_skew_unmeasured".to_string());
            } else if !capture.clock_skew.wall_monotonic_ok {
                problems.push("acceptance_wall_clock_non_monotonic".to_string());
            }
        }
        None => {
            problems.push("acceptance_host_sink_write_unmeasured".to_string());
            problems.push("acceptance_clock_skew_unmeasured".to_string());
        }
    }
    problems
}

fn decode_compact_domain_perf_diagnostic_units(
    offset: usize,
    domain_id: u16,
    game_hour_raw: i32,
    record_flags: u32,
    payload: &[u8],
    summary: &mut CompactSummary,
) {
    if record_flags & COMPACT_RECORD_FLAG_PERF_DIAGNOSTIC_TRAILER == 0 {
        return;
    }
    let mut cursor = 40usize;
    if payload.len().saturating_sub(cursor) < 8 {
        summary.parse_errors.push(format!(
            "offset {offset}: domain perf diagnostic trailer is {} byte(s), expected at least 8",
            payload.len().saturating_sub(cursor)
        ));
        return;
    }
    if &payload[cursor..cursor + 4] != COMPACT_DOMAIN_PERF_DIAGNOSTIC_UNITS_MAGIC {
        summary.parse_errors.push(format!(
            "offset {offset}: domain perf diagnostic trailer has unknown magic"
        ));
        return;
    }
    cursor += 4;
    let version = read_u16_le(payload, cursor);
    cursor += 2;
    let unit_count = read_u16_le(payload, cursor) as usize;
    cursor += 2;
    if version != COMPACT_DOMAIN_PERF_DIAGNOSTIC_UNITS_VERSION {
        summary.parse_errors.push(format!(
            "offset {offset}: domain perf diagnostic trailer version {version} != {COMPACT_DOMAIN_PERF_DIAGNOSTIC_UNITS_VERSION}"
        ));
        return;
    }

    for unit_index in 0..unit_count {
        if payload.len().saturating_sub(cursor) < 12 {
            summary.parse_errors.push(format!(
                "offset {offset}: domain perf diagnostic unit {unit_index} truncated"
            ));
            return;
        }
        let name_len = read_u16_le(payload, cursor) as usize;
        let reserved = read_u16_le(payload, cursor + 2);
        let value = read_u64_le(payload, cursor + 4);
        cursor += 12;
        if reserved != 0 {
            summary.parse_errors.push(format!(
                "offset {offset}: domain perf diagnostic unit {unit_index} reserved field is nonzero"
            ));
        }
        if payload.len().saturating_sub(cursor) < name_len {
            summary.parse_errors.push(format!(
                "offset {offset}: domain perf diagnostic unit {unit_index} name truncated"
            ));
            return;
        }
        let name_bytes = &payload[cursor..cursor + name_len];
        cursor += name_len;
        let Ok(name) = std::str::from_utf8(name_bytes) else {
            summary.parse_errors.push(format!(
                "offset {offset}: domain perf diagnostic unit {unit_index} name is not utf-8"
            ));
            continue;
        };
        if !is_valid_compact_perf_diagnostic_name(name) {
            summary.parse_errors.push(format!(
                "offset {offset}: domain perf diagnostic unit {unit_index} has invalid name {name:?}"
            ));
            continue;
        }
        add_compact_domain_perf_diagnostic_unit(summary, domain_id, game_hour_raw, name, value);
    }
    if cursor != payload.len() {
        summary.parse_errors.push(format!(
            "offset {offset}: domain perf diagnostic trailer has {} trailing byte(s)",
            payload.len().saturating_sub(cursor)
        ));
    }
}

fn is_valid_compact_perf_diagnostic_name(name: &str) -> bool {
    !name.is_empty()
        && name
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
}

fn add_compact_domain_perf_diagnostic_unit(
    summary: &mut CompactSummary,
    domain_id: u16,
    game_hour_raw: i32,
    name: &str,
    value: u64,
) {
    if domain_id == RC_PROBE_DOMAIN_ID {
        // Lane-wall counter (lever #5): lw_* units get a dedicated aggregate
        // with per-frame value vectors (avg/p95/max in the manifest).
        if add_compact_lane_wall_unit(summary, name, value) {
            return;
        }
        // lane/hour-latch: cumulative counters aggregate by MAX (not sum).
        // Terminal/transient state markers are deliberately last-value: a later
        // successful observe clears an earlier failure, and a later barrier
        // release clears the active flag. A failing final poll or active final
        // barrier must still survive as the terminal truncation marker.
        if let Some(rest) = name.strip_prefix("hl_") {
            if matches!(
                rest,
                "last_observe_failed"
                    | "capture_barrier_active"
                    | "sink_time_p50_us"
                    | "sink_time_p99_us"
            ) {
                summary.hour_latch.insert(rest.to_string(), value);
            } else {
                let entry = summary.hour_latch.entry(rest.to_string()).or_default();
                *entry = (*entry).max(value);
            }
            return;
        }
        if name.starts_with("ci_") {
            let entry = summary
                .control_invalid_reasons
                .entry(name.to_string())
                .or_default();
            entry.value = entry.value.saturating_add(value);
            if game_hour_raw == compact_contract::status_origins::ATTRIBUTION_NO_CLOCK_HOUR {
                entry.no_clock_observations = entry.no_clock_observations.saturating_add(1);
            } else {
                entry.first_hour = Some(
                    entry
                        .first_hour
                        .map_or(game_hour_raw, |hour| hour.min(game_hour_raw)),
                );
                entry.last_hour = Some(
                    entry
                        .last_hour
                        .map_or(game_hour_raw, |hour| hour.max(game_hour_raw)),
                );
            }
            return;
        }
        // R2 bound-trip attribution units: `*_trips` counters sum; `*_raw_sample`
        // keeps the last observed value (the `_sample` unit class — summing
        // destroys raw words).
        if name.starts_with("bt_") {
            let entry = summary.bound_trips.entry(name.to_string()).or_default();
            if name.ends_with("_sample") {
                *entry = value;
            } else {
                *entry = entry.saturating_add(value);
            }
            return;
        }
        // C1 stage A status-origin ledger: counters sum, `_sample` units keep
        // the last value; both track {first_hour, last_hour} of incidence —
        // exactly the C0 cross-domain incidence ledger shape.
        if name.starts_with("so_") {
            let entry = summary.status_origins.entry(name.to_string()).or_default();
            if name.ends_with("_sample") {
                entry.value = value;
            } else {
                entry.value = entry.value.saturating_add(value);
            }
            if game_hour_raw == compact_contract::status_origins::ATTRIBUTION_NO_CLOCK_HOUR {
                entry.no_clock_observations = entry.no_clock_observations.saturating_add(1);
            } else {
                entry.first_hour = Some(
                    entry
                        .first_hour
                        .map_or(game_hour_raw, |h| h.min(game_hour_raw)),
                );
                entry.last_hour = Some(
                    entry
                        .last_hour
                        .map_or(game_hour_raw, |h| h.max(game_hour_raw)),
                );
            }
            return;
        }
        // Plan-v2 read A/B probe units go to a dedicated aggregate, never
        // per_domain (which the coverage/perf-count gates read).
        let entry = summary.read_ab_probe.entry(name.to_string()).or_default();
        *entry = entry.saturating_add(value);
        return;
    }
    if let Some(domain) = summary.per_domain.get_mut(&domain_id) {
        let entry = domain.data_units_total.entry(name.to_string()).or_default();
        // Bitmask units aggregate by OR, never sum: two frames failing slot 0
        // must read as mask 1, not "2" (which would falsely name slot 1).
        // d69's failed- and stale-slot masks; counters keep summing. Units
        // named `*_sample` are per-frame VALUE samples (hashes, raw words,
        // indices) — summing destroys them; keep the LAST observed value.
        if name == "d69_failed_slot_mask"
            || name.starts_with("d69_failed_slot_mask_")
            || name == "d69_stale_slot_mask"
        {
            *entry |= value;
        } else if name.ends_with("_sample") {
            *entry = value;
        } else {
            *entry = entry.saturating_add(value);
        }
    }
    if domain_id == COMPACT_DOMAIN_CONSTRUCTION_BUILDINGS_STATE_DAMAGE_LIVE {
        if name.starts_with("domain48_gate_") {
            add_compact_domain_problem(summary, domain_id, name, value.max(1));
        } else if value != 0
            && (name.starts_with("domain48_failed_") || name.starts_with("domain48_skipped_"))
        {
            add_compact_domain_problem(summary, domain_id, name, value);
        }
    }
}

/// Lane-wall counter (deep-war lever #5): route one `lw_*` diagnostic unit
/// from the reserved probe domain into the dedicated aggregates. Returns
/// false for non-`lw_` (and unrecognized `lw_`) names so they keep flowing to
/// `read_ab_probe` (forward compatibility).
fn add_compact_lane_wall_unit(summary: &mut CompactSummary, name: &str, value: u64) -> bool {
    let Some(rest) = name.strip_prefix("lw_") else {
        return false;
    };
    match rest {
        "frames" => {
            summary.lane_wall_frames = summary.lane_wall_frames.saturating_add(value);
        }
        "worker_span_us" => {
            summary.lane_wall_worker_span_us_total =
                summary.lane_wall_worker_span_us_total.saturating_add(value);
        }
        "prewarm_us" => summary.acceptance_prewarm_times_us.push(value),
        "hour_label_skew_abs" => summary.acceptance_hour_label_skew_abs.push(value),
        "hour_label_skew_missing" => {
            summary.acceptance_hour_label_skew_missing = summary
                .acceptance_hour_label_skew_missing
                .saturating_add(value);
        }
        "crit_wall_us" => summary.lane_wall_crit_walls_us.push(value),
        "crit_busy_us" => {
            summary.lane_wall_crit_busy_us_total =
                summary.lane_wall_crit_busy_us_total.saturating_add(value);
        }
        "lmain_wall_us" => {
            summary.lane_wall_main_wall_us_total =
                summary.lane_wall_main_wall_us_total.saturating_add(value);
        }
        "lother_wall_us" => {
            summary.lane_wall_other_wall_us_total =
                summary.lane_wall_other_wall_us_total.saturating_add(value);
        }
        "prefetch_dist_relation" => match summary.lane_wall_prefetch_dist_relation_applied {
            None => summary.lane_wall_prefetch_dist_relation_applied = Some(value),
            Some(prev) if prev != value => {
                summary.lane_wall_prefetch_dist_relation_mixed = true;
            }
            Some(_) => {}
        },
        "prefetch_dist_candidates" => match summary.lane_wall_prefetch_dist_candidates_applied {
            None => summary.lane_wall_prefetch_dist_candidates_applied = Some(value),
            Some(prev) if prev != value => {
                summary.lane_wall_prefetch_dist_candidates_mixed = true;
            }
            Some(_) => {}
        },
        _ => {
            if let Some(id) = rest
                .strip_prefix('d')
                .and_then(|s| s.strip_suffix("_crit_us"))
                .and_then(|s| s.parse::<u16>().ok())
            {
                let entry = summary
                    .lane_wall_domain_crit_us_total
                    .entry(id)
                    .or_default();
                *entry = entry.saturating_add(value);
                return true;
            }
            if let Some(lane) = rest
                .strip_prefix('l')
                .and_then(|s| s.strip_suffix("_wall_us"))
                .and_then(|s| s.parse::<u16>().ok())
            {
                summary
                    .lane_wall_per_lane_walls_us
                    .entry(lane)
                    .or_default()
                    .push(value);
                return true;
            }
            if let Some(lane) = rest
                .strip_prefix('l')
                .and_then(|s| s.strip_suffix("_busy_us"))
                .and_then(|s| s.parse::<u16>().ok())
            {
                let entry = summary
                    .lane_wall_per_lane_busy_us_total
                    .entry(lane)
                    .or_default();
                *entry = entry.saturating_add(value);
                return true;
            }
            return false;
        }
    }
    true
}

/// Lane-wall manifest aggregate (compact_stream.lane_wall). Everything needed
/// to attribute critical-path milliseconds per domain is derivable from this
/// object alone:
///   avg crit wall/frame        = crit_wall_us_total / frames
///   crit-path share of domain  = per_domain_critical_path_us_total[d] / crit_wall_us_total
///   crit-path ms/frame of dom. = per_domain_critical_path_us_total[d] / frames / 1000
/// Domain key "200" is the country-bundle worker (compact domains 10..=17).
fn lane_wall_summary_json(summary: &CompactSummary) -> Value {
    let crit_wall_us_total: u64 = summary
        .lane_wall_crit_walls_us
        .iter()
        .fold(0u64, |acc, &v| acc.saturating_add(v));
    let mut per_lane = serde_json::Map::new();
    for (&lane, walls) in &summary.lane_wall_per_lane_walls_us {
        let busy = summary
            .lane_wall_per_lane_busy_us_total
            .get(&lane)
            .copied()
            .unwrap_or(0);
        per_lane.insert(
            format!("l{lane}"),
            json!({
                "wall_us": timing_summary_json(walls),
                "busy_us_total": busy,
            }),
        );
    }
    let mut per_domain_crit = serde_json::Map::new();
    let mut per_domain_share = serde_json::Map::new();
    for (&domain, &crit_us) in &summary.lane_wall_domain_crit_us_total {
        per_domain_crit.insert(domain.to_string(), json!(crit_us));
        if crit_wall_us_total != 0 {
            per_domain_share.insert(
                domain.to_string(),
                json!(crit_us as f64 / crit_wall_us_total as f64),
            );
        }
    }
    json!({
        "frames": summary.lane_wall_frames,
        "worker_span_us_total": summary.lane_wall_worker_span_us_total,
        "crit_wall_us": timing_summary_json(&summary.lane_wall_crit_walls_us),
        "crit_wall_us_total": crit_wall_us_total,
        "crit_busy_us_total": summary.lane_wall_crit_busy_us_total,
        "main_wall_us_total": summary.lane_wall_main_wall_us_total,
        "other_wall_us_total": summary.lane_wall_other_wall_us_total,
        "per_lane": Value::Object(per_lane),
        "per_domain_critical_path_us_total": Value::Object(per_domain_crit),
        "per_domain_critical_path_share": Value::Object(per_domain_share),
        "country_bundle_tag": 200,
        // APPLIED d53 prefetch distances mined from the stream's lw units.
        // `null` applied + `mixed:false` = stream predates the units; `null` +
        // `mixed:true` = the session carried MORE THAN ONE distance and has no
        // single arm label (never fabricated via max/min). Unlike the top-level
        // prefetch_dist_* echo (host-requested), a non-null value here proves
        // which distance the DLL actually used — the live-A/B arm label of
        // record.
        "prefetch_dist_relation_applied": (!summary.lane_wall_prefetch_dist_relation_mixed)
            .then_some(summary.lane_wall_prefetch_dist_relation_applied)
            .flatten(),
        "prefetch_dist_relation_mixed": summary.lane_wall_prefetch_dist_relation_mixed,
        "prefetch_dist_candidates_applied": (!summary.lane_wall_prefetch_dist_candidates_mixed)
            .then_some(summary.lane_wall_prefetch_dist_candidates_applied)
            .flatten(),
        "prefetch_dist_candidates_mixed": summary.lane_wall_prefetch_dist_candidates_mixed,
    })
}

fn timing_summary_json(values: &[u64]) -> Value {
    if values.is_empty() {
        return json!({
            "count": 0,
            "avg": null,
            "p50": null,
            "p95": null,
            "p99": null,
            "max": null,
        });
    }
    let mut sorted = values.to_vec();
    sorted.sort_unstable();
    let sum = sorted.iter().copied().fold(0u64, u64::saturating_add);
    let p95_index = ((sorted.len() * 95).saturating_add(99) / 100)
        .saturating_sub(1)
        .min(sorted.len().saturating_sub(1));
    let p50_index = ((sorted.len() * 50).saturating_add(99) / 100)
        .saturating_sub(1)
        .min(sorted.len().saturating_sub(1));
    let p99_index = ((sorted.len() * 99).saturating_add(99) / 100)
        .saturating_sub(1)
        .min(sorted.len().saturating_sub(1));
    json!({
        "count": sorted.len(),
        "avg": (sum as f64) / (sorted.len() as f64),
        "p50": sorted[p50_index],
        "p95": sorted[p95_index],
        "p99": sorted[p99_index],
        "max": sorted[sorted.len() - 1],
    })
}

fn json_hourly_problems(summary: &Summary, min_game_hours: i32) -> Vec<String> {
    let mut problems = Vec::new();
    if !summary.parse_errors.is_empty() {
        problems.push("json_stream_not_decodable".to_string());
    }
    if !summary.control_errors.is_empty() {
        problems.push("collector_control_invalid".to_string());
    }
    if summary.skipped_hours != 0 {
        problems.push("skipped_game_hours_detected".to_string());
    }
    let Some((first, last)) = summary.first_hour.zip(summary.last_hour) else {
        problems.push("no_game_hours_observed".to_string());
        return problems;
    };
    let advanced = last.saturating_sub(first);
    if advanced < min_game_hours {
        problems.push("minimum_game_hours_not_reached".to_string());
    }
    problems
}

fn compact_hourly_problems(
    summary: &CompactSummary,
    min_game_hours: i32,
    coverage_errors: &[String],
) -> Vec<String> {
    let mut problems = Vec::new();
    let gate_status = compact_gate_status(summary);
    let failure_status_flags_or = gate_status.failure_status_flags_or;
    if !summary.parse_errors.is_empty() {
        problems.push("compact_stream_not_decodable".to_string());
    }
    if !summary.ordering_errors.is_empty() {
        problems.push("compact_stream_sequence_order_failed".to_string());
    }
    if summary.skipped_hours != 0 {
        problems.push("skipped_game_hours_detected".to_string());
    }
    if (failure_status_flags_or & COMPACT_STATUS_CONTROL_INVALID) != 0 {
        problems.push("collector_control_invalid".to_string());
    }
    if failure_status_flags_or != 0 {
        problems.push("compact_failure_status_seen".to_string());
    }
    if (failure_status_flags_or & COMPACT_STATUS_WORKER_PANIC) != 0 {
        problems.push("compact_worker_panic_seen".to_string());
    }
    if (failure_status_flags_or & COMPACT_STATUS_BRIDGE_UNAVAILABLE) != 0 {
        problems.push("compact_bridge_unavailable".to_string());
    }
    if (failure_status_flags_or & COMPACT_STATUS_SOURCE_UNAVAILABLE) != 0 {
        problems.push("compact_source_unavailable".to_string());
    }
    if (failure_status_flags_or & COMPACT_STATUS_PARTIAL_DATA) != 0 {
        problems.push("compact_partial_data".to_string());
    }
    if (summary.status_flags_or & COMPACT_STATUS_TRANSITION_BASELINE_RESET) != 0 {
        problems.push("compact_transition_baseline_reset".to_string());
    }
    if compact_domain_problem_count(summary, "delta_before_baseline") != 0 {
        problems.push("compact_delta_before_baseline".to_string());
    }
    if summary.late_records_after_frame_end != 0 {
        problems.push("compact_late_records_after_frame_end".to_string());
    }
    if !compact_profile_unfolded_domains(summary).is_empty() {
        problems.push("production_profile_unfolded_domain_data".to_string());
    }
    if !coverage_errors.is_empty() {
        problems.push("scheduled_domain_coverage_failed".to_string());
    }
    let Some((first, last)) = summary.first_hour.zip(summary.last_hour) else {
        problems.push("no_game_hours_observed".to_string());
        return problems;
    };
    let advanced = last.saturating_sub(first);
    if advanced < min_game_hours {
        problems.push("minimum_game_hours_not_reached".to_string());
    }
    problems
}

fn has_all_required_root_evidence(observed_mask: u32, required_mask: u32) -> bool {
    observed_mask & required_mask == required_mask
}

fn domain57_gate_problems(summary: &CompactSummary, required: bool) -> Vec<String> {
    if !required {
        return Vec::new();
    }
    const REQUIRED_ROOT_MASK: u32 = 0x7;
    let mut problems = Vec::new();
    let mut records_by_hour = BTreeMap::<i32, usize>::new();
    for record in &summary.domain57_frames {
        *records_by_hour.entry(record.header_hour_raw).or_default() += 1;
    }
    let exact_one_record_per_closed_frame = summary.frame_end_hour_counts.len()
        == summary.frame_end_record_count
        && summary
            .frame_end_hour_counts
            .values()
            .all(|count| *count == 1)
        && records_by_hour.len() == summary.frame_end_hour_counts.len()
        && summary
            .frame_end_hour_counts
            .keys()
            .all(|hour| records_by_hour.get(hour) == Some(&1));
    if !exact_one_record_per_closed_frame {
        problems.push("d57_record_count_per_closed_frame_invalid".to_string());
    }
    if summary
        .domain57_frames
        .iter()
        .any(|record| {
            !has_all_required_root_evidence(record.root_evidence_mask, REQUIRED_ROOT_MASK)
        })
    {
        problems.push("d57_required_root_evidence_missing".to_string());
    }
    if summary
        .domain57_frames
        .iter()
        .any(|record| record.speed_rows.len() != 1)
    {
        problems.push("d57_game_speed_row_count_invalid".to_string());
    }
    if summary
        .domain57_frames
        .iter()
        .any(|record| record.pause_rows.len() != 1)
    {
        problems.push("d57_pause_row_count_invalid".to_string());
    }
    if summary
        .domain57_frames
        .iter()
        .any(|record| record.payload_hour_raw != record.header_hour_raw)
    {
        problems.push("d57_payload_header_hour_mismatch".to_string());
    }
    if summary.domain57_frames.iter().any(|record| {
        record
            .speed_rows
            .iter()
            .chain(record.pause_rows.iter())
            .any(|row| row.event_hour_raw != record.header_hour_raw)
    }) {
        problems.push("d57_event_header_hour_mismatch".to_string());
    }
    problems
}

fn trim_ascii(bytes: &[u8]) -> &[u8] {
    let mut start = 0usize;
    let mut end = bytes.len();
    while start < end && bytes[start].is_ascii_whitespace() {
        start += 1;
    }
    while end > start && bytes[end - 1].is_ascii_whitespace() {
        end -= 1;
    }
    &bytes[start..end]
}

fn add_domains(value: Option<&Value>, out: &mut BTreeSet<String>) {
    if let Some(items) = value.and_then(Value::as_array) {
        for item in items {
            if let Some(domain) = item.as_str() {
                out.insert(domain.to_string());
            }
        }
    }
}

fn frame_domains(value: &Value) -> Vec<String> {
    let mut domains = BTreeSet::new();
    add_domains(value.get("domains"), &mut domains);
    if let Some(root) = value.get("root_probe") {
        add_domains(root.get("domains"), &mut domains);
    }
    domains.into_iter().collect()
}

fn skipped_hours(hours: &[i32]) -> i32 {
    hours
        .windows(2)
        .map(|pair| pair[1].saturating_sub(pair[0]).saturating_sub(1).max(0))
        .sum()
}

struct WindowSearch {
    pid: Dword,
    hwnd: Hwnd,
}

fn find_main_window(pid: Dword) -> Option<Hwnd> {
    let mut search = WindowSearch {
        pid,
        hwnd: ptr::null_mut(),
    };
    unsafe {
        EnumWindows(enum_window_proc, &mut search as *mut WindowSearch as Lparam);
    }
    if search.hwnd.is_null() {
        None
    } else {
        Some(search.hwnd)
    }
}

extern "system" fn enum_window_proc(hwnd: Hwnd, lparam: Lparam) -> Bool {
    let search = unsafe { &mut *(lparam as *mut WindowSearch) };
    if unsafe { IsWindowVisible(hwnd) } == 0 {
        return 1;
    }
    let mut owner = 0u32;
    unsafe {
        GetWindowThreadProcessId(hwnd, &mut owner);
    }
    if owner == search.pid {
        search.hwnd = hwnd;
        0
    } else {
        1
    }
}

fn wide(value: &OsStr) -> Vec<u16> {
    value.encode_wide().chain(std::iter::once(0)).collect()
}

fn last_error() -> Dword {
    unsafe { GetLastError() }
}

