    fn complete_hour_latch_summary(attempts: u64) -> CompactSummary {
        let mut summary = CompactSummary {
            frame_end_record_count: usize::try_from(attempts).unwrap(),
            ..CompactSummary::default()
        };
        for (name, value) in [
            ("observed", attempts),
            ("attempts", attempts),
            ("emitted_to_sink", attempts),
            ("coalesced", 0),
            ("coalesced_superseded", 0),
            ("coalesced_overflow", 0),
            ("coalesced_flush", 0),
            ("coalesced_backward", 0),
            ("coalesced_anomalous", 0),
            ("in_flight", 0),
            ("last_observe_failed", 0),
            ("latch_requested_but_inactive", 0),
            ("capture_barrier_acquisitions", attempts),
            ("capture_barrier_failures", 0),
            ("capture_barrier_releases", attempts),
            ("capture_barrier_restore_failures", 0),
            ("capture_barrier_supported", 1),
            ("capture_barrier_active", 0),
            ("sink_write_failures", 0),
            ("sink_open_attempts", 1),
            ("sink_open_finishes", 1),
            ("sink_requested_count", 1),
            ("sink_opened_count", 1),
            ("sink_open_failures", 0),
            ("sink_write_attempts", attempts),
            ("sink_write_finishes", attempts),
            ("sink_write_commits", attempts),
            ("sink_write_in_flight", 0),
            ("sink_file_bytes_committed", 0),
            ("sink_pipe_bytes_committed", 4096),
            ("sink_time_sample_count", attempts),
            ("sink_time_total_us", 300),
            ("sink_time_p50_us", 100),
            ("sink_time_p99_us", 200),
            ("sink_time_max_us", 200),
            ("transport_failed", 0),
            ("configured_sink_count", 1),
            ("pipe_sink_enabled", 1),
            ("file_sink_enabled", 0),
            ("pipe_sink_requested", 1),
            ("pipe_sink_opened", 1),
            ("file_sink_requested", 0),
            ("file_sink_opened", 0),
            ("finalized", 1),
        ] {
            summary.hour_latch.insert(name.to_string(), value);
        }
        summary
    }

