    #[test]
    fn compact_payload_status_flags_reads_construction_lane_status_at_offset_12() {
        // Regression: the CBSD lane header places the global compact status word
        // at byte 12; offset 16 is game_hour_raw. Reading offset 16 fabricated
        // phantom failure flags (CONTROL_INVALID/WORKER_PANIC/etc.) from the game
        // hour, poisoning the tolerance gate. Craft a frame whose game_hour_raw
        // has failure-looking bits and whose real status is clean.
        let frame = domain48::LaneFrame {
            game_hour_raw: 0x03A0_32E9, // failure-mask bits {0,3,6,7,12} once masked
            status_flags: compact_contract::COMPACT_STATUS_EXTRACTION_PERF_GATE
                | COMPACT_STATUS_PARTIAL_DATA,
            source_flags: domain48::SOURCE_FLAG_DLL_NATIVE,
            observed_country_roots: 1,
            observed_state_roots: 1,
            observed_province_roots: 1,
            construction_rows: Vec::new(),
            railway_construction_rows: None,
            building_rows: Vec::new(),
            resource_rows: Vec::new(),
        };
        let payload = domain48::encode_lane_frame(&frame);
        let status = compact_payload_status_flags(
            COMPACT_DOMAIN_CONSTRUCTION_BUILDINGS_STATE_DAMAGE_LIVE,
            &payload,
        )
        .expect("d48 payload has a status word");
        assert_eq!(
            status,
            compact_contract::COMPACT_STATUS_EXTRACTION_PERF_GATE | COMPACT_STATUS_PARTIAL_DATA,
            "must read the real status at offset 12, not game_hour_raw at offset 16"
        );
        // D48 is production-complete, so its real PARTIAL_DATA bit is now a
        // failure. The result must contain exactly that bit, never phantom bits
        // decoded from the game hour.
        assert_eq!(
            compact_domain_effective_failure_flags(
                COMPACT_DOMAIN_CONSTRUCTION_BUILDINGS_STATE_DAMAGE_LIVE,
                status,
            ),
            COMPACT_STATUS_PARTIAL_DATA,
            "CBSD failure contribution must come from its real status word only"
        );
    }

    #[test]
    fn compact_payload_status_flags_reads_only_frd_depth_global_status_word() {
        // FRD2 v2 has no global DATA status. Its lane-local byte-8 flags must
        // remain None, while v3 status zero is authoritative Some(0), not
        // indistinguishable from a missing field.
        let mut v2 = Vec::new();
        v2.extend_from_slice(COMPACT_FRD_DEPTH_SCHEMA_MAGIC);
        v2.extend_from_slice(&COMPACT_FRD_DEPTH_SCHEMA_VERSION_V2.to_le_bytes());
        v2.extend_from_slice(&(COMPACT_FRD_DEPTH_HEADER_LEN_V2 as u16).to_le_bytes());
        // depth_status_flags with bits that would look like failures if misread.
        v2.extend_from_slice(&0x0000_0007u32.to_le_bytes());
        v2.resize(COMPACT_FRD_DEPTH_HEADER_LEN_V2, 0);
        assert_eq!(
            compact_payload_status_flags(COMPACT_DOMAIN_FOCUS_RESEARCH_DECISIONS_DEPTH_LIVE, &v2,),
            None,
            "d45 v2 carries no global DATA status"
        );

        let mut v3 = v2;
        v3[4..6].copy_from_slice(&COMPACT_FRD_DEPTH_SCHEMA_VERSION.to_le_bytes());
        v3[6..8].copy_from_slice(&(COMPACT_FRD_DEPTH_HEADER_LEN as u16).to_le_bytes());
        v3.resize(COMPACT_FRD_DEPTH_HEADER_LEN, 0);
        assert_eq!(
            compact_payload_status_flags(COMPACT_DOMAIN_FOCUS_RESEARCH_DECISIONS_DEPTH_LIVE, &v3,),
            Some(0),
            "d45 v3 status zero is authoritative, not missing"
        );

        let mut v5 = v3;
        v5[4..6].copy_from_slice(&COMPACT_FRD_DEPTH_SCHEMA_VERSION_V5.to_le_bytes());
        v5[6..8].copy_from_slice(&(COMPACT_FRD_DEPTH_HEADER_LEN_V5 as u16).to_le_bytes());
        v5.resize(COMPACT_FRD_DEPTH_HEADER_LEN_V5, 0);
        v5[56..60].copy_from_slice(&COMPACT_STATUS_DELTA_DATA.to_le_bytes());
        assert_eq!(
            compact_payload_status_flags(COMPACT_DOMAIN_FOCUS_RESEARCH_DECISIONS_DEPTH_LIVE, &v5,),
            Some(COMPACT_STATUS_DELTA_DATA),
            "d45 v5 retains the global DATA status at byte 56"
        );
    }

