    #[test]
    fn compact_air_combat_losses_live_row_len_is_76_not_64_or_68() {
        let payload = test_air_combat_losses_live_single_loss_payload(COMPACT_STATUS_DELTA_DATA);
        assert_eq!(
            payload.len(),
            COMPACT_AIR_STRENGTH_DELTA_HEADER_LEN + COMPACT_AIR_STRENGTH_DELTA_ROW_LEN
        );
        assert_eq!(COMPACT_AIR_STRENGTH_DELTA_ROW_LEN, 76);
        assert_ne!(COMPACT_AIR_STRENGTH_DELTA_ROW_LEN, 64);
        assert_ne!(COMPACT_AIR_STRENGTH_DELTA_ROW_LEN, 68);
    }

    #[test]
    fn compact_summary_rejects_stale_air_combat_losses_live_68_byte_row_shape() {
        let payload = test_air_combat_losses_live_single_loss_payload(COMPACT_STATUS_DELTA_DATA);
        let stale_len = COMPACT_AIR_STRENGTH_DELTA_HEADER_LEN + 68;
        let summary = summarize_compact_stream(&{
            let mut raw = Vec::new();
            append_test_compact_record(
                &mut raw,
                1,
                100,
                42,
                COMPACT_RECORD_TYPE_DOMAIN_DATA,
                &payload[..stale_len],
            );
            raw
        });
        assert!(summary.parse_errors.iter().any(|error| {
            error
                == "offset 0: air combat losses live data payload is 116 byte(s), expected at least 124"
        }));
    }

    #[test]
    fn compact_summary_rejects_air_combat_losses_live_bad_scale_and_delta() {
        let mut payload =
            test_air_combat_losses_live_single_loss_payload(COMPACT_STATUS_DELTA_DATA);
        payload[40..44].copy_from_slice(&1u32.to_le_bytes());
        payload[84..88].copy_from_slice(&(-2i32).to_le_bytes());

        let summary = summarize_compact_stream(&{
            let mut raw = Vec::new();
            append_test_compact_record(
                &mut raw,
                1,
                100,
                42,
                COMPACT_RECORD_TYPE_DOMAIN_DATA,
                &payload,
            );
            raw
        });
        assert!(summary
            .parse_errors
            .iter()
            .any(|error| error.contains("scale_raw 1")));
        assert!(summary
            .parse_errors
            .iter()
            .any(|error| error.contains("count_delta -2")));
    }

