    // Regression for the d48 tolerated-partial delta-baseline leak (adversarial
    // review Finding 1). A tolerated-PARTIAL frame sparse-merges into the hour's
    // PROJECTED state (correct — its snapshot shows those rows) but must NOT enter
    // the DELTA BASELINE the next delta is diffed against, because the collector's
    // `tracker.last_*` is likewise never advanced on a partial frame. Two failure
    // sequences the old single-accumulator design got wrong:
    //   (a) phantom row  — a row present only in the partial hour, absent in-game
    //       by the next delta hour, was kept forever in delta mode.
    //   (b) reverted value — a value that changed in the partial hour then reverted
    //       by the next delta hour retained the transient value in delta mode.
    // Both are exercised together below; the fold must be byte-identical to the
    // full-emission stream at every hour.
    #[test]
    fn compact_construction_buildings_state_damage_partial_does_not_leak_into_delta_baseline() {
        fn source_flags() -> u32 {
            domain48::SOURCE_FLAG_DLL_NATIVE
                | domain48::SOURCE_FLAG_SHARED_COUNTRY_ROOTS
                | domain48::SOURCE_FLAG_SHARED_MAP_TOPOLOGY
                | domain48::SOURCE_FLAG_HEALTHY_LEVEL_CANDIDATE
        }

        fn construction_row(line_id: u32, produced_raw: i32) -> domain48::ConstructionQueueRow {
            domain48::ConstructionQueueRow {
                tag_db_id: 1,
                line_id,
                template_id: Some(20_013),
                active_factories: 5,
                cost_raw: 10_000_000,
                produced_raw,
                priority: 0,
                target_state_id: Some(42),
                target_location_id: Some(42),
                target_scope: Some(domain48::SCOPE_STATE),
                repair_levels_remaining: Some(0),
                created_date_raw: Some(60_827_043 + line_id),
            }
        }

        fn state_building(type_id: u32, level: u32) -> domain48::BuildingRow {
            domain48::BuildingRow {
                scope: domain48::SCOPE_STATE,
                location_id: 42,
                state_id: 42,
                type_id,
                level,
                healthy_level: Some(level),
                partial_health_raw: Some(0),
            }
        }

        fn resource_row(resource_id: u32, amount_raw: i32) -> domain48::StateResourceRow {
            domain48::StateResourceRow {
                state_id: 42,
                resource_id,
                amount_raw,
            }
        }

        fn frame(
            status_flags: u32,
            construction_rows: Vec<domain48::ConstructionQueueRow>,
            building_rows: Vec<domain48::BuildingRow>,
            resource_rows: Vec<domain48::StateResourceRow>,
        ) -> domain48::LaneFrame {
            domain48::LaneFrame {
                game_hour_raw: 0,
                status_flags,
                source_flags: source_flags(),
                observed_country_roots: 1,
                observed_state_roots: 1,
                observed_province_roots: 1,
                construction_rows,
                railway_construction_rows: None,
                building_rows,
                resource_rows,
            }
        }

        fn append_domain48_frame(
            raw: &mut Vec<u8>,
            next_sequence: &mut u64,
            game_hour_raw: i32,
            frame: &domain48::LaneFrame,
        ) {
            let row_count = frame
                .construction_rows
                .len()
                .saturating_add(frame.building_rows.len())
                .saturating_add(frame.resource_rows.len())
                .min(u32::MAX as usize) as u32;
            append_test_compact_record(
                raw,
                *next_sequence,
                game_hour_raw,
                48,
                COMPACT_RECORD_TYPE_DOMAIN_PERF,
                &test_domain_payload_with_status(
                    500,
                    row_count,
                    row_count,
                    row_count,
                    row_count,
                    frame.status_flags,
                ),
            );
            *next_sequence += 1;
            append_test_compact_record(
                raw,
                *next_sequence,
                game_hour_raw,
                48,
                COMPACT_RECORD_TYPE_DOMAIN_DATA,
                &domain48::encode_lane_frame(frame),
            );
            *next_sequence += 1;
            append_test_compact_record(
                raw,
                *next_sequence,
                game_hour_raw,
                1000,
                COMPACT_RECORD_TYPE_FRAME_END,
                &test_frame_payload(1_200, 1),
            );
            *next_sequence += 1;
        }

        fn canonical_snapshots(raw: &[u8]) -> Vec<Vec<u8>> {
            fold_compact_snapshots(raw)
                .into_iter()
                .map(|snapshot| serde_json::to_vec(&snapshot).unwrap())
                .collect()
        }

        // Hour 0: clean baseline. Row 88 does NOT exist; row 77 == 5_000_000;
        // state building 0x2fab == level 5; resource 0x3e03 == 2_500_000.
        let full0 = frame(
            0,
            vec![construction_row(77, 5_000_000)],
            vec![state_building(0x2fab, 5)],
            vec![resource_row(0x3e03, 2_500_000)],
        );
        // Hour 1: tolerated PARTIAL. Introduces a PHANTOM construction row 88 and a
        // phantom state building 0x3000, and TRANSIENTLY changes row 77 -> 9_000_000,
        // building 0x2fab -> level 9, and resource 0x3e03 -> 9_999_999. This frame is
        // byte-identical between the full and delta streams (the collector emits a
        // partial the same way in both emit modes), so the hour-1 snapshot must fold
        // identically; the divergence risk is entirely in hour 2's baseline.
        let partial1 = frame(
            COMPACT_STATUS_PARTIAL_DATA,
            vec![
                construction_row(77, 9_000_000),
                construction_row(88, 4_000_000),
            ],
            vec![state_building(0x2fab, 9), state_building(0x3000, 3)],
            vec![resource_row(0x3e03, 9_999_999)],
        );
        // Hour 2 in-game truth == hour 0 EXCEPT state building 0x2fab advances to
        // level 6 (a genuine change). Row 88 is gone, 0x3000 is gone, row 77 has
        // reverted to 5_000_000, resource reverted to 2_500_000.
        let full2 = frame(
            0,
            vec![construction_row(77, 5_000_000)],
            vec![state_building(0x2fab, 6)],
            vec![resource_row(0x3e03, 2_500_000)],
        );
        // The collector diffs hour-2 truth against its tracker, which still holds the
        // hour-0 baseline (the partial never advanced it): the only change vs hour 0
        // is building 0x2fab 5 -> 6. No row 88 (never in the tracker -> no upsert, no
        // tombstone), no 0x3000, no row-77 change, no resource change.
        let delta2 = frame(
            COMPACT_STATUS_DELTA_DATA,
            Vec::new(),
            vec![state_building(0x2fab, 6)],
            Vec::new(),
        );

        let mut full_raw = Vec::new();
        let mut full_seq = 1u64;
        let mut delta_raw = Vec::new();
        let mut delta_seq = 1u64;
        let game_hour_raw = 60_759_360;
        for (index, full) in [&full0, &partial1, &full2].iter().enumerate() {
            append_domain48_frame(
                &mut full_raw,
                &mut full_seq,
                game_hour_raw + index as i32,
                full,
            );
        }
        for (index, delta) in [&full0, &partial1, &delta2].iter().enumerate() {
            append_domain48_frame(
                &mut delta_raw,
                &mut delta_seq,
                game_hour_raw + index as i32,
                delta,
            );
        }

        let full_summary = summarize_compact_stream(&full_raw);
        let delta_summary = summarize_compact_stream(&delta_raw);
        assert!(
            full_summary.parse_errors.is_empty(),
            "{:?}",
            full_summary.parse_errors
        );
        assert!(
            delta_summary.parse_errors.is_empty(),
            "{:?}",
            delta_summary.parse_errors
        );
        assert!(compact_domain_coverage_errors(&full_summary, &[48]).is_empty());
        assert!(compact_domain_coverage_errors(&delta_summary, &[48]).is_empty());

        let full_snapshots = canonical_snapshots(&full_raw);
        let delta_snapshots = canonical_snapshots(&delta_raw);
        assert_eq!(
            full_snapshots.len(),
            3,
            "expected one snapshot per captured hour"
        );
        // The whole point: a tolerated-partial frame's transient/phantom rows must
        // not survive into the next delta hour. Byte-identical to full emission.
        assert_eq!(delta_snapshots, full_snapshots);
    }

    // Gate (a) for the d48 churn fix (lane/d48-partial). The collector now emits a
    // tolerated-partial frame as the CHANGED SUBSET of its read rows (diffed against
    // the projected state) instead of the full read set, to stop a chronically-
    // partial d48 from re-emitting ~its whole row set every hour (the 79.2%-churn
    // pathology). This gate proves that reduction is LOSSLESS at the fold: folding
    // the reduced-partial delta stream is byte-identical to folding both the full-
    // emission stream AND the legacy full-read-partial delta stream, hour for hour.
    #[test]
    fn compact_d48_reduced_partial_folds_identically_to_full_emission() {
        fn source_flags() -> u32 {
            domain48::SOURCE_FLAG_DLL_NATIVE
                | domain48::SOURCE_FLAG_SHARED_COUNTRY_ROOTS
                | domain48::SOURCE_FLAG_SHARED_MAP_TOPOLOGY
                | domain48::SOURCE_FLAG_HEALTHY_LEVEL_CANDIDATE
        }
        fn construction_row(line_id: u32, produced_raw: i32) -> domain48::ConstructionQueueRow {
            domain48::ConstructionQueueRow {
                tag_db_id: 1,
                line_id,
                template_id: Some(20_013),
                active_factories: 5,
                cost_raw: 10_000_000,
                produced_raw,
                priority: 0,
                target_state_id: Some(42),
                target_location_id: Some(42),
                target_scope: Some(domain48::SCOPE_STATE),
                repair_levels_remaining: Some(0),
                created_date_raw: Some(60_827_043 + line_id),
            }
        }
        fn state_building(type_id: u32, level: u32) -> domain48::BuildingRow {
            domain48::BuildingRow {
                scope: domain48::SCOPE_STATE,
                location_id: 42,
                state_id: 42,
                type_id,
                level,
                healthy_level: Some(level),
                partial_health_raw: Some(0),
            }
        }
        fn resource_row(resource_id: u32, amount_raw: i32) -> domain48::StateResourceRow {
            domain48::StateResourceRow {
                state_id: 42,
                resource_id,
                amount_raw,
            }
        }
        fn frame(
            status_flags: u32,
            construction_rows: Vec<domain48::ConstructionQueueRow>,
            building_rows: Vec<domain48::BuildingRow>,
            resource_rows: Vec<domain48::StateResourceRow>,
        ) -> domain48::LaneFrame {
            domain48::LaneFrame {
                game_hour_raw: 0,
                status_flags,
                source_flags: source_flags(),
                observed_country_roots: 1,
                observed_state_roots: 1,
                observed_province_roots: 1,
                construction_rows,
                railway_construction_rows: None,
                building_rows,
                resource_rows,
            }
        }
        fn append_domain48_frame(
            raw: &mut Vec<u8>,
            next_sequence: &mut u64,
            game_hour_raw: i32,
            frame: &domain48::LaneFrame,
        ) {
            let row_count = frame
                .construction_rows
                .len()
                .saturating_add(frame.building_rows.len())
                .saturating_add(frame.resource_rows.len())
                .min(u32::MAX as usize) as u32;
            append_test_compact_record(
                raw,
                *next_sequence,
                game_hour_raw,
                48,
                COMPACT_RECORD_TYPE_DOMAIN_PERF,
                &test_domain_payload_with_status(
                    500,
                    row_count,
                    row_count,
                    row_count,
                    row_count,
                    frame.status_flags,
                ),
            );
            *next_sequence += 1;
            append_test_compact_record(
                raw,
                *next_sequence,
                game_hour_raw,
                48,
                COMPACT_RECORD_TYPE_DOMAIN_DATA,
                &domain48::encode_lane_frame(frame),
            );
            *next_sequence += 1;
            append_test_compact_record(
                raw,
                *next_sequence,
                game_hour_raw,
                1000,
                COMPACT_RECORD_TYPE_FRAME_END,
                &test_frame_payload(1_200, 1),
            );
            *next_sequence += 1;
        }
        fn canonical_snapshots(raw: &[u8]) -> Vec<Vec<u8>> {
            fold_compact_snapshots(raw)
                .into_iter()
                .map(|snapshot| serde_json::to_vec(&snapshot).unwrap())
                .collect()
        }

        // Hour 0: clean baseline (two construction lines, two buildings, one
        // resource).
        let base = frame(
            0,
            vec![
                construction_row(77, 5_000_000),
                construction_row(88, 2_000_000),
            ],
            vec![state_building(0x2fab, 5), state_building(0x3000, 7)],
            vec![resource_row(0x3e03, 2_500_000)],
        );
        // Hour 1 tolerated-PARTIAL. The read observed line 77 changed (6M), line 88
        // unchanged (2M) and building 0x2fab unchanged (5); it did NOT read building
        // 0x3000 or resource 0x3e03 (unread, must be retained).
        //   * full-emission / legacy delta: emit the FULL read set.
        let partial_full = frame(
            COMPACT_STATUS_PARTIAL_DATA,
            vec![
                construction_row(77, 6_000_000),
                construction_row(88, 2_000_000),
            ],
            vec![state_building(0x2fab, 5)],
            Vec::new(),
        );
        //   * new collector: emit ONLY the changed subset (line 77). Lines/buildings
        //     equal to the projection are dropped; the fold retains them unchanged.
        let partial_reduced = frame(
            COMPACT_STATUS_PARTIAL_DATA,
            vec![construction_row(77, 6_000_000)],
            Vec::new(),
            Vec::new(),
        );
        // Hour 2 in-game truth == hour 1 projection EXCEPT building 0x2fab -> level 6.
        let full2 = frame(
            0,
            vec![
                construction_row(77, 6_000_000),
                construction_row(88, 2_000_000),
            ],
            vec![state_building(0x2fab, 6), state_building(0x3000, 7)],
            vec![resource_row(0x3e03, 2_500_000)],
        );
        // Delta vs the PINNED hour-0 baseline (the partial never advanced it): line
        // 77 5M->6M and building 0x2fab 5->6. Identical for the legacy and reduced
        // streams because both leave the delta baseline pinned across the partial.
        let delta2 = frame(
            COMPACT_STATUS_DELTA_DATA,
            vec![construction_row(77, 6_000_000)],
            vec![state_building(0x2fab, 6)],
            Vec::new(),
        );

        let build = |frames: &[&domain48::LaneFrame]| -> Vec<u8> {
            let mut raw = Vec::new();
            let mut seq = 1u64;
            let game_hour_raw = 60_759_360;
            for (index, f) in frames.iter().enumerate() {
                append_domain48_frame(&mut raw, &mut seq, game_hour_raw + index as i32, f);
            }
            raw
        };

        let full_raw = build(&[&base, &partial_full, &full2]);
        let legacy_delta_raw = build(&[&base, &partial_full, &delta2]);
        let reduced_delta_raw = build(&[&base, &partial_reduced, &delta2]);

        for raw in [&full_raw, &legacy_delta_raw, &reduced_delta_raw] {
            let summary = summarize_compact_stream(raw);
            assert!(
                summary.parse_errors.is_empty(),
                "{:?}",
                summary.parse_errors
            );
            let coverage_errors = compact_domain_coverage_errors(&summary, &[48]);
            assert!(coverage_errors.is_empty(), "{coverage_errors:?}");
            let problems = compact_hourly_problems(&summary, 0, &coverage_errors);
            assert!(problems.contains(&"compact_failure_status_seen".to_string()));
            assert!(problems.contains(&"compact_partial_data".to_string()));
            assert!(!compact_expected_partial_tolerance_domain_names(&summary)
                .contains(&"construction_buildings_state_damage_live"));
        }

        let full_snapshots = canonical_snapshots(&full_raw);
        let legacy_snapshots = canonical_snapshots(&legacy_delta_raw);
        let reduced_snapshots = canonical_snapshots(&reduced_delta_raw);
        assert_eq!(full_snapshots.len(), 3);
        // Legacy full-read partial == full emission (the a1c787a4a guarantee).
        assert_eq!(legacy_snapshots, full_snapshots);
        // The fix's guarantee: the reduced-partial delta stream folds byte-identically
        // to full emission at every hour — the churn reduction is lossless.
        assert_eq!(reduced_snapshots, full_snapshots);
    }

    // lane/d53-partial-delta: the losslessness gate for enabling delta emission on
    // tolerated-PARTIAL d53 frames. In deep war 400/400 d53 frames are partial, so
    // the delta path never fired and d53 re-emitted its full ~245k-row read every
    // hour (92.3% of the whole stream). The new collector emits DELTA|PARTIAL on
    // partial frames (diffed against a pinned baseline, tombstone-all-absent) and
    // the fold seeds each hour from its mirror delta baseline. Because the collector
    // tombstones EVERY baseline row absent from the read (it cannot distinguish a
    // torn read from a genuine deletion), the reduced-partial fold reconstructs the
    // EXACT rows the frame carried — byte-identical to today's seed-from-empty
    // full-emit snapshot, on all cases: unchanged partials, genuine changes,
    // reverted values, deletions/tombstones, clean frames interleaved, and
    // multi-hour spans across the per-hour overlay clear.
    #[test]
    fn compact_d53_reduced_partial_folds_identically_to_full_emission() {
        use diplomacy53::compact as d53c;
        use std::collections::BTreeMap;

        // Recursively sort every JSON array by each element's canonical string so
        // two snapshots that carry the same rows in different array order compare
        // equal (decoded-row equality, plan G1).
        fn canonicalize_json(v: &Value) -> Value {
            match v {
                Value::Array(items) => {
                    let mut canon: Vec<Value> = items.iter().map(canonicalize_json).collect();
                    canon.sort_by_key(|e| e.to_string());
                    Value::Array(canon)
                }
                Value::Object(map) => Value::Object(
                    map.iter()
                        .map(|(k, val)| {
                            let value = if k == "snapshot_payload_sha256" {
                                Value::Null
                            } else {
                                canonicalize_json(val)
                            };
                            (k.clone(), value)
                        })
                        .collect(),
                ),
                other => other.clone(),
            }
        }

        fn canonicalize_projected_d53(mut value: Value) -> Value {
            if let Some(extra) = value
                .pointer_mut("/diplomacy_world/domain53_extra")
                .and_then(Value::as_object_mut)
            {
                // This receipt authenticates carrier bytes, so a FULL payload
                // and an equivalent DELTA payload correctly have different
                // hashes. It is not part of projected game-state equality.
                extra.remove("snapshot_payload_sha256");
            }
            canonicalize_json(&value)
        }

        #[derive(Clone, Default)]
        struct WorldState {
            countries: BTreeMap<u32, i64>,           // tag -> casualties
            opinions: BTreeMap<(u32, u32), i32>,     // (src,tgt) -> opinion
            state_events: BTreeMap<(u32, u32), i64>, // (owner,obj) -> value
            subjects: BTreeMap<(u32, u32), u32>,     // (overlord,subject) -> autonomy
        }

        fn country_row(tag: u32, casualties: i64) -> d53c::CountryDiplomacyRow {
            d53c::CountryDiplomacyRow {
                tag_db_id: tag,
                faction_group: 0,
                at_war_count: 0,
                casualties,
            }
        }
        fn opinion_row(src: u32, tgt: u32, value: i32) -> d53c::OpinionRow {
            d53c::OpinionRow {
                src_tag_db_id: src,
                target_tag_db_id: tgt,
                opinion: value,
            }
        }
        fn state_event_row(owner: u32, obj: u32, value: i64) -> d53c::StateEventRow {
            let deleted = owner & d53c::ROW_ID_DELETED != 0;
            d53c::StateEventRow {
                owner_tag_db_id: owner,
                target_tag_db_id: None,
                event_kind: d53c::STATE_EVENT_KIND_OBSERVED,
                source_kind: d53c::STATE_EVENT_SOURCE_RELATION_OPINION,
                object_hash: obj,
                value_hash: if deleted { 0 } else { 1 },
                value_raw: if deleted { 0 } else { value },
            }
        }
        fn subject_row(overlord: u32, subject: u32, autonomy: u32) -> d53c::SubjectRow {
            let deleted = overlord & d53c::ROW_ID_DELETED != 0;
            d53c::SubjectRow {
                overlord_tag_db_id: overlord,
                subject_tag_db_id: subject,
                // Live rows need a nonzero autonomy_state_hash and a positive
                // start_date; tombstones must zero every live field.
                autonomy_state_hash: if deleted { 0 } else { autonomy },
                autonomy_ratio_raw: 0,
                start_date_raw: if deleted { 0 } else { 60_795_475 },
            }
        }
        const DEL: u32 = d53c::ROW_ID_DELETED;
        // Country rows carry casualties -> the strict stream validator counts them
        // as "country war projection rows" and requires this badge on every frame
        // that emits them. Set on ALL frames (full and reduced) so the projected
        // diplomacy_world status_flags stay byte-identical between the two streams.
        const WAR_BADGE: u32 = d53c::STATUS_WAR_LIFECYCLE_DETAIL_UNVALIDATED;

        // FULL emission: encode every row of `state`, with the given status.
        fn encode_full(state: &WorldState, status: u32) -> Vec<u8> {
            let snap = d53c::DiplomacyIntelSnapshot {
                status_flags: status | WAR_BADGE,
                countries: state
                    .countries
                    .iter()
                    .map(|(&t, &c)| country_row(t, c))
                    .collect(),
                opinions: state
                    .opinions
                    .iter()
                    .map(|(&(s, t), &v)| opinion_row(s, t, v))
                    .collect(),
                state_events: state
                    .state_events
                    .iter()
                    .map(|(&(o, h), &v)| state_event_row(o, h, v))
                    .collect(),
                subjects: state
                    .subjects
                    .iter()
                    .map(|(&(o, s), &a)| subject_row(o, s, a))
                    .collect(),
                ..Default::default()
            };
            d53c::encode_payload(&snap)
        }

        // REDUCED delta emission: mirror the collector's tombstone-all diff of
        // `current` vs the pinned `baseline`, with the given status (DELTA or
        // DELTA|PARTIAL). Emits changed/new rows and a tombstone for every
        // baseline key absent from `current`.
        fn encode_delta(baseline: &WorldState, current: &WorldState, status: u32) -> Vec<u8> {
            let mut snap = d53c::DiplomacyIntelSnapshot {
                status_flags: status | WAR_BADGE,
                ..Default::default()
            };
            for (&t, &c) in &current.countries {
                if baseline.countries.get(&t) != Some(&c) {
                    snap.countries.push(country_row(t, c));
                }
            }
            for &t in baseline.countries.keys() {
                if !current.countries.contains_key(&t) {
                    snap.countries.push(country_row(t | DEL, 0));
                }
            }
            for (&(s, tg), &v) in &current.opinions {
                if baseline.opinions.get(&(s, tg)) != Some(&v) {
                    snap.opinions.push(opinion_row(s, tg, v));
                }
            }
            for &(s, tg) in baseline.opinions.keys() {
                if !current.opinions.contains_key(&(s, tg)) {
                    snap.opinions.push(opinion_row(s | DEL, tg, 0));
                }
            }
            for (&(o, h), &v) in &current.state_events {
                if baseline.state_events.get(&(o, h)) != Some(&v) {
                    snap.state_events.push(state_event_row(o, h, v));
                }
            }
            for &(o, h) in baseline.state_events.keys() {
                if !current.state_events.contains_key(&(o, h)) {
                    snap.state_events.push(state_event_row(o | DEL, h, 0));
                }
            }
            for (&(o, s), &a) in &current.subjects {
                if baseline.subjects.get(&(o, s)) != Some(&a) {
                    snap.subjects.push(subject_row(o, s, a));
                }
            }
            for &(o, s) in baseline.subjects.keys() {
                if !current.subjects.contains_key(&(o, s)) {
                    snap.subjects.push(subject_row(o | DEL, s, 0));
                }
            }
            d53c::encode_payload(&snap)
        }

        fn row_count(payload: &[u8]) -> u32 {
            d53c::decode_snapshot_payload(0, payload)
                .map(|s| s.row_count())
                .unwrap_or(0)
        }

        fn append_hour(raw: &mut Vec<u8>, seq: &mut u64, hour: i32, payload: &[u8]) {
            let rc = row_count(payload);
            append_test_compact_record(
                raw,
                *seq,
                hour,
                53,
                COMPACT_RECORD_TYPE_DOMAIN_PERF,
                &test_domain_payload_with_status(500, rc, rc, 0, 0, 0),
            );
            *seq += 1;
            append_test_compact_record(
                raw,
                *seq,
                hour,
                53,
                COMPACT_RECORD_TYPE_DOMAIN_DATA,
                payload,
            );
            *seq += 1;
            append_test_compact_record(
                raw,
                *seq,
                hour,
                1000,
                COMPACT_RECORD_TYPE_FRAME_END,
                &test_frame_payload(1_200, 1),
            );
            *seq += 1;
        }

        // ---- Hand-built scenario covering every required case ----
        // Hour 0: CLEAN baseline.
        let h0 = WorldState {
            countries: [(1, 100), (2, 200)].into_iter().collect(),
            opinions: [((1, 2), 5), ((1, 3), 7), ((2, 1), -3)]
                .into_iter()
                .collect(),
            state_events: [((1, 0xaa), 1000)].into_iter().collect(),
            subjects: [((1, 2), 50)].into_iter().collect(),
        };
        // Hour 1 PARTIAL: change op(1,2) & country 1 & subject(1,2); DELETE op(1,3);
        // leave op(2,1)/country 2/state_event unchanged.
        let h1 = WorldState {
            countries: [(1, 150), (2, 200)].into_iter().collect(),
            opinions: [((1, 2), 6), ((2, 1), -3)].into_iter().collect(),
            state_events: [((1, 0xaa), 1000)].into_iter().collect(),
            subjects: [((1, 2), 60)].into_iter().collect(),
        };
        // Hour 2 PARTIAL: REVERT op(1,2) & country 1 back to baseline; CHANGE
        // state_event; subject stays 60 (still != baseline).
        let h2 = WorldState {
            countries: [(1, 100), (2, 200)].into_iter().collect(),
            opinions: [((1, 2), 5), ((2, 1), -3)].into_iter().collect(),
            state_events: [((1, 0xaa), 2000)].into_iter().collect(),
            subjects: [((1, 2), 60)].into_iter().collect(),
        };
        // Hour 3 CLEAN: annex country 2, end the subject relation, keep the rest.
        let h3 = WorldState {
            countries: [(1, 100)].into_iter().collect(),
            opinions: [((1, 2), 5)].into_iter().collect(),
            state_events: [((1, 0xaa), 2000)].into_iter().collect(),
            subjects: BTreeMap::new(),
        };

        let mut full_raw = Vec::new();
        let mut reduced_raw = Vec::new();
        let mut fseq = 1u64;
        let mut rseq = 1u64;
        let base_hour = 60_759_360;

        // FULL stream: every hour is a full read (partial hours carry the full R).
        append_hour(&mut full_raw, &mut fseq, base_hour, &encode_full(&h0, 0));
        append_hour(
            &mut full_raw,
            &mut fseq,
            base_hour + 1,
            &encode_full(&h1, 0),
        );
        append_hour(
            &mut full_raw,
            &mut fseq,
            base_hour + 2,
            &encode_full(&h2, 0),
        );
        append_hour(
            &mut full_raw,
            &mut fseq,
            base_hour + 3,
            &encode_full(&h3, 0),
        );

        // REDUCED stream: hour 0 is the full clean baseline; hour 1/2 are
        // DELTA|PARTIAL vs the PINNED hour-0 baseline; hour 3 is a plain DELTA
        // (clean read) that also advances the baseline.
        append_hour(&mut reduced_raw, &mut rseq, base_hour, &encode_full(&h0, 0));
        append_hour(
            &mut reduced_raw,
            &mut rseq,
            base_hour + 1,
            &encode_delta(
                &h0,
                &h1,
                COMPACT_STATUS_DELTA_DATA,
            ),
        );
        append_hour(
            &mut reduced_raw,
            &mut rseq,
            base_hour + 2,
            &encode_delta(
                &h1,
                &h2,
                COMPACT_STATUS_DELTA_DATA,
            ),
        );
        append_hour(
            &mut reduced_raw,
            &mut rseq,
            base_hour + 3,
            &encode_delta(&h2, &h3, COMPACT_STATUS_DELTA_DATA),
        );

        for raw in [&full_raw, &reduced_raw] {
            let summary = summarize_compact_stream(raw);
            assert!(
                summary.parse_errors.is_empty(),
                "{:?}",
                summary.parse_errors
            );
        }

        let full_snapshots = fold_compact_snapshots(&full_raw)
            .into_iter()
            .map(canonicalize_projected_d53)
            .collect::<Vec<_>>();
        let reduced_snapshots = fold_compact_snapshots(&reduced_raw)
            .into_iter()
            .map(canonicalize_projected_d53)
            .collect::<Vec<_>>();
        assert_eq!(full_snapshots.len(), 4);
        assert_eq!(reduced_snapshots.len(), 4);
        for (full, reduced) in full_snapshots.iter().zip(&reduced_snapshots) {
            assert_eq!(
                canonicalize_json(reduced),
                canonicalize_json(full),
                "reduced d53 delta stream must fold to the same semantic rows as full emission"
            );
        }

        // ---- EMPTY-FIRST-FRAME regression (Codex finding 3/4) ----
        // A session whose first success frame carries ZERO rows must still seed an
        // (empty) baseline on both sides; the next non-empty frame is a delta vs
        // that empty baseline. The bug dropped those rows at fold time.
        {
            let e0 = WorldState::default();
            let e1 = WorldState {
                opinions: [((1, 2), 5), ((1, 3), 7)].into_iter().collect(),
                countries: [(1, 100)].into_iter().collect(),
                ..Default::default()
            };
            let mut fr = Vec::new();
            let mut rr = Vec::new();
            let (mut fs, mut rs) = (1u64, 1u64);
            // FULL: empty(partial) baseline, then full partial reads.
            append_hour(
                &mut fr,
                &mut fs,
                base_hour,
                &encode_full(&e0, 0),
            );
            append_hour(
                &mut fr,
                &mut fs,
                base_hour + 1,
                &encode_full(&e1, 0),
            );
            append_hour(
                &mut fr,
                &mut fs,
                base_hour + 2,
                &encode_full(&e1, 0),
            );
            // REDUCED: empty(partial) baseline seeds; then DELTA|PARTIAL vs empty.
            append_hour(
                &mut rr,
                &mut rs,
                base_hour,
                &encode_full(&e0, 0),
            );
            let dp = COMPACT_STATUS_DELTA_DATA;
            append_hour(&mut rr, &mut rs, base_hour + 1, &encode_delta(&e0, &e1, dp));
            append_hour(&mut rr, &mut rs, base_hour + 2, &encode_delta(&e1, &e1, dp));
            let fsn = fold_compact_snapshots(&fr)
                .into_iter()
                .map(canonicalize_projected_d53)
                .collect::<Vec<_>>();
            let rsn = fold_compact_snapshots(&rr)
                .into_iter()
                .map(canonicalize_projected_d53)
                .collect::<Vec<_>>();
            assert_eq!(fsn.len(), 3);
            for (full, reduced) in fsn.iter().zip(&rsn) {
                assert_eq!(
                    canonicalize_json(reduced),
                    canonicalize_json(full),
                    "empty-first-frame: reduced folds identically (rows must not vanish at H1/H2)"
                );
            }
        }

        // ---- Randomized property test (gate b): fuzz change sequences ----
        // A tiny deterministic LCG drives the mutations; a test-side collector-sim
        // produces the reduced stream exactly as the real collector would (diff vs
        // pinned baseline, tombstone-all, advance-baseline only on clean frames).
        struct Rng(u64);
        impl Rng {
            fn next(&mut self) -> u64 {
                self.0 = self
                    .0
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                self.0 >> 16
            }
            fn below(&mut self, n: u64) -> u64 {
                self.next() % n
            }
        }

        for seed in 0..48u64 {
            let mut rng = Rng(seed.wrapping_mul(0x9E3779B97F4A7C15).wrapping_add(1));
            let mut truth = WorldState::default();
            // A pinned collector baseline that advances only on clean frames, plus a
            // "seen a clean baseline yet" flag mirroring the collector/fold.
            let mut baseline: Option<WorldState> = None;

            let mut full_raw = Vec::new();
            let mut reduced_raw = Vec::new();
            let mut fseq = 1u64;
            let mut rseq = 1u64;
            let mut hour = base_hour;
            let mut expected_snaps = 0usize;

            let hours = 6 + rng.below(6) as i32;
            for _ in 0..hours {
                // Mutate the ground truth: a handful of add/change/delete ops.
                let ops = 1 + rng.below(5);
                for _ in 0..ops {
                    let fam = rng.below(4);
                    let del = rng.below(3) == 0;
                    match fam {
                        0 => {
                            let t = 1 + rng.below(4) as u32;
                            if del {
                                truth.countries.remove(&t);
                            } else {
                                truth.countries.insert(t, rng.below(500) as i64);
                            }
                        }
                        1 => {
                            let s = 1 + rng.below(4) as u32;
                            let tg = 1 + rng.below(4) as u32;
                            if s == tg {
                                continue;
                            }
                            if del {
                                truth.opinions.remove(&(s, tg));
                            } else {
                                truth.opinions.insert((s, tg), rng.below(400) as i32 - 200);
                            }
                        }
                        2 => {
                            let o = 1 + rng.below(4) as u32;
                            let h = 0xa0 + rng.below(4) as u32;
                            if del {
                                truth.state_events.remove(&(o, h));
                            } else {
                                truth.state_events.insert((o, h), rng.below(9000) as i64);
                            }
                        }
                        _ => {
                            let o = 1 + rng.below(4) as u32;
                            let s = 1 + rng.below(4) as u32;
                            if o == s {
                                continue;
                            }
                            if del {
                                truth.subjects.remove(&(o, s));
                            } else {
                                // autonomy_state_hash must be nonzero for a live row.
                                truth.subjects.insert((o, s), rng.below(100) as u32 + 1);
                            }
                        }
                    }
                }

                // Frame is partial ~2 in 3, INCLUDING the first frame — the first
                // frame is always emitted in full and seeds the baseline even when
                // partial (mirrors the collector's deep-war all-partial cold start).
                // D53 is production-complete: partial captures fail admission
                // instead of participating in the losslessness comparison.
                // Exercise the ordinary exact FULL-vs-DELTA carrier paths.
                let is_partial = false;
                let full_status = 0;
                let full_payload = encode_full(&truth, full_status);

                let reduced_payload = match &baseline {
                    // First frame: full emission (may carry the partial bit).
                    None => encode_full(&truth, full_status),
                    Some(b) => {
                        let status = COMPACT_STATUS_DELTA_DATA;
                        encode_delta(b, &truth, status)
                    }
                };
                // Seed on the first frame regardless; afterwards advance the pinned
                // baseline only on non-partial (clean) frames.
                if baseline.is_none() || !is_partial {
                    baseline = Some(truth.clone());
                }

                append_hour(&mut full_raw, &mut fseq, hour, &full_payload);
                append_hour(&mut reduced_raw, &mut rseq, hour, &reduced_payload);
                hour += 1;
                expected_snaps += 1;
            }

            let full_snaps = fold_compact_snapshots(&full_raw);
            let reduced_snaps = fold_compact_snapshots(&reduced_raw);
            assert_eq!(full_snaps.len(), expected_snaps, "seed {seed}");
            // DECODED-ROW EQUALITY (plan G1: "byte-identical per-hour snapshots OR
            // decoded-row equality"). The world-overlay row Vecs (subjects/wars) and
            // per-country Vecs are rendered in upsert/append order, which the delta
            // projection reaches by a different path than a full replace — so the
            // SET of rows is identical but the array ORDER can differ. That ordering
            // is a pre-existing, semantically-irrelevant property of the delta
            // projection (shared with the already-shipped pure-delta path), so
            // canonicalize array order before comparing: this proves every array
            // carries exactly the same rows (no loss, no duplication, no corruption)
            // hour for hour.
            for (idx, (f, r)) in full_snaps.iter().zip(reduced_snaps.iter()).enumerate() {
                let (cf, cr) = (
                    canonicalize_projected_d53(f.clone()),
                    canonicalize_projected_d53(r.clone()),
                );
                assert_eq!(
                    cf, cr,
                    "seed {seed} hour {idx}: reduced-partial d53 delta must fold to the same rows as full emission"
                );
            }
        }
    }

