    #[test]
    fn write_control_file_round_trips_profile_and_sidecar() {
        let dir = std::env::temp_dir().join(format!(
            "battle-plan-recorder_host_control_rt_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        let cfg = parse_args(profile_test_args(&dir, &["--profile", "debug"])).unwrap();
        write_control_file(&cfg, "tok", None).unwrap();
        let control = fs::read_to_string(dir.join("collector_control.json")).unwrap();

        assert!(
            control.contains("\"profile\":\"debug\""),
            "control: {control}"
        );
        assert!(control.contains("\"sidecar_log\":true"));
        assert!(control.contains("\"extraction_perf_gate\":true"));
        assert!(control.contains("\"d53_emit_mode\":\"delta\""));
        assert!(control.contains("\"d51_emit_mode\":\"delta\""));
        assert!(control.contains("\"d41_emit_mode\":\"delta\""));
        assert!(control.contains("\"d44_emit_mode\":\"delta\""));
        assert!(control.contains("\"d48_emit_mode\":\"delta\""));
        // Default (no explicit flag) resolves to `offsets`, matching the DLL's
        // implicit default, so production behavior is unchanged.
        assert!(control.contains("\"d53_relation_read_mode\":\"offsets\""));
        assert!(control.contains("\"compact_country_frame\":false"));
        assert!(control.contains("\"stream_format\":\"compact\""));
        assert!(control.contains("\"scheduled_snapshot_step_hours\":1"));
        assert!(!control.contains("\"control_challenge\""));

        let challenge = [0xabu8; 16];
        write_control_file(&cfg, "tok", Some(challenge)).unwrap();
        let duplex = fs::read_to_string(dir.join("collector_control.json")).unwrap();
        assert!(duplex.contains(&format!(
            "\"control_challenge\":\"{}\"",
            to_hex(&challenge)
        )));

        // No profile is resolved to the host's legacy debug-mode settings; JSON
        // null is never emitted because the collector rejects it as malformed.
        let cfg_legacy = parse_args(profile_test_args(&dir, &[])).unwrap();
        write_control_file(&cfg_legacy, "tok", None).unwrap();
        let legacy = fs::read_to_string(dir.join("collector_control.json")).unwrap();
        assert!(legacy.contains("\"profile\":\"debug\""), "legacy: {legacy}");
        assert!(!legacy.contains("\"domain57_game_speed_gate\""));
        assert!(!legacy.contains("\"profile\":null"), "legacy: {legacy}");
        assert!(
            !legacy.contains("\"scheduled_domains\":null"),
            "legacy: {legacy}"
        );
        for domain_id in 10..=17 {
            assert!(
                legacy.contains(compact_domain_name(domain_id)),
                "legacy roster missing domain {domain_id}: {legacy}"
            );
        }
        assert!(legacy.contains("\"sidecar_log\":false"));
        assert!(legacy.contains("\"d53_relation_read_mode\":\"offsets\""));
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn d53_relation_read_mode_parses_and_writes_shadow() {
        assert_eq!(
            D53RelationReadMode::parse("offsets"),
            Some(D53RelationReadMode::Offsets)
        );
        assert_eq!(
            D53RelationReadMode::parse("scan"),
            Some(D53RelationReadMode::Scan)
        );
        assert_eq!(
            D53RelationReadMode::parse("shadow"),
            Some(D53RelationReadMode::Shadow)
        );
        assert_eq!(D53RelationReadMode::parse("bogus"), None);
        assert_eq!(D53RelationReadMode::Shadow.as_str(), "shadow");

        // Default when the flag is absent stays `offsets`.
        let dir =
            std::env::temp_dir().join(format!("battle-plan-recorder_host_d53rrm_{}", std::process::id()));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        let cfg_default = parse_args(profile_test_args(&dir, &[])).unwrap();
        assert_eq!(
            cfg_default.d53_relation_read_mode,
            D53RelationReadMode::Offsets
        );

        // Explicit --d53-relation-read-mode shadow flows into the control file.
        let cfg_shadow = parse_args(profile_test_args(
            &dir,
            &["--d53-relation-read-mode", "shadow"],
        ))
        .unwrap();
        assert_eq!(
            cfg_shadow.d53_relation_read_mode,
            D53RelationReadMode::Shadow
        );
        write_control_file(&cfg_shadow, "tok", None).unwrap();
        let control = fs::read_to_string(dir.join("collector_control.json")).unwrap();
        assert!(
            control.contains("\"d53_relation_read_mode\":\"shadow\""),
            "control: {control}"
        );

        // An invalid value is a hard parse error, never a silent fallback.
        assert!(parse_args(profile_test_args(
            &dir,
            &["--d53-relation-read-mode", "nope"],
        ))
        .is_err());
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn prefetch_dist_overrides_parse_and_write_control() {
        let dir = std::env::temp_dir().join(format!(
            "battle-plan-recorder_host_prefetch_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();

        // Absent flags -> None -> `null` in the control file, so the DLL keeps
        // its env/default distances (parse_json_u32 yields None for null).
        let cfg_default = parse_args(profile_test_args(&dir, &[])).unwrap();
        assert_eq!(cfg_default.prefetch_dist_relation, None);
        assert_eq!(cfg_default.prefetch_dist_candidates, None);
        write_control_file(&cfg_default, "tok", None).unwrap();
        let control = fs::read_to_string(dir.join("collector_control.json")).unwrap();
        assert!(
            control.contains("\"prefetch_dist_relation\":null"),
            "control: {control}"
        );
        assert!(control.contains("\"prefetch_dist_candidates\":null"));

        // Explicit values flow into the control file verbatim, including the
        // meaningful 0 (prefetch OFF) — every live-sweep arm must be expressible.
        let cfg_set = parse_args(profile_test_args(
            &dir,
            &[
                "--prefetch-dist-relation",
                "8",
                "--prefetch-dist-candidates",
                "0",
            ],
        ))
        .unwrap();
        assert_eq!(cfg_set.prefetch_dist_relation, Some(8));
        assert_eq!(cfg_set.prefetch_dist_candidates, Some(0));
        write_control_file(&cfg_set, "tok", None).unwrap();
        let control = fs::read_to_string(dir.join("collector_control.json")).unwrap();
        assert!(
            control.contains("\"prefetch_dist_relation\":8"),
            "control: {control}"
        );
        assert!(control.contains("\"prefetch_dist_candidates\":0"));

        // Garbage is a hard parse error, never a silent fallback.
        assert!(parse_args(profile_test_args(&dir, &["--prefetch-dist-relation", "x"])).is_err());
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn production_profile_summary_populates_mismatch_lists() {
        let cfg = test_config(
            vec!["fuel_live", "country_identity", "unknown_future"],
            None,
        );
        let summary = build_production_profile_summary(&cfg);

        assert!(
            !summary.profile_domains_not_scheduled.contains(&"fuel_live"),
            "scheduled profile domain should not be reported missing"
        );
        assert!(
            summary
                .profile_domains_not_scheduled
                .contains(&"land_combat_detail_events_live"),
            "unscheduled profile domain should be visible"
        );
        assert_eq!(
            summary.scheduled_domains_not_in_profile,
            vec!["unknown_future".to_string()]
        );

        let manifest_block = summary.as_json();
        assert_eq!(
            manifest_block["scheduled_domains_not_in_profile"],
            json!(["unknown_future"])
        );
        assert!(manifest_block["profile_domains_not_scheduled"]
            .as_array()
            .unwrap()
            .iter()
            .any(|value| value.as_str() == Some("land_combat_detail_events_live")));
    }

