    fn static_artifact_shape_request(name: &'static str) -> StaticArtifactRequest {
        StaticArtifactRequest {
            name,
            path: PathBuf::from(format!("{name}.json")),
            expected_sha256: None,
        }
    }

    fn assert_object_keys(value: &Value, expected: &[&str]) {
        let object = value.as_object().expect("expected JSON object");
        let actual: BTreeSet<&str> = object.keys().map(String::as_str).collect();
        let expected: BTreeSet<&str> = expected.iter().copied().collect();
        assert_eq!(actual, expected);
    }

    fn expect_invalid_static_artifact_shape(
        name: &'static str,
        catalog: Value,
        expected_detail: &str,
    ) {
        let request = static_artifact_shape_request(name);
        let err = validate_static_artifact_shape(&request, &catalog)
            .expect_err("catalog should be rejected");
        assert!(
            err.contains(expected_detail) && err.contains(name),
            "error should name artifact and expected detail {expected_detail:?}: {err}"
        );
    }

    fn container_index_static_artifacts(container: &Container) -> Vec<Value> {
        // The typed Index does not model static_artifacts, so re-read the verified
        // index bytes to inspect the top-level roster.
        let game_id = container.game_id().to_string();
        let bytes = container
            .read_entry_bytes(&format!("payload/{game_id}/index.json"))
            .unwrap();
        let index: Value = serde_json::from_slice(&bytes).unwrap();
        index
            .get("static_artifacts")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default()
    }

    #[test]
    fn new_static_artifact_shapes_pass_and_provenance_is_whitelisted() {
        let cases: Vec<(&'static str, Value, Vec<&str>)> = vec![
            (
                STATIC_ARTIFACT_DECISIONS_STATIC_DEFINITIONS,
                fake_decisions_static_catalog(),
                vec![
                    "category_count",
                    "category_files_parsed",
                    "category_files_total",
                    "decision_count",
                    "decision_files_parsed",
                    "decision_files_total",
                    "decision_mapped",
                    "decision_omitted_no_loc_key",
                ],
            ),
            (
                STATIC_ARTIFACT_IDEA_TECH_LOC_XREF_STATIC,
                fake_idea_tech_loc_xref_static_catalog(),
                vec![
                    "idea_count",
                    "idea_files_parsed",
                    "idea_files_total",
                    "idea_mapped",
                    "idea_omitted_no_loc_key",
                    "tech_count",
                    "tech_files_parsed",
                    "tech_files_total",
                ],
            ),
            (
                STATIC_ARTIFACT_SHIP_DEFINITIONS_STATIC,
                fake_ship_definitions_static_catalog(),
                vec![
                    "equipment_files_parsed",
                    "equipment_files_total",
                    "module_files_parsed",
                    "module_files_total",
                    "ship_hull_count",
                    "ship_module_count",
                ],
            ),
            (
                STATIC_ARTIFACT_GFX_ICON_MANIFEST,
                fake_gfx_icon_manifest_catalog(),
                vec![
                    "sprites",
                    "flag_assets",
                    "interface_gfx_files",
                    "interface_gfx_files_parsed",
                    "missing_textures",
                    "allowed_missing_textures",
                    "unresolved_textures",
                    "unused_missing_texture_allowlist_entries",
                ],
            ),
            (
                STATIC_ARTIFACT_TECHNOLOGY_SHARING_STATIC,
                fake_technology_sharing_static_catalog(),
                vec![
                    "definition_count",
                    "source_files_parsed",
                    "source_files_total",
                    "categories_absent_unrestricted_count",
                    "categories_explicit_nonempty_count",
                    "categories_explicit_empty_unproven_count",
                    "runtime_token_proof",
                    "runtime_hash_proof",
                ],
            ),
            (
                STATIC_ARTIFACT_FOCUS_DEFS_STATIC,
                fake_focus_defs_static_catalog(),
                vec![
                    "tree_count",
                    "focus_count",
                    "shared_focus_count",
                    "joint_focus_count",
                    "focus_background_style_count",
                    "files_parsed",
                ],
            ),
        ];

        for (name, catalog, meta_fields) in cases {
            // The GFX manifest joins no localisation; every other new artifact
            // carries a whitelisted localisation_source block.
            let has_localisation_source = name != STATIC_ARTIFACT_GFX_ICON_MANIFEST;
            let request = static_artifact_shape_request(name);
            validate_static_artifact_shape(&request, &catalog).unwrap();
            let provenance = artifact_provenance(&request, &catalog).unwrap();
            let mut expected_top: Vec<&str> = vec![
                "artifact_kind",
                "artifact_sha256",
                "meta",
                "mod_identity_layers",
                "schema",
            ];
            if has_localisation_source {
                expected_top.push("localisation_source");
            }
            assert_object_keys(&provenance, &expected_top);
            assert_object_keys(&provenance["meta"], &meta_fields);
            if has_localisation_source {
                assert_object_keys(
                    &provenance["localisation_source"],
                    &["key_count", "sha256", "source"],
                );
            }

            let provenance_text = serde_json::to_string(&provenance).unwrap();
            for dropped in [
                "\"path\":",
                "\"source_files\":",
                "unlisted_top_level",
                "warnings",
                r"C:\Users",
                "SteamLibrary",
            ] {
                assert!(
                    !provenance_text.contains(dropped),
                    "{name} provenance leaked dropped field/string {dropped}: {provenance_text}"
                );
            }
        }
    }

    #[test]
    fn new_static_artifact_shapes_reject_schema_empty_objects_and_noninteger_counts() {
        for (name, catalog) in fake_new_static_catalogs() {
            let mut wrong_schema = catalog.clone();
            wrong_schema["schema"] = json!("wrong.static_artifact.v1");
            expect_invalid_static_artifact_shape(name, wrong_schema, "field schema expected");

            let mut empty_required_object = catalog.clone();
            let mut noninteger_count = catalog.clone();
            let (expected_empty_detail, expected_noninteger_detail) = match name {
                STATIC_ARTIFACT_DECISIONS_STATIC_DEFINITIONS => {
                    empty_required_object["decisions"] = json!({});
                    noninteger_count["meta"]["decision_count"] = json!("1");
                    (
                        "field decisions must be a non-empty JSON object",
                        "must be an integer",
                    )
                }
                STATIC_ARTIFACT_IDEA_TECH_LOC_XREF_STATIC => {
                    empty_required_object["tokens"]["ideas"] = json!({});
                    empty_required_object["tokens"]["technologies"] = json!({});
                    noninteger_count["meta"]["idea_count"] = json!("1");
                    (
                        "field tokens must contain at least one idea or technology token",
                        "must be an integer",
                    )
                }
                STATIC_ARTIFACT_SHIP_DEFINITIONS_STATIC => {
                    empty_required_object["ship_hulls"] = json!({});
                    noninteger_count["meta"]["ship_hull_count"] = json!("1");
                    (
                        "field ship_hulls must be a non-empty JSON object",
                        "must be an integer",
                    )
                }
                STATIC_ARTIFACT_GFX_ICON_MANIFEST => {
                    empty_required_object["sprites"] = json!({});
                    noninteger_count["meta"]["sprites"] = json!("1");
                    (
                        "field sprites must be a non-empty JSON object",
                        "must be a non-negative integer",
                    )
                }
                STATIC_ARTIFACT_TECHNOLOGY_SHARING_STATIC => {
                    empty_required_object["definitions"] = json!({});
                    noninteger_count["meta"]["definition_count"] = json!("1");
                    (
                        "technology-sharing artifact requires definitions",
                        "must be an integer",
                    )
                }
                STATIC_ARTIFACT_FOCUS_DEFS_STATIC => {
                    empty_required_object["trees"] = json!({});
                    noninteger_count["meta"]["tree_count"] = json!("1");
                    (
                        "field trees must be a non-empty JSON object",
                        "must be an integer",
                    )
                }
                _ => unreachable!(),
            };
            expect_invalid_static_artifact_shape(
                name,
                empty_required_object,
                expected_empty_detail,
            );
            expect_invalid_static_artifact_shape(
                name,
                noninteger_count,
                expected_noninteger_detail,
            );
        }
    }

    #[test]
    fn gfx_icon_manifest_rejects_non_gate_passing_states() {
        let name = STATIC_ARTIFACT_GFX_ICON_MANIFEST;

        let mut unresolved = fake_gfx_icon_manifest_catalog();
        unresolved["meta"]["unresolved_textures"] = json!(3);
        expect_invalid_static_artifact_shape(
            name,
            unresolved,
            "meta.unresolved_textures must be 0",
        );

        let mut stale_allowlist = fake_gfx_icon_manifest_catalog();
        stale_allowlist["meta"]["unused_missing_texture_allowlist_entries"] = json!(1);
        expect_invalid_static_artifact_shape(
            name,
            stale_allowlist,
            "meta.unused_missing_texture_allowlist_entries must be 0",
        );

        let mut parse_gap = fake_gfx_icon_manifest_catalog();
        parse_gap["meta"]["interface_gfx_files_parsed"] = json!(1);
        expect_invalid_static_artifact_shape(
            name,
            parse_gap,
            "meta.interface_gfx_files_parsed must equal meta.interface_gfx_files",
        );

        let mut unaccounted_missing = fake_gfx_icon_manifest_catalog();
        unaccounted_missing["meta"]["missing_textures"] = json!(7);
        expect_invalid_static_artifact_shape(
            name,
            unaccounted_missing,
            "meta.missing_textures must equal meta.allowed_missing_textures",
        );

        let mut flags_not_array = fake_gfx_icon_manifest_catalog();
        flags_not_array["flags"] = json!({});
        expect_invalid_static_artifact_shape(name, flags_not_array, "flags must be a JSON array");

        // Negative and above-i64::MAX counts must be rejected outright, never
        // allowed to make two invalid values compare equal.
        let mut negative_counts = fake_gfx_icon_manifest_catalog();
        negative_counts["meta"]["missing_textures"] = json!(-1);
        negative_counts["meta"]["allowed_missing_textures"] = json!(-1);
        expect_invalid_static_artifact_shape(
            name,
            negative_counts,
            "meta.missing_textures must be a non-negative integer",
        );

        let mut oversized_counts = fake_gfx_icon_manifest_catalog();
        oversized_counts["meta"]["interface_gfx_files"] = json!(u64::MAX);
        oversized_counts["meta"]["interface_gfx_files_parsed"] = json!(u64::MAX - 1);
        let request = static_artifact_shape_request(name);
        let err = validate_static_artifact_shape(&request, &oversized_counts)
            .expect_err("mismatched oversized counts must be rejected");
        assert!(
            err.contains("interface_gfx_files"),
            "oversized count mismatch must fail on the parity check: {err}"
        );
    }

    #[test]
    fn new_static_artifact_layers_accept_root_or_root_name_and_reject_missing_identity() {
        for (name, catalog) in fake_new_static_catalogs() {
            let mut root_name_only = catalog.clone();
            root_name_only["layers"] =
                json!([{ "label": "mod", "replace_path": [], "root_name": "test" }]);
            let request = static_artifact_shape_request(name);
            validate_static_artifact_shape(&request, &root_name_only).unwrap();
            let provenance = artifact_provenance(&request, &root_name_only).unwrap();
            assert_eq!(
                provenance["mod_identity_layers"][0]["root_basename"],
                json!("test")
            );

            let mut root_only = catalog.clone();
            root_only["layers"] = json!([{ "label": "mod", "replace_path": [], "root": r"C:\Users\Example\Documents\mod\test" }]);
            validate_static_artifact_shape(&request, &root_only).unwrap();
            let provenance = artifact_provenance(&request, &root_only).unwrap();
            assert_eq!(
                provenance["mod_identity_layers"][0]["root_basename"],
                json!("test")
            );

            // An empty "root" must not shadow a valid "root_name": validation
            // passes via root_name, so provenance must carry root_name too
            // (never root_basename: "").
            let mut empty_root_with_root_name = catalog.clone();
            empty_root_with_root_name["layers"] =
                json!([{ "label": "mod", "replace_path": [], "root": "", "root_name": "test" }]);
            validate_static_artifact_shape(&request, &empty_root_with_root_name).unwrap();
            let provenance = artifact_provenance(&request, &empty_root_with_root_name).unwrap();
            assert_eq!(
                provenance["mod_identity_layers"][0]["root_basename"],
                json!("test")
            );

            let mut missing_root = catalog.clone();
            missing_root["layers"] = json!([{ "label": "mod", "replace_path": [] }]);
            expect_invalid_static_artifact_shape(name, missing_root, "root or root_name");

            let mut missing_label = catalog;
            missing_label["layers"] = json!([{ "replace_path": [], "root_name": "test" }]);
            expect_invalid_static_artifact_shape(name, missing_label, "layers[0].label");
        }
    }

