        fs::write(&loc_path, &loc_bytes).unwrap();
        fs::write(&decisions_path, &decisions_bytes).unwrap();
        fs::write(&idea_tech_path, &idea_tech_bytes).unwrap();
        fs::write(&ship_path, &ship_bytes).unwrap();
        fs::write(&gfx_path, &gfx_bytes).unwrap();
